    ...
```
Hmm, that's Lua 5.1's lua.c. But here we see no "lua: " prefix for interactive errors, and "progname: " prefix for script errors. LuaJIT's main.c differs: it has

```c
static int report(lua_State *L, int status)
{
  if (status && !lua_isnil(L, -1)) {
    const char *msg = lua_tostring(L, -1);
    if (msg == NULL) msg = "(error object is not a string)";
    fputs(msg, stderr);
    fputc('\n', stderr);
    lua_pop(L, 1);
  }
  return status;
}
```
