/* Core object model, GC, string interning, tables and small API helpers. */
#include "lua.h"
#include <stdarg.h>
#include <ctype.h>
#include <float.h>
#include <errno.h>

#define MAX(a,b) ((a)>(b)?(a):(b))

/* -------------------------------------------------------- global state --- */
static GCObject *allobjects = NULL;
static size_t heapsize = 0;
static int gcrunning = 1;
static size_t gcstep = 0;
static int gccounter = 0;

/* string table */
#define STRTAB_INIT 1024
static Str **strtab = NULL;
static uint32_t strtabsize = 0;
static uint32_t strtabcount = 0;

static uint32_t str_hash(const char *s, size_t len)
{
  /* FNV-ish hash like LuaJIT's string hashing */
  uint32_t h = (uint32_t)len;
  size_t i;
  for (i = 0; i < len; i++) {
    h = h ^ ((uint8_t)s[i] << ((i & 3) * 8));
    h = (h << 5) - h + (uint8_t)s[i];   /* h*33 + c */
  }
  return h ? h : 1;
}

void *luaP_malloc(size_t n)
{
  void *p = malloc(n ? n : 1);
  if (!p) { fprintf(stderr, "not enough memory\n"); exit(1); }
  heapsize += n;
  return p;
}

static void *zalloc(size_t n) { void *p = luaP_malloc(n); memset(p, 0, n); return p; }

/* ------------------------------------------------------------- values ---- */
Val nilV(void)   { Val v; v.t = TAG_NIL;   v.u.g = NULL; return v; }
Val trueV(void)  { Val v; v.t = TAG_TRUE;  v.u.g = NULL; return v; }
Val falseV(void) { Val v; v.t = TAG_FALSE; v.u.g = NULL; return v; }
Val numV(double d){ Val v; v.t = TAG_NUM;  v.u.n = d; return v; }
Val boolV(int b) { return b ? trueV() : falseV(); }
Val tabV(Table *t){ Val v; v.t = TAG_TAB; v.u.g = (GCObject*)t; return v; }
Val strV(Str *s) { Val v; v.t = TAG_STR; v.u.g = (GCObject*)s; return v; }
Val funV(Func *f){ Val v; v.t = TAG_FUN; v.u.g = (GCObject*)f; return v; }
Val udV(UData *u){ Val v; v.t = TAG_UDATA; v.u.g = (GCObject*)u; return v; }
Val cdV(CData *c){ Val v; v.t = TAG_CDATA; v.u.g = (GCObject*)c; return v; }
Val upV(UpVal *u){ Val v; v.t = TAG_UPVAL; v.u.g = (GCObject*)u; return v; }
Table *tabV2(Val v) { return v.t == TAG_TAB ? (Table*)v.u.g : NULL; }
Str *strV2(Val v)   { return v.t == TAG_STR ? (Str*)v.u.g : NULL; }
Func *funV2(Val v)  { return v.t == TAG_FUN ? (Func*)v.u.g : NULL; }
UData *udV2(Val v)  { return v.t == TAG_UDATA ? (UData*)v.u.g : NULL; }
CData *cdV2(Val v)  { return v.t == TAG_CDATA ? (CData*)v.u.g : NULL; }
int istrue(Val v)   { return v.t != TAG_NIL && v.t != TAG_FALSE; }
int isfalse(Val v)  { return v.t == TAG_NIL || v.t == TAG_FALSE; }
int numtobool(double d) { return d != 0 && d == d; }

int val_equal(Val a, Val b)
{
  if (a.t != b.t) return 0;
  if (a.t == TAG_NUM) return a.u.n == b.u.n;
  return a.u.g == b.u.g;
}

uint32_t val_hash(Val v)
{
  switch (v.t) {
  case TAG_NIL: case TAG_FALSE: case TAG_TRUE: return (uint32_t)(v.t + 1);
  case TAG_NUM: {
    double d = v.u.n;
    if (d == 0) return 1;
    {
      /* hash the double bits */
      union { double d; uint64_t u; } x;
      x.d = d;
      uint32_t h = (uint32_t)(x.u ^ (x.u >> 32));
      h ^= h >> 16; h *= 0x5bd1e995u; h ^= h >> 13;
      return h ? h : 1;
    }
  }
  case TAG_STR: { Str *s = strV2(v); return s->hash; }
  default: {
    uintptr_t p = (uintptr_t)v.u.g;
    uint32_t h = (uint32_t)(p >> 3);
    h ^= h >> 16; h *= 0x5bd1e995u; h ^= h >> 13;
    return h ? h : 1;
  }
  }
}

/* -------------------------------------------------------------- strings --- */
static void strtab_init(void)
{
  uint32_t i;
  strtabsize = STRTAB_INIT;
  strtab = (Str**)zalloc(sizeof(Str*) * strtabsize);
  for (i = 0; i < strtabsize; i++) strtab[i] = NULL;
}

static void strtab_resize(void)
{
  uint32_t ns = strtabsize * 2, i;
  Str **nt = (Str**)zalloc(sizeof(Str*) * ns);
  for (i = 0; i < strtabsize; i++) {
    Str *s = strtab[i], *nx;
    while (s) { uint32_t h = s->hash & (ns - 1); nx = (Str*)s->next; s->next = (GCObject*)nt[h]; nt[h] = s; s = nx; }
  }
  luaP_free_nofree:
  free(strtab);
  strtab = nt;
  strtabsize = ns;
}

Str *luaP_newstr(Thread *L, const char *s, size_t len)
{
  uint32_t h;
  Str *e;
  if (!strtab) strtab_init();
  h = str_hash(s, len);
  e = strtab[h & (strtabsize - 1)];
  while (e) {
    if (e->hash == h && e->len == len && memcmp(e->data, s, len) == 0) return e;
    e = (Str*)e->next;
  }
  if (strtabcount + 1 > strtabsize) strtab_resize();
  e = (Str*)zalloc(sizeof(Str) + len);
  e->tt = TAG_STR;
  e->len = (uint32_t)len;
  e->hash = h;
  memcpy(e->data, s, len);
  e->data[len] = 0;
  e->next = (GCObject*)strtab[h & (strtabsize - 1)];
  strtab[h & (strtabsize - 1)] = e;
  strtabcount++;
  e->marked = 0;
  e->next = NULL;   /* strings are never collected: not in allobjects */
  return e;
}

/* ------------------------------------------------------------- numbers ---- */
void num2str(double d, char *buf)
{
  if (isnan(d)) { strcpy(buf, "nan"); return; }
  if (isinf(d)) { strcpy(buf, d > 0 ? "inf" : "-inf"); return; }
  snprintf(buf, 40, "%.14g", d);
}

int str2num(const char *s, size_t len, double *out)
{
  /* Built-in conversion: decimal, hexadecimal (incl. hex floats). */
  const char *p = s, *e = s + len;
  int neg = 0, got = 0;
  double val;
  while (p < e && (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r' ||
		   *p == '\v' || *p == '\f')) p++;
  if (p >= e) return 0;
  if (*p == '+') p++;
  else if (*p == '-') { neg = 1; p++; }
  if (p >= e) return 0;
  if (*p == '0' && (p + 1 < e) && (p[1] == 'x' || p[1] == 'X')) {
    p += 2;
    if (p >= e) return 0;
    val = 0;
    while (p < e) {
      int c = (uint8_t)*p;
      int d;
      if (c >= '0' && c <= '9') d = c - '0';
      else if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
      else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
      else break;
      val = val * 16 + d;
      p++; got = 1;
    }
    if (!got) return 0;
    if (p < e && (*p == '.' || *p == 'p' || *p == 'P')) {
      /* hex fraction / exponent */
      double frac = 0, scale = 1.0/16.0;
      if (*p == '.') {
	p++;
	while (p < e) {
	  int c = (uint8_t)*p;
	  if (c >= '0' && c <= '9') frac += (c - '0') * scale;
	  else if (c >= 'a' && c <= 'f') frac += (c - 'a' + 10) * scale;
	  else if (c >= 'A' && c <= 'F') frac += (c - 'A' + 10) * scale;
	  else break;
	  scale /= 16.0;
	  p++;
	}
      }
      val += frac;
      if (p < e && (*p == 'p' || *p == 'P')) {
	int eneg = 0, eval = 0;
	p++;
	if (p < e && (*p == '+' || *p == '-')) { eneg = (*p == '-'); p++; }
	while (p < e && *p >= '0' && *p <= '9') { eval = eval * 10 + (*p - '0'); p++; }
	while (eval--) { if (eneg) val /= 2; else val *= 2; }
      }
    }
  } else {
    double ipart = 0;
    int intgot = 0;
    while (p < e && *p >= '0' && *p <= '9') { ipart = ipart * 10 + (*p - '0'); p++; intgot = 1; got = 1; }
    if (p < e && *p == '.') {
      double frac = 0, scale = 0.1;
      p++;
      while (p < e && *p >= '0' && *p <= '9') { frac += (*p - '0') * scale; scale /= 10; p++; }
      val = ipart + frac;
      if (!intgot && p > s && p[-1] == '.') got = 1;
    } else val = ipart;
    if (p < e && (*p == 'e' || *p == 'E')) {
      int eneg = 0;
      double eval = 0, mul = 1;
      const char *q = p + 1;
      if (q < e && (*q == '+' || *q == '-')) { eneg = (*q == '-'); q++; }
      if (q >= e || !(*q >= '0' && *q <= '9')) return 0;
      while (q < e && *q >= '0' && *q <= '9') { eval = eval * 10 + (*q - '0'); q++; }
      while (eval >= 1) { if (eval >= 1024) { mul *= 1e308; eval -= 1024; } else { mul *= 10; eval -= 1; } }
      val *= eneg ? 1/mul : mul;
      p = q;
    }
  }
  while (p < e && (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r' ||
		   *p == '\v' || *p == '\f')) p++;
  if (p != e) return 0;
  *out = neg ? -val : val;
  return 1;
}

/* ------------------------------------------------------------- tables ----- */
static Val *node_alloc(Thread *L, uint32_t n)
{
  HashNode *h = (HashNode*)zalloc(sizeof(HashNode) * n);
  Val *v = (Val*)h;
  (void)v;
  return (Val*)h;
}

void table_resize(Thread *L, Table *t, uint32_t narr, uint32_t nhash)
{
  HashNode *oldnode = (HashNode*)t->node;
  uint32_t oldnodemask = t->nodemask, oldnodeused = t->nodeused;
  uint32_t oldarraycap = t->arraycap;
  Val *oldarray = t->array;
  uint32_t i;
  /* count how many array entries to keep */
  if (nhash < 2) nhash = 2;
  /* find the next power of two >= nhash */
  { uint32_t s = 2; while (s < nhash) s <<= 1; nhash = s; }
  t->node = NULL; t->nodemask = 0; t->array = NULL; t->arraycap = 0;
  t->arrayused = 0;
  if (narr > 0) {
    t->array = (Val*)zalloc(sizeof(Val) * narr);
    t->arraycap = narr;
    for (i = 0; i < narr; i++) t->array[i] = nilV();
  }
  /* rehash: first the array part entries from the old array */
  if (oldarray) {
    for (i = 0; i < oldarraycap && i < narr; i++) {
      if (!isfalse(oldarray[i]) && oldarray[i].t != TAG_NIL)
	t->array[i] = oldarray[i];
    }
    for (i = narr; i < oldarraycap; i++) {
      if (!isfalse(oldarray[i]) && oldarray[i].t != TAG_NIL) {
	Val k = numV((double)(i + 1));
	Val v = oldarray[i];
	/* insert into the hash part */
	{ uint32_t hv = val_hash(k) & (nhash - 1);
	  for (;;) {
	    HashNode *n = (HashNode*)t->node;
	    (void)n; hv = (hv + 1) & (nhash - 1); break;
	  }
	}
	t->nodeused++;  /* placeholder; proper insertion below */
      }
    }
  }
  (void)oldnode; (void)oldnodemask; (void)oldnodeused;
  if (nhash > 0) {
    t->node = (HashNode*)node_alloc(L, nhash);
    t->nodemask = nhash - 1;
    for (i = 0; i < nhash; i++) {
      t->node[i].key = nilV();
      t->node[i].val = nilV();
    }
    t->nodeused = 0;
    t->firstfree = nhash - 1;
  }
  /* now re-insert everything properly */
  t->nodeused = 0;
  if (oldarray) {
    for (i = 0; i < oldarraycap; i++) {
      if (oldarray[i].t != TAG_NIL) {
	if (i < narr) t->array[i] = oldarray[i];
	else {
	  Val k = numV((double)(i + 1));
	  uint32_t hv = val_hash(k) & t->nodemask;
	  for (;;) {
	    HashNode *n = &t->node[hv];
	    if (n->key.t == TAG_NIL) { n->key = k; n->val = oldarray[i]; t->nodeused++; break; }
	    hv = (hv + 1) & t->nodemask;
	  }
	}
      }
    }
  }
  if (oldnode) {
    for (i = 0; i <= oldnodemask; i++) {
      if (oldnode[i].key.t != TAG_NIL) {
	Val k = oldnode[i].key, v = oldnode[i].val;
	Val *slot = NULL;
	if (k.t == TAG_NUM) {
	  double d = k.u.n;
	  int64_t ii = (int64_t)d;
	  if (d >= 1 && d == (double)ii && ii <= (int64_t)t->arraycap) {
	    t->array[ii-1] = v;
	    goto done_ins;
	  }
	}
	{ uint32_t hv = val_hash(k) & t->nodemask;
	  for (;;) {
	    HashNode *n = &t->node[hv];
	    if (n->key.t == TAG_NIL) { n->key = k; n->val = v; t->nodeused++; break; }
	    hv = (hv + 1) & t->nodemask;
	  }
	}
      done_ins: ;
      }
    }
