static void rehash(Thread *L, Table *t)
{
  uint32_t nhash = t->nodeused * 2 + 2;
  uint32_t narr = t->arraycap;
  /* count how many integer keys should go to the array part */
  { uint32_t i, cnt = 0, maxidx = 0;
    if (t->node) {
      for (i = 0; i <= t->nodemask; i++) {
	if (t->node[i].key.t == TAG_NUM) {
	  double d = t->node[i].key.u.n;
	  if (d >= 1 && d == floor(d) && d <= 1e9) {
	    int64_t ii = (int64_t)d;
	    if (ii > maxidx) maxidx = (uint32_t)ii;
	    cnt++;
	  }
	}
      }
    }
    if (cnt > 0) {
      uint32_t s = 1;
      while (s < maxidx && s * 2 <= (cnt * 2 + 4)) s <<= 1;
      if (s > narr) narr = s;
    }
  }
  table_resize(L, t, narr, nhash);
}

Table *luaP_newtable(Thread *L)
{
  Table *t = (Table*)zalloc(sizeof(Table));
  t->tt = TAG_TAB;
  t->next = allobjects;
  allobjects = (GCObject*)t;
  t->node = (HashNode*)node_alloc(L, 2);
  t->nodemask = 1;
  t->node[0].key = nilV(); t->node[0].val = nilV();
  t->node[1].key = nilV(); t->node[1].val = nilV();
  t->firstfree = 1;
  t->mt = nilV();
  return t;
}

static Val *hash_find(Table *t, Val key)
{
  uint32_t hv = val_hash(key) & t->nodemask;
  for (;;) {
    HashNode *n = &t->node[hv];
    if (n->key.t == TAG_NIL) return NULL;
    if (n->key.t == key.t && (n->key.t == TAG_NUM ? n->key.u.n == key.u.n : n->key.u.g == key.u.g))
      return &n->val;
    hv = (hv + 1) & t->nodemask;
  }
}

Val *table_get(Table *t, Val key)
{
  if (key.t == TAG_NUM) {
    double d = key.u.n;
    if (d >= 1 && d == floor(d)) {
      int64_t i = (int64_t)d;
      if (i <= (int64_t)t->arraycap) {
	Val *v = &t->array[i-1];
	if (v->t != TAG_NIL) return v;
	return NULL;
      }
    }
    if (key.u.n != key.u.n) return NULL;   /* NaN */
  }
  if (!t->node) return NULL;
  return hash_find(t, key);
}

Val table_getstr(Table *t, Str *s)
{
  Val key = strV(s);
  Val *v = table_get(t, key);
  return v ? *v : nilV();
}

void table_seti(Thread *L, Table *t, int64_t i, Val val)
{
  Val key = numV((double)i);
  table_set(L, t, key, val);
}

Val table_geti(Table *t, int64_t i)
{
  Val key = numV((double)i);
  Val *v = table_get(t, key);
  return v ? *v : nilV();
}

void table_set(Thread *L, Table *t, Val key, Val val)
{
  Val *v;
  if (key.t == TAG_NIL) { luaP_errormsg(L, "table index is nil"); }
  if (key.t == TAG_NUM && key.u.n != key.u.n) { luaP_errormsg(L, "table index is NaN"); }
  v = table_get(t, key);
  if (v) { *v = val; return; }
  if (key.t == TAG_NUM) {
    double d = key.u.n;
    if (d >= 1 && d == floor(d) && d < 1e9) {
      int64_t i = (int64_t)d;
      if (i <= (int64_t)t->arraycap) {
	t->array[i-1] = val;
	if (val.t == TAG_NIL) { /* shrink? */ }
	return;
      }
      if (i == (int64_t)t->arraycap + 1) {
	uint32_t na = t->arraycap;
	while (na < i && na < 1u<<24) na *= 2;
	table_resize(L, t, na, t->nodeused + 2);
	t->array[i-1] = val;
	return;
      }
    }
  }
  { uint32_t hv = val_hash(key) & t->nodemask;
    for (;;) {
      HashNode *n = &t->node[hv];
      if (n->key.t == TAG_NIL) {
	if (t->nodeused + 1 > (t->nodemask + 1) / 2) {
	  table_set(L, t, key, val);   /* rehash will reinsert */
	  rehash(L, t);
	  return;
	}
	n->key = key; n->val = val; t->nodeused++;
	return;
      }
      hv = (hv + 1) & t->nodemask;
    }
  }
}

void table_setstr(Thread *L, Table *t, Str *s, Val v)
{
  table_set(L, t, strV(s), v);
}

int64_t table_getn(Table *t)
{
  int64_t j = t->arraycap;
  if (j > 0 && t->array[j-1].t == TAG_NIL) {
    /* binary search */
    int64_t i = 0;
    while (j - i > 1) { int64_t m = (i + j) / 2; if (t->array[m-1].t == TAG_NIL) j = m; else i = m; }
    return i;
  } else {
    /* check the hash part for arraycap+1 */
    Val k = numV((double)(t->arraycap + 1));
    Val *v = t->node ? hash_find(t, k) : NULL;
    if (v && v->t != TAG_NIL) {
      int64_t i = t->arraycap + 1;
      while (1) {
	i++;
	{ Val k2 = numV((double)i);
	  Val *v2 = t->node ? hash_find(t, k2) : NULL;
	  if (!v2 || v2->t == TAG_NIL) return i - 1;
