}

int table_next(Table *t, Val key, Val *outkey, Val *outval)
{
  if (key.t == TAG_NIL) {
    uint32_t i;
    for (i = 0; i < t->arraycap; i++) {
      if (t->array[i].t != TAG_NIL) { *outkey = numV((double)(i+1)); *outval = t->array[i]; return 1; }
    }
    if (t->node) {
      uint32_t i2;
      for (i2 = 0; i2 <= t->nodemask; i2++) {
	if (t->node[i2].key.t != TAG_NIL) { *outkey = t->node[i2].key; *outval = t->node[i2].val; return 1; }
      }
    }
    return 0;
  }
  if (key.t == TAG_NUM) {
    double d = key.u.n;
    if (d >= 1 && d == floor(d)) {
      int64_t i = (int64_t)d;
      if (i <= (int64_t)t->arraycap) {
	for (; i < (int64_t)t->arraycap; i++) {
	  if (t->array[i].t != TAG_NIL) { *outkey = numV((double)(i+1)); *outval = t->array[i]; return 1; }
	}
