	  uint32_t i2;
	  for (i2 = 0; i2 <= t->nodemask; i2++) {
	    if (t->node[i2].key.t != TAG_NIL) { *outkey = t->node[i2].key; *outval = t->node[i2].val; return 1; }
	  }
	}
	return 0;
      }
    }
  }
  if (t->node) {
    Val *v = hash_find(t, key);
    if (v) {
      HashNode *n = (HashNode*)v;
      uint32_t idx = (uint32_t)(n - t->node);
      uint32_t i;
      for (i = idx + 1; i <= t->nodemask; i++) {
	if (t->node[i].key.t != TAG_NIL) { *outkey = t->node[i].key; *outval = t->node[i].val; return 1; }
      }
    }
  }
  return 0;
}

void table_clear(Table *t)
{
