  if (p >= e) return 0;
  if (*p == '+') p++;
  else if (*p == '-') { neg = 1; p++; }
  if (p >= e) return 0;
  if (*p == '0' && (p + 1 < e) && (p[1] == 'x' || p[1] == 'X')) {
    p += 2;
    if (p >= e) return 0;
    val = 0;
    while (p < e) {
