/* ------------------------------------------------------------ GC --------- */
static void markval(Val v);
static void markobj(GCObject *o);

static void marktable(Table *t)
{
  uint32_t i;
  if (t->marked) return;
  t->marked = 1;
  markval(t->mt);
  if (t->array) for (i = 0; i < t->arraycap; i++) {
    Val v = t->array[i];
    if (v.t != TAG_NIL) markval(v);
  }
  if (t->node) for (i = 0; i <= t->nodemask; i++) {
    if (t->node[i].key.t != TAG_NIL) {
      markval(t->node[i].key);
      markval(t->node[i].val);
    }
  }
}

static void markobj(GCObject *o)
{
  if (o->marked) return;
  switch (o->tt) {
  case TAG_TAB: marktable((Table*)o); break;
  case TAG_FUN: {
    Func *f = (Func*)o;
    int i;
    f->marked = 1;
    if (f->proto) f->proto->marked = 1;
    for (i = 0; i < f->nuv; i++) if (f->upvals[i]) markobj((GCObject*)f->upvals[i]);
    break;
  }
  case TAG_UPVAL: {
    UpVal *u = (UpVal*)o;
    u->marked = 1;
    if (u->closed) markval(u->val);
    break;
  }
  case TAG_PROTO: {
    Proto *p = (Proto*)o;
    int i;
    p->marked = 1;
    if (p->source) p->source->marked = 1;
    for (i = 0; i < p->nk; i++) markval(p->k[i]);
    break;
  }
  case TAG_UDATA: {
    UData *u = (UData*)o;
    u->marked = 1;
    markval(u->mt);
    break;
  }
  case TAG_CDATA: {
    CData *c = (CData*)o;
    c->marked = 1;
    markval(c->mt);
    markval(c->ctype);
    break;
  }
  case TAG_THREAD: {
    Thread *t = (Thread*)o;
    int i;
    t->marked = 1;
    for (i = 0; i < t->top; i++) markval(t->stack[i]);
    if (t->env) marktable(t->env);
    markval(t->co);
    break;
  }
  }
}

static void markval(Val v)
{
  if (v.t == TAG_NIL || v.t == TAG_TRUE || v.t == TAG_FALSE) return;
  if (v.t == TAG_NUM) return;
  markobj(v.u.g);
}

typedef struct GCList { void *obj; struct GCList *next; } GCList;

static void gc_call_finalizers(void)
{
  /* tables with __gc metamethod that are unreachable: collected list */
  GCList *list = NULL, *l;
  GCObject *o, *n;
  uint32_t i;
  for (o = allobjects; o; o = o->next) {
    if (!o->marked && o->tt == TAG_TAB) {
      Table *t = (Table*)o;
      Val mt = t->mt;
      Table *m = tabV2(mt);
      if (m && m->node) {
	Val k = strV(luaP_newstr(NULL, "__gc", 4));
	Val *v = table_get(m, k);
	if (v && v->t != TAG_NIL && v->t != TAG_FALSE) {
	  l = (GCList*)malloc(sizeof(GCList));
	  l->obj = o; l->next = list; list = l;
	}
      }
    }
  }
  /* run the finalizers */
  for (l = list; l; l = l->next) {
    Table *t = (Table*)l->obj;
    Val mt = t->mt;
    Table *m = tabV2(mt);
    if (m) {
      Val k = strV(luaP_newstr(NULL, "__gc", 4));
      Val *v = table_get(m, k);
      if (v && v->t != TAG_NIL && v->t != TAG_FALSE) {
	extern void lj_callgcfunc(Thread *L, Val f, Val obj);
	Thread *mth = NULL;
	/* Use the main thread for the callback */
	if (allthreads) mth = allthreads;
	if (mth) lj_callgcfunc(mth, *v, tabV(t));
      }
    }
  }
  while (list) { l = list; list = list->next; free(l); }
  /* purge weak tables */
  for (o = allobjects; o; o = n) {
    n = o->next;
    if (o->tt == TAG_TAB) {
      Table *t = (Table*)o;
      if (t->weakmode) {
	if (t->array) for (i = 0; i < t->arraycap; i++) {
	  Val v = t->array[i];
	  if (v.t != TAG_NIL) {
	    if (t->weakmode & 1) { GCObject *ov = v.u.g; if (ov && !ov->marked) t->array[i] = nilV(); }
	    if (t->weakmode & 2) { GCObject *ov = v.u.g; if (ov && !ov->marked) t->array[i] = nilV(); }
	  }
	}
	if (t->node) for (i = 0; i <= t->nodemask; i++) {
	  Val k = t->node[i].key;
	  if (k.t == TAG_NIL) continue;
	  if (t->weakmode & 1) { GCObject *ok = k.u.g; if (ok && !ok->marked) { t->node[i].key = nilV(); t->node[i].val = nilV(); t->nodeused--; } }
	  else if (t->weakmode & 2) { GCObject *ov = t->node[i].val.u.g; if (ov && !ov->marked) { t->node[i].key = nilV(); t->node[i].val = nilV(); t->nodeused--; } }
	}
      }
    }
  }
}

void lj_gc_collect(Thread *L)
{
  GCObject *o, **pp;
  int i;
  /* mark */
  for (o = allobjects; o; o = o->next) o->marked = 0;
  for (o = (GCObject*)allthreads; o; o = o->nextthread)
    markobj(o);
  if (lj_registry) marktable(lj_registry);
  for (i = 0; i < nextraroots; i++) markval(extraroots[i]);
  gc_call_finalizers();
  /* sweep */
  pp = &allobjects;
  for (o = allobjects; o; o = *pp) {
    if (!o->marked) {
      *pp = o->next;
      switch (o->tt) {
      case TAG_TAB: { Table *t = (Table*)o; free(t->array); if (t->node) free(t->node); heapsize -= sizeof(Table); free(o); break; }
      case TAG_FUN: { Func *f = (Func*)o; if (f->upvals) free(f->upvals); heapsize -= sizeof(Func); free(o); break; }
      case TAG_UPVAL: heapsize -= sizeof(UpVal); free(o); break;
      case TAG_PROTO: { Proto *p = (Proto*)o; free(p->code); free(p->k); free(p->lineinfo); free(p->flags); free(p->uvnames); free(p->uvinfo); free(p->callinfo); heapsize -= sizeof(Proto); free(o); break; }
      case TAG_UDATA: { UData *u = (UData*)o; if (u->data) free(u->data); heapsize -= sizeof(UData); free(o); break; }
      case TAG_CDATA: { CData *c = (CData*)o; if (c->data) free(c->data); heapsize -= sizeof(CData); free(o); break; }
      }
    } else pp = &o->next;
  }
}

