/* ------------------------------------------------------------- values ---- */
Val nilV(void)   { Val v; v.t = TAG_NIL;   v.u.g = NULL; return v; }
Val trueV(void)  { Val v; v.t = TAG_TRUE;  v.u.g = NULL; return v; }
Val falseV(void) { Val v; v.t = TAG_FALSE; v.u.g = NULL; return v; }
Val numV(double d){ Val v; v.t = TAG_NUM;  v.u.n = d; return v; }
Val boolV(int b) { return b ? trueV() : falseV(); }
Val tabV(Table *t){ Val v; v.t = TAG_TAB; v.u.g = (GCObject*)t; return v; }
Val strV(Str *s) { Val v; v.t = TAG_STR; v.u.g = (GCObject*)s; return v; }
Val funV(Func *f){ Val v; v.t = TAG_FUN; v.u.g = (GCObject*)f; return v; }
Val udV(UData *u){ Val v; v.t = TAG_UDATA; v.u.g = (GCObject*)u; return v; }
Val cdV(CData *c){ Val v; v.t = TAG_CDATA; v.u.g = (GCObject*)c; return v; }
Val upV(UpVal *u){ Val v; v.t = TAG_UPVAL; v.u.g = (GCObject*)u; return v; }
Table *tabV2(Val v) { return v.t == TAG_TAB ? (Table*)v.u.g : NULL; }
Str *strV2(Val v)   { return v.t == TAG_STR ? (Str*)v.u.g : NULL; }
Func *funV2(Val v)  { return v.t == TAG_FUN ? (Func*)v.u.g : NULL; }
UData *udV2(Val v)  { return v.t == TAG_UDATA ? (UData*)v.u.g : NULL; }
CData *cdV2(Val v)  { return v.t == TAG_CDATA ? (CData*)v.u.g : NULL; }
int istrue(Val v)   { return v.t != TAG_NIL && v.t != TAG_FALSE; }
int isfalse(Val v)  { return v.t == TAG_NIL || v.t == TAG_FALSE; }
int numtobool(double d) { return d != 0 && d == d; }

int val_equal(Val a, Val b)
{
  if (a.t != b.t) return 0;
  if (a.t == TAG_NUM) return a.u.n == b.u.n;
  return a.u.g == b.u.g;
}

uint32_t val_hash(Val v)
{
  switch (v.t) {
  case TAG_NIL: case TAG_FALSE: case TAG_TRUE: return (uint32_t)(v.t + 1);
  case TAG_NUM: {
    double d = v.u.n;
    if (d == 0) return 1;
    { union { double d; uint64_t u; } x; uint32_t h;
      x.d = d; h = (uint32_t)(x.u ^ (x.u >> 32));
      h ^= h >> 16; h *= 0x5bd1e995u; h ^= h >> 13;
      return h ? h : 1; }
  }
  case TAG_STR: { Str *s = strV2(v); return s->hash; }
  default: {
    uintptr_t p = (uintptr_t)v.u.g; uint32_t h = (uint32_t)(p >> 3);
    h ^= h >> 16; h *= 0x5bd1e995u; h ^= h >> 13;
    return h ? h : 1; }
  }
}

/* -------------------------------------------------------------- strings --- */
#define STRTAB_INIT 1024
static Str **strtab = NULL;
static uint32_t strtabsize = 0, strtabcount = 0;

static uint32_t str_hash(const char *s, size_t len)
{
  uint32_t h = (uint32_t)len; size_t i;
  for (i = 0; i < len; i++) h = h ^ ((uint8_t)s[i] << ((i & 3) * 8));
  for (i = 0; i < len; i++) h = (h << 5) - h + (uint8_t)s[i];
  return h ? h : 1;
}

static void strtab_init(void)
{
  strtabsize = STRTAB_INIT;
  strtab = (Str**)zalloc(sizeof(Str*) * strtabsize);
}

static void strtab_resize(void)
{
  uint32_t ns = strtabsize * 2, i;
  Str **nt = (Str**)zalloc(sizeof(Str*) * ns);
  for (i = 0; i < strtabsize; i++) {
    Str *s = strtab[i], *nx;
    while (s) { uint32_t h = s->hash & (ns - 1); nx = (Str*)s->next; s->next = (GCObject*)nt[h]; nt[h] = s; s = nx; }
  }
  free(strtab);
  strtab = nt; strtabsize = ns;
}

Str *luaP_newstr(Thread *L, const char *s, size_t len)
{
  uint32_t h; Str *e;
  if (!strtab) strtab_init();
  h = str_hash(s, len);
  e = strtab[h & (strtabsize - 1)];
  while (e) {
    if (e->hash == h && e->len == len && memcmp(e->data, s, len) == 0) return e;
    e = (Str*)e->next;
  }
  if (strtabcount + 1 > strtabsize) strtab_resize();
  e = (Str*)zalloc(sizeof(Str) + len);
  e->tt = TAG_STR;
  e->len = (uint32_t)len;
  e->hash = h;
  memcpy(e->data, s, len);
  e->data[len] = 0;
  e->next = (GCObject*)strtab[h & (strtabsize - 1)];
  strtab[h & (strtabsize - 1)] = e;
  strtabcount++;
  return e;
}

/* ------------------------------------------------------------- numbers ---- */
void num2str(double d, char *buf)
{
  if (isnan(d)) { strcpy(buf, "nan"); return; }
  if (isinf(d)) { strcpy(buf, d > 0 ? "inf" : "-inf"); return; }
  snprintf(buf, 40, "%.14g", d);
}

/* ------------------------------------------------------------- tables ----- */
void table_resize(Thread *L, Table *t, uint32_t narr, uint32_t nhash)
{
  Val *oldarray = t->array;
  uint32_t oldarraycap = t->arraycap;
  HashNode *oldnode = (HashNode*)t->node;
  uint32_t oldnodemask = t->nodemask;
  uint32_t i, s;
  if (narr > 1024*1024) narr = 1024*1024;
  s = 2; while (s < nhash) s <<= 1; nhash = s;

  t->array = NULL; t->arraycap = 0; t->arrayused = 0;
  t->node = NULL; t->nodemask = 0; t->nodeused = 0; t->firstfree = 0;

  if (narr > 0) {
    t->array = (Val*)zalloc(sizeof(Val) * narr);
    t->arraycap = narr;
    for (i = 0; i < narr; i++) t->array[i] = nilV();
  }
  if (nhash > 0) {
    t->node = (HashNode*)zalloc(sizeof(HashNode) * nhash);
    t->nodemask = nhash - 1;
    for (i = 0; i < nhash; i++) { t->node[i].key = nilV(); t->node[i].val = nilV(); }
    t->firstfree = nhash - 1;
  }

#define PUT(v, k) do { Val _v = (v); \
    if (_v.t != TAG_NIL) { \
      if ((k).t == TAG_NUM) { double _d = (k).u.n; \
	if (_d >= 1 && _d == floor(_d)) { int64_t _i = (int64_t)_d; \
	  if (_i >= 1 && _i <= (int64_t)t->arraycap) { t->array[_i-1] = _v; goto nxt; } } } \
      { uint32_t _hv = val_hash((k)) & t->nodemask; \
	for (;;) { HashNode *_n = &t->node[_hv]; \
	  if (_n->key.t == TAG_NIL) { _n->key = (k); _n->val = _v; t->nodeused++; break; } \
	  _hv = (_hv + 1) & t->nodemask; } } \
    } nxt: ; } while (0)

  if (oldarray) {
    for (i = 0; i < oldarraycap; i++) {
      if (oldarray[i].t != TAG_NIL)
	PUT(oldarray[i], numV((double)(i+1)));
    }
  }
  if (oldnode) {
    for (i = 0; i <= oldnodemask; i++) {
      if (oldnode[i].key.t != TAG_NIL)
	PUT(oldnode[i].val, oldnode[i].key);
    }
  }
#undef PUT
  if (oldarray) free(oldarray);
  if (oldnode) free(oldnode);
}

static void rehash(Thread *L, Table *t)
{
  uint32_t nhash = t->nodeused * 2 + 4;
  uint32_t narr = t->arraycap;
  uint32_t i, cnt = 0, maxidx = 0;
  if (t->node) {
    for (i = 0; i <= t->nodemask; i++) {
      if (t->node[i].key.t == TAG_NUM) {
	double d = t->node[i].key.u.n;
	if (d >= 1 && d == floor(d) && d < 1e9) {
	  uint32_t ii = (uint32_t)d;
	  if (ii > maxidx) maxidx = ii;
	  cnt++;
	}
      }
    }
  }
  if (cnt > 0) {
    uint32_t s = 1;
    while (s < maxidx && s < cnt * 4 + 4) s <<= 1;
    if (s > narr) narr = s;
  }
  table_resize(L, t, narr, nhash);
}

Table *luaP_newtable(Thread *L)
{
  Table *t = (Table*)zalloc(sizeof(Table));
  t->tt = TAG_TAB;
  t->next = allobjects;
  allobjects = (GCObject*)t;
  t->mt = nilV();
  t->node = (HashNode*)zalloc(sizeof(HashNode) * 2);
  t->nodemask = 1;
  t->node[0].key = nilV(); t->node[0].val = nilV();
  t->node[1].key = nilV(); t->node[1].val = nilV();
  t->firstfree = 1;
  return t;
}

static Val *hash_find(Table *t, Val key)
{
  uint32_t hv = val_hash(key) & t->nodemask;
  for (;;) {
    HashNode *n = &t->node[hv];
    if (n->key.t == TAG_NIL) return NULL;
    if (n->key.t == key.t && (n->key.t == TAG_NUM ? n->key.u.n == key.u.n : n->key.u.g == key.u.g))
      return &n->val;
    hv = (hv + 1) & t->nodemask;
  }
}

Val *table_get(Table *t, Val key)
{
  if (key.t == TAG_NUM) {
    double d = key.u.n;
    if (d != d) return NULL;
    if (d >= 1 && d == floor(d)) {
      int64_t i = (int64_t)d;
      if (i <= (int64_t)t->arraycap) {
	Val *v = &t->array[i-1];
	if (v->t != TAG_NIL) return v;
	if (t->node) return hash_find(t, key);
	return NULL;
      }
    }
  }
  if (!t->node) return NULL;
  return hash_find(t, key);
}

Val table_getstr(Table *t, Str *s)
{
  Val key = strV(s), *v;
  v = table_get(t, key);
  return v ? *v : nilV();
}

void table_seti(Thread *L, Table *t, int64_t i, Val val)
{ table_set(L, t, numV((double)i), val); }

Val table_geti(Table *t, int64_t i)
{
  Val *v = table_get(t, numV((double)i));
  return v ? *v : nilV();
}

void table_set(Thread *L, Table *t, Val key, Val val)
{
  Val *v;
  if (key.t == TAG_NIL) luaP_errorstr(L, "table index is nil");
  if (key.t == TAG_NUM && key.u.n != key.u.n) luaP_errorstr(L, "table index is NaN");
  v = table_get(t, key);
  if (v) { *v = val; return; }
  for (;;) {
    if (key.t == TAG_NUM) {
      double d = key.u.n;
      if (d >= 1 && d == floor(d) && d < 1e9) {
	int64_t i = (int64_t)d;
	if (i <= (int64_t)t->arraycap) {
	  t->array[i-1] = val;
	  return;
	}
	if (i == (int64_t)t->arraycap + 1) {
	  uint32_t na = t->arraycap ? t->arraycap : 1;
	  while (na < (uint32_t)i && na < (1u<<24)) na *= 2;
	  table_resize(L, t, na, t->nodeused * 2 + 4);
	  continue;
	}
      }
    }
    { uint32_t hv = val_hash(key) & t->nodemask;
      for (;;) {
	HashNode *n = &t->node[hv];
	if (n->key.t == TAG_NIL) {
	  if (t->nodeused + 1 > (t->nodemask + 1) / 2) { rehash(L, t); break; }
	  n->key = key; n->val = val; t->nodeused++;
	  return;
	}
	hv = (hv + 1) & t->nodemask;
      }
    }
  }
}

void table_setstr(Thread *L, Table *t, Str *s, Val v) { table_set(L, t, strV(s), v); }

int64_t table_getn(Table *t)
{
  int64_t j = t->arraycap;
  if (j > 0 && t->array[j-1].t == TAG_NIL) {
    int64_t i = 0;
    while (j - i > 1) { int64_t m = (i + j) / 2; if (t->array[m-1].t == TAG_NIL) j = m; else i = m; }
    return i;
  } else {
    Val k = numV((double)(t->arraycap + 1));
    Val *v = t->node ? hash_find(t, k) : NULL;
    if (v && v->t != TAG_NIL) {
      int64_t i = t->arraycap + 1;
      for (;;) {
	i++;
	k = numV((double)i);
	v = t->node ? hash_find(t, k) : NULL;
	if (!v || v->t == TAG_NIL) return i - 1;
      }
    }
  }
  return t->arraycap;
}

int table_next(Table *t, Val key, Val *outkey, Val *outval)
{
  uint32_t i;
  if (key.t == TAG_NIL) {
    for (i = 0; i < t->arraycap; i++)
      if (t->array[i].t != TAG_NIL) { *outkey = numV((double)(i+1)); *outval = t->array[i]; return 1; }
    if (t->node) {
      for (i = 0; i <= t->nodemask; i++)
	if (t->node[i].key.t != TAG_NIL) { *outkey = t->node[i].key; *outval = t->node[i].val; return 1; }
    }
    return 0;
  }
  if (key.t == TAG_NUM) {
    double d = key.u.n;
    if (d >= 1 && d == floor(d)) {
      int64_t i = (int64_t)d;
      if (i <= (int64_t)t->arraycap) {
	for (; i < (int64_t)t->arraycap; i++)
	  if (t->array[i].t != TAG_NIL) { *outkey = numV((double)(i+1)); *outval = t->array[i]; return 1; }
	if (t->node) {
	  for (i = 0; i <= t->nodemask; i++)
	    if (t->node[i].key.t != TAG_NIL) { *outkey = t->node[i].key; *outval = t->node[i].val; return 1; }
	}
	return 0;
      }
    }
  }
  if (t->node) {
    Val *v = hash_find(t, key);
    if (v) {
      uint32_t idx = (uint32_t)(((HashNode*)v) - t->node);
      for (i = idx + 1; i <= t->nodemask; i++)
	if (t->node[i].key.t != TAG_NIL) { *outkey = t->node[i].key; *outval = t->node[i].val; return 1; }
    }
  }
  return 0;
}

void table_clear(Table *t)
{
  uint32_t i;
  if (t->array) for (i = 0; i < t->arraycap; i++) t->array[i] = nilV();
  if (t->node) for (i = 0; i <= t->nodemask; i++) { t->node[i].key = nilV(); t->node[i].val = nilV(); }
  t->nodeused = 0;
}

