Val tostringV(Thread *L, Val v)
{
  Str *s = tostrV(L, v);
  if (s) return strV(s);
  {
    Val mt = table_getmetatable(L, v);
    Table *m = tabV2(mt);
    if (m) {
      Val mm = table_metamethod(L, v, MM_TOSTRING);
      if (mm.t != TAG_NIL) {
	extern int lj_callmetamethod_tostring(Thread *L, Val obj, Val mm, Val *out);
	Val out;
	if (lj_callmetamethod_tostring(L, obj, mm, &out)) {
	  Str *s2 = tostrV(L, out);
	  if (s2) return strV(s2);
	}
      }
    }
  }
  return tostring_default(L, v);
}

Val tostring_default(Thread *L, Val v)
{
  char buf[80];
  switch (v.t) {
  case TAG_TAB: snprintf(buf, sizeof(buf), "table: %p", (void*)v.u.g); break;
  case TAG_FUN: snprintf(buf, sizeof(buf), "function: %p", (void*)v.u.g); break;
  case TAG_UDATA: snprintf(buf, sizeof(buf), "userdata: %p", (void*)v.u.g); break;
  case TAG_CDATA: snprintf(buf, sizeof(buf), "cdata: %p", (void*)v.u.g); break;
  case TAG_THREAD: snprintf(buf, sizeof(buf), "thread: %p", (void*)v.u.g); break;
  default: snprintf(buf, sizeof(buf), "?"); break;
  }
  return strV(luaP_newstr(L, buf, strlen(buf)));
}
