/* ------------------------------------------------------------ stack API -- */
#define CURBASE (L->nframes > 0 ? L->frames[L->nframes-1].base : 0)

int luaP_gettop(Thread *L) { return L->top - CURBASE; }
Val *luaP_index(Thread *L, int idx)
{
  if (idx > 0) { int i = CURBASE + idx - 1; if (i >= L->top) return &L->stack[L->top-1]; return &L->stack[i]; }
  if (idx == 0) return &L->stack[L->top];
  return &L->stack[L->top + idx];
}
Val luaP_get(Thread *L, int idx)
{
  if (idx > 0) { int i = CURBASE + idx - 1; if (i >= L->top) return nilV(); if (i < 0) return nilV(); return L->stack[i]; }
  if (idx == 0) return nilV();
  { int i = L->top + idx; if (i < CURBASE) return nilV(); return L->stack[i]; }
}
void luaP_settop(Thread *L, int idx)
{
  int n = CURBASE + idx;
  if (n < CURBASE) n = CURBASE;
  if (n < L->top) L->top = n;
  else { while (L->top < n) { L->stack[L->top] = nilV(); L->top++; } }
}
void luaP_pop(Thread *L) { L->top--; }
void luaP_popn(Thread *L, int n) { L->top -= n; }

static void stack_grow(Thread *L, int need)
{
  if (need > L->stacksize) {
    int ns = L->stacksize;
    Val *old = L->stack;
    while (ns < need) ns = ns * 2;
    if (ns > LUA_MAXSTACK) ns = LUA_MAXSTACK;
    if (ns < need) { lj_seterror(L, "stack overflow"); }
    L->stack = (Val*)luaP_malloc(sizeof(Val) * ns);
    memcpy(L->stack, old, sizeof(Val) * L->stacksize);
    { int i; for (i = L->stacksize; i < ns; i++) L->stack[i] = nilV(); }
    heapsize += sizeof(Val) * (ns - L->stacksize);
    free(old);
    L->stacksize = ns;
    /* fix open upvalues pointing into the stack */
    lj_fixupvals(L, old, L->stack);
  }
}

void luaP_checkstack(Thread *L, int n)
{
  if (L->top + n >= L->stacksize) stack_grow(L, L->top + n + 1);
}

void luaP_pushval(Thread *L, Val v)
{
  luaP_checkstack(L, 1);
  L->stack[L->top++] = v;
}
Val luaP_popval(Thread *L) { return L->stack[--L->top]; }
void luaP_pushnil(Thread *L)  { luaP_pushval(L, nilV()); }
