void luaP_pushcfunc(Thread *L, CFunction_ f, uint32_t id, const char *name)
{ luaP_pushval(L, funV(luaP_newcfunc(L, f, id, name))); }

/* -------------------------------------------------------------------- GC -- */
static void markval(Val v);
static void markobj(GCObject *o)
{ int i;
  if (o->marked) return;
  switch (o->tt) {
  case TAG_TAB: { Table *t = (Table*)o; uint32_t j;
    t->marked = 1; markval(t->mt);
    if (t->array) for (j = 0; j < t->arraycap; j++) markval(t->array[j]);
    if (t->node) for (j = 0; j <= t->nodemask; j++) if (t->node[j].key.t != TAG_NIL) {
      markval(t->node[j].key); markval(t->node[j].val); }
    break; }
  case TAG_FUN: { Func *f = (Func*)o; f->marked = 1;
    if (f->proto) f->proto->marked = 1;
    for (i = 0; i < f->nuv; i++) if (f->upvals[i]) markobj((GCObject*)f->upvals[i]);
    break; }
  case TAG_UPVAL: { UpVal *u = (UpVal*)o; u->marked = 1; if (u->closed) markval(u->val); break; }
  case TAG_PROTO: { Proto *p = (Proto*)o; int j; p->marked = 1;
    if (p->source) p->source->marked = 1;
    for (j = 0; j < p->nk; j++) markval(p->k[j]);
    break; }
  case TAG_UDATA: { UData *u = (UData*)o; u->marked = 1; markval(u->mt); break; }
  case TAG_CDATA: { CData *c = (CData*)o; c->marked = 1; markval(c->mt); markval(c->ctype); break; }
  case TAG_THREAD: { Thread *t = (Thread*)o; int j; t->marked = 1;
    for (j = 0; j < t->top; j++) markval(t->stack[j]);
    if (t->env) markobj((GCObject*)t->env);
    markval(t->co); break; }
  } }
static void markval(Val v) { if (v.t == TAG_NIL || v.t == TAG_TRUE || v.t == TAG_FALSE) return; if (v.t == TAG_NUM) return; markobj(v.u.g); }

typedef struct GCList { void *obj; struct GCList *next; } GCList;

void lj_callgcfunc(Thread *L, Val f, Val obj)
{ /* call f(obj) in protected mode */
  extern int lj_safe_call1(Thread *L, Val f, Val a1);
  lj_safe_call1(L, f, obj); }

static void gc_finalizers(void)
{ GCList *list = NULL, *l; GCObject *o; 
  for (o = allobjects; o; o = o->next) {
    if (!o->marked && (o->tt == TAG_TAB || o->tt == TAG_UDATA)) {
      Val mt = (o->tt == TAG_TAB) ? ((Table*)o)->mt : ((UData*)o)->mt;
      Table *m = tabV2(mt);
      if (m) { Val *v = table_getstr(m, luaP_newstr(NULL, "__gc", 4));
	if (v && istrue(*v)) { l = (GCList*)malloc(sizeof(GCList)); l->obj = o; l->next = list; list = l; } } } }
  for (l = list; l; l = l->next) {
    GCObject *o = (GCObject*)l->obj;
    Val mt = (o->tt == TAG_TAB) ? ((Table*)o)->mt : ((UData*)o)->mt;
    Table *m = tabV2(mt);
    if (m) { Val *v = table_getstr(m, luaP_newstr(NULL, "__gc", 4));
      if (v && istrue(*v) && allthreads) {
	Val obj = (o->tt == TAG_TAB) ? tabV((Table*)o) : udV((UData*)o);
	lj_callgcfunc(allthreads, *v, obj); } } }
  while (list) { l = list; list = list->next; free(l); } }

static void gc_weakpurge(void)
{ GCObject *o; uint32_t i;
  for (o = allobjects; o; o = o->next) {
    if (o->tt != TAG_TAB) continue;
    { Table *t = (Table*)o;
      if (!t->weakmode) continue;
      if (t->array) for (i = 0; i < t->arraycap; i++) {
	Val v = t->array[i];
	if (v.t != TAG_NIL && v.t != TAG_NUM && v.t != TAG_STR) {
	  GCObject *gv = v.u.g;
	  if (gv && !gv->marked) t->array[i] = nilV(); } }
      if (t->node) for (i = 0; i <= t->nodemask; i++) {
	Val k = t->node[i].key;
	if (k.t == TAG_NIL) continue;
	if ((t->weakmode & 1) && k.t != TAG_NUM && k.t != TAG_STR) {
	  GCObject *gk = k.u.g;
	  if (gk && !gk->marked) { t->node[i].key = nilV(); t->node[i].val = nilV(); t->nodeused--; }
	} else if (t->weakmode & 2) {
	  Val vv = t->node[i].val;
	  if (vv.t != TAG_NIL && vv.t != TAG_NUM && vv.t != TAG_STR) {
	    GCObject *gv = vv.u.g;
	    if (gv && !gv->marked) { t->node[i].key = nilV(); t->node[i].val = nilV(); t->nodeused--; }
	  }
	} } } }

void lj_gc_collect(Thread *L)
{ GCObject *o, **pp; int i;
  for (o = allobjects; o; o = o->next) o->marked = 0;
  for (o = (GCObject*)allthreads; o; o = o->nextthread) markobj(o);
  if (lj_registry) markobj((GCObject*)lj_registry);
  for (i = 0; i < nextraroots; i++) markval(extraroots[i]);
  gc_finalizers();
  gc_weakpurge();
  pp = &allobjects;
  for (o = allobjects; o; o = *pp) {
    if (!o->marked) {
      *pp = o->next;
      switch (o->tt) {
      case TAG_TAB: { Table *t = (Table*)o; free(t->array); if (t->node) free(t->node); heapsize -= sizeof(Table); free(o); break; }
      case TAG_FUN: { Func *f = (Func*)o; if (f->upvals) free(f->upvals); heapsize -= sizeof(Func); free(o); break; }
      case TAG_UPVAL: heapsize -= sizeof(UpVal); free(o); break;
      case TAG_PROTO: { Proto *p = (Proto*)o; free(p->code); free(p->k); free(p->lines); free(p->uvnames); free(p->uvinfo); free(p->callnamekind); free(p->callnamestr); heapsize -= sizeof(Proto); free(o); break; }
      case TAG_UDATA: { UData *u = (UData*)o; heapsize -= sizeof(UData); free(u->data); free(o); break; }
      case TAG_CDATA: { CData *c = (CData*)o; heapsize -= sizeof(CData); free(c->data); free(o); break; }
      default: free(o); break;
      }
    } else pp = &o->next;
  }
}
