/* ---------------------------------------------------------------- values -- */
Val nilV(void)   { Val v; v.t = TAG_NIL;   v.u.g = NULL; return v; }
Val trueV(void)  { Val v; v.t = TAG_TRUE;  v.u.g = NULL; return v; }
Val falseV(void) { Val v; v.t = TAG_FALSE; v.u.g = NULL; return v; }
Val numV(double d){ Val v; v.t = TAG_NUM;  v.u.n = d; return v; }
