Val tabV(Table *t){ Val v; v.t = TAG_TAB; v.u.g = (GCObject*)t; return v; }
Val strV(Str *s) { Val v; v.t = TAG_STR; v.u.g = (GCObject*)s; return v; }
Val funV(Func *f){ Val v; v.t = TAG_FUN; v.u.g = (GCObject*)f; return v; }
Val udV(UData *u){ Val v; v.t = TAG_UDATA; v.u.g = (GCObject*)u; return v; }
Val cdV(CData *c){ Val v; v.t = TAG_CDATA; v.u.g = (GCObject*)c; return v; }
Val upV(UpVal *u){ Val v; v.t = TAG_UPVAL; v.u.g = (GCObject*)u; return v; }
Table *tabV2(Val v) { return v.t == TAG_TAB ? (Table*)v.u.g : NULL; }
Str *strV2(Val v)   { return v.t == TAG_STR ? (Str*)v.u.g : NULL; }
Func *funV2(Val v)  { return v.t == TAG_FUN ? (Func*)v.u.g : NULL; }
UData *udV2(Val v)  { return v.t == TAG_UDATA ? (UData*)v.u.g : NULL; }
CData *cdV2(Val v)  { return v.t == TAG_CDATA ? (CData*)v.u.g : NULL; }
UpVal *upV2(Val v)  { return v.t == TAG_UPVAL ? (UpVal*)v.u.g : NULL; }
int istrue(Val v)   { return v.t != TAG_NIL && v.t != TAG_FALSE; }
int isfalse(Val v)  { return v.t == TAG_NIL || v.t == TAG_FALSE; }
int numtobool(double d) { return d != 0 && d == d; }

int val_equal(Val a, Val b)
{ if (a.t != b.t) return 0; if (a.t == TAG_NUM) return a.u.n == b.u.n; return a.u.g == b.u.g; }

uint32_t val_hash(Val v)
{
  switch (v.t) {
  case TAG_NIL: case TAG_FALSE: case TAG_TRUE: return (uint32_t)(v.t + 1);
  case TAG_NUM: { union { double d; uint64_t u; } x; uint32_t h;
    x.d = v.u.n; if (v.u.n == 0) return 1;
    h = (uint32_t)(x.u ^ (x.u >> 32)); h ^= h >> 16; h *= 0x5bd1e995u; h ^= h >> 13;
    return h ? h : 1; }
  case TAG_STR: return strV2(v)->hash;
  default: { uintptr_t p = (uintptr_t)v.u.g; uint32_t h = (uint32_t)(p >> 3);
    h ^= h >> 16; h *= 0x5bd1e995u; h ^= h >> 13; return h ? h : 1; }
  }
}

const char *luaP_typename(Val v)
