int lj_index(Thread *L, Val obj, Val key, Val *out)
{ /* returns 1 if *out was filled */
  if (obj.t == TAG_TAB) {
    Table *t = tabV2(obj);
    Val *v = table_get(t, key);
    if (v) { *out = *v; return 1; }
    /* no value: use __index */
    { Val mm = table_metamethod(L, obj, MM_INDEX);
      if (istrue(mm)) {
	if (mm.t == TAG_TAB || mm.t == TAG_FUN) {
	  if (mm.t == TAG_TAB) { Val *v2 = table_get(tabV2(mm), key);
	    if (v2) { *out = *v2; return 1; }
	    return 1; }
	  else { int top = L->top;
	    luaP_checkstack(L, 4);
	    luaP_pushval(L, mm); luaP_pushval(L, obj); luaP_pushval(L, key);
	    luaP_docall(L, L->top - 3, 2, 1, FRK_META, NULL);
	    *out = L->stack[L->top-1];
	    L->top = top;
	    return 1; } }
      } }
    *out = nilV();
    return 1; }
  if (obj.t == TAG_STR) {
    extern Table *lj_strmeta;
    if (lj_strmeta) { Val *v = table_get(lj_strmeta, key);
      if (v) { *out = *v; return 1; } }
    *out = nilV();
    return 1; }
  if (obj.t == TAG_UDATA || obj.t == TAG_CDATA) {
    Val mm = table_metamethod(L, obj, MM_INDEX);
    if (istrue(mm)) {
      if (mm.t == TAG_TAB) { Val *v2 = table_get(tabV2(mm), key);
	*out = v2 ? *v2 : nilV(); return 1; }
      else if (mm.t == TAG_FUN) { int top = L->top;
	luaP_checkstack(L, 4);
	luaP_pushval(L, mm); luaP_pushval(L, obj); luaP_pushval(L, key);
	luaP_docall(L, L->top - 3, 2, 1, FRK_META, NULL);
	*out = L->stack[L->top-1];
	L->top = top; return 1; } } }
  { char loc[300]; lj_getlocation(L, 1, loc, sizeof(loc));
    char buf[600]; buf[0] = 0;
    /* try to include the name */
    { uint8_t kind = FRK_NONE; Str *nm = NULL;
      if (L->nframes) { Frame *fr = topframe(L);
	if (lj_slotname(L, fr, -1, &kind, &nm)) { } } }
    snprintf(buf, sizeof(buf), "%sattempt to index a %s value", loc, luaP_typename(obj));
    luaP_errorstr(L, buf); }
  return 0; }

int lj_newindex(Thread *L, Val obj, Val key, Val val)
{ if (obj.t == TAG_TAB) {
    Table *t = tabV2(obj);
    Val *v = table_get(t, key);
    if (v) { *v = val; return 1; }
    { Val mm = table_metamethod(L, obj, MM_NEWINDEX);
      if (istrue(mm)) {
	if (mm.t == TAG_TAB) { table_set(L, tabV2(mm), key, val); return 1; }
	if (mm.t == TAG_FUN) { int top = L->top;
	  luaP_checkstack(L, 4);
	  luaP_pushval(L, mm); luaP_pushval(L, obj); luaP_pushval(L, key); luaP_pushval(L, val);
	  luaP_docall(L, L->top - 4, 3, 0, FRK_META, NULL);
	  L->top = top; return 1; } } }
    table_set(L, t, key, val);
    return 1; }
  { char loc[300]; lj_getlocation(L, 1, loc, sizeof(loc));
    char buf[600];
    snprintf(buf, sizeof(buf), "%sattempt to index a %s value", loc, luaP_typename(obj));
    luaP_errorstr(L, buf); }
  return 0; }
