/* Virtual machine: frames, calls, errors, tracebacks, coroutines, metamethods. */
#include "lua.h"
#include <ctype.h>
#include <float.h>
#include <errno.h>

/* ----------------------------------------------------------- opcodes ----- */
enum {
  OP_MOVE=0, OP_LOADK, OP_LOADBOOL, OP_LOADNIL, OP_GETUPVAL, OP_SETUPVAL,
  OP_GETTABUP, OP_GETTAB, OP_GETTABLE, OP_SETTABUP, OP_SETTAB, OP_SETTABLE,
  OP_NEWTABLE, OP_SETLIST, OP_ADD, OP_SUB, OP_MUL, OP_DIV, OP_MOD, OP_POW,
  OP_UNM, OP_NOT, OP_LEN, OP_CONCAT, OP_JMP, OP_TEST, OP_TESTSET, OP_EQ,
  OP_LT, OP_LE, OP_JTRUE, OP_JFALSE, OP_JEQ, OP_JNE, OP_JLT, OP_JLE,
  OP_CALL, OP_TAILCALL, OP_RETURN, OP_FORPREP, OP_FORLOOP,
  OP_TFORCALL, OP_TFORLOOP, OP_CLOSURE, OP_VARARG, OP_CLOSE, OP_NOP
};

/* ---------------------------------------------------------------- misc --- */
Thread *curthread = NULL;
typedef void (*ContFunc)(Thread *L, int status);
UpVal *openupvals_head = NULL;

static Frame *topframe(Thread *L) { return &L->frames[L->nframes-1]; }

const char *lj_curfuncname(Thread *L)
{ if (L->nframes == 0) return NULL;
  { Frame *fr = topframe(L); if (fr->name) return fr->name->data; }
  return NULL; }

void lj_fixupvals(Thread *L, Val *old, Val *newstack)
{ GCObject *o; int i;
  for (o = (GCObject*)allthreads_head(); o; o = o->nextthread) {
    Thread *t = (Thread*)o;
    if (t->stack != old) continue;
    for (i = 0; i < t->top; i++) {
      Val v = t->stack[i];
      if (v.t == TAG_UPVAL) { UpVal *u = upV2(v);
	if (u && !u->closed && u->v >= old && u->v < old + t->stacksize)
	  u->v = newstack + (u->v - old); } } } }

/* --------------------------------------------------------------- errors -- */
void luaP_error(Thread *L, Val msg)
{ luaP_checkstack(L, 2); L->stack[L->top++] = msg; err_throw(L); }

void err_throw(Thread *L)
{ ErrCtx *ctx = L->ectx;
  if (!ctx) {
    Val msg = L->stack[L->top-1];
    lj_report(L, msg);
    exit(1);
  }
  longjmp(ctx->jb, 2); }

int lj_yieldthrow(Thread *L)
{ ErrCtx *ctx = L->ectx;
  while (ctx) { if (ctx->catchyield) break; ctx = ctx->prev; }
  if (!ctx) return 0;
  longjmp(ctx->jb, 1);
  return 0; }

void luaP_errorstr(Thread *L, const char *msg)
{ luaP_error(L, strV(luaP_newstr(L, msg, strlen(msg)))); }

void luaP_errormsg(Thread *L, const char *fmt, ...)
{ char buf[2048]; va_list ap; va_start(ap, fmt); vsnprintf(buf, sizeof(buf), fmt, ap); va_end(ap);
  luaP_errorstr(L, buf); }

void luaP_errormsg2(Thread *L, int level, const char *fmt, ...)
{ char buf[2048], loc[300], buf2[2400]; va_list ap;
  va_start(ap, fmt); vsnprintf(buf, sizeof(buf), fmt, ap); va_end(ap);
  lj_getlocation(L, level, loc, sizeof(loc));
  if (loc[0]) { snprintf(buf2, sizeof(buf2), "%s%s", loc, buf); luaP_errorstr(L, buf2); }
  else luaP_errorstr(L, buf); }

void lj_getlocation(Thread *L, int level, char *out, size_t outlen)
{ int i, cnt = 0;
  out[0] = 0;
  for (i = L->nframes - 1; i >= 0; i--) {
    Frame *fr = &L->frames[i];
    if (fr->kind != FR_LUA) continue;
    cnt++;
    if (cnt == level) {
      Func *f = funV2(fr->func);
      if (f && f->proto) {
	int line = lj_lineof(f->proto, fr->pc);
	if (f->proto->source) snprintf(out, outlen, "%s:%d: ", f->proto->source->data, line);
	else snprintf(out, outlen, "?:%d: ", line);
      }
      return;
    } } }

int lj_protect(Thread *L, ErrCtx *ctx, int catchyield)
{ ctx->prev = L->ectx; ctx->catchyield = catchyield; ctx->L = L;
  L->ectx = ctx; return setjmp(ctx->jb); }

void lj_unprotect(Thread *L, ErrCtx *ctx) { L->ectx = ctx->prev; }

/* ------------------------------------------------------------- stack ----- */
void luaP_setupstack(Thread *L, int need)
{ if (L->top + need >= L->stacksize) {
    int ns = L->stacksize; Val *old = L->stack;
    while (ns < L->top + need + 1) ns *= 2;
    if (ns > LUA_MAXSTACK) {
      if (L->top + need + 1 > LUA_MAXSTACK) luaP_errorstr(L, "stack overflow");
      ns = LUA_MAXSTACK;
    }
    L->stack = (Val*)luaP_malloc(sizeof(Val)*ns);
    memcpy(L->stack, old, sizeof(Val)*L->stacksize);
    { int i; for (i = L->stacksize; i < ns; i++) L->stack[i] = nilV(); }
    free(old); L->stacksize = ns;
    lj_fixupvals(L, old, L->stack);
  } }

void luaP_checkstack(Thread *L, int n) { luaP_setupstack(L, n); }
void luaP_checkstack_co(Thread *L, int n) { luaP_setupstack(L, n); }

/* ------------------------------------------------------ metamethods ------ */
Table *metatableV(Val v)
{ switch (v.t) {
  case TAG_TAB: return tabV2(((Table*)v.u.g)->mt);
  case TAG_UDATA: return tabV2(((UData*)v.u.g)->mt);
  case TAG_CDATA: return tabV2(((CData*)v.u.g)->mt);
  case TAG_STR: { extern Table *lj_strmeta; return lj_strmeta; }
  case TAG_THREAD: { Thread *t = (Thread*)v.u.g; return tabV2(t->co); }
  }
  return NULL; }

Val table_metamethod(Thread *L, Val obj, int mm)
{ Table *mt = metatableV(obj);
  Val key, *v;
  if (!mt) return nilV();
  key = strV(luaP_newstr(L, lj_mmnames[mm], strlen(lj_mmnames[mm])));
  v = table_get(mt, key);
  if (!v) return nilV();
  return *v; }

static Val get_binmeta(Thread *L, Val a, Val b, int mm)
{ Val m = table_metamethod(L, a, mm);
  if (!istrue(m)) m = table_metamethod(L, b, mm);
  return m; }

int lj_tostring_meta(Thread *L, Val obj, Val *out)
{ Val mm = table_metamethod(L, obj, MM_TOSTRING);
  int top;
  if (!istrue(mm)) return 0;
  top = L->top;
  luaP_checkstack(L, 4);
  luaP_pushval(L, mm);
  luaP_pushval(L, obj);
  luaP_docall(L, L->top - 2, 1, 1, FRK_META, NULL);
  *out = L->stack[L->top-1];
  L->top = top;
  return 1; }

int lj_callmeta(Thread *L, Val obj, int mm, int nargs, int nres)
{ Val m = table_metamethod(L, obj, mm);
  int top, i;
  if (!istrue(m)) return 0;
  top = L->top;
  luaP_checkstack(L, nargs + 4);
  luaP_pushval(L, m);
  for (i = 0; i < nargs; i++) luaP_pushval(L, L->stack[top - nargs + i]);
  luaP_docall(L, L->top - nargs - 1, nargs, nres, FRK_META, NULL);
  L->top = top + nres;
  return 1; }

/* ----------------------------------------------------- slot name lookup -- */
int lj_slotname(Thread *L, Frame *fr, int reg, uint8_t *kind, Str **name)
{ Proto *p; int i, pc;
  Func *f;
  *kind = FRK_NONE; *name = NULL;
  if (fr->func.t != TAG_FUN) return 0;
  f = funV2(fr->func);
  if (!f || !f->proto) return 0;
  p = f->proto;
  pc = fr->pc;
  if (p->locslot) {
    for (i = 0; i < p->nlocs; i++) {
      if (p->locslot[i] == reg && pc >= p->locstart[i] && pc <= p->locend[i]) {
	*kind = FRK_LOCAL; *name = p->locname[i]; return 1; } } }
  if (pc > 0) {
    Ins *ins = &p->code[pc-1];
    if (ins->a == reg) {
      switch (ins->op) {
      case OP_GETTABUP: *kind = FRK_GLOBAL; *name = strV2(p->k[ins->c]); return 1;
      case OP_GETTAB: *kind = FRK_FIELD; *name = strV2(p->k[ins->c]); return 1;
      case OP_GETUPVAL: *kind = FRK_UPVAL; *name = p->uvnames[ins->b]; return 1;
      case OP_SELF: *kind = FRK_METHOD; *name = strV2(p->k[ins->c]); return 1;
      } } }
  return 0; }

static Str *opname(Thread *L, int reg, uint8_t *kind)
{ if (L->nframes == 0) { *kind = FRK_NONE; return NULL; }
  { Frame *fr = topframe(L);
    Str *nm = NULL; uint8_t k = FRK_NONE;
    if (lj_slotname(L, fr, reg, &k, &nm)) { *kind = k; return nm; } }
  *kind = FRK_NONE;
  return NULL; }

static const char *kindword(uint8_t kind)
{ switch (kind) {
  case FRK_LOCAL: return "local";
  case FRK_GLOBAL: return "global";
  case FRK_FIELD: return "field";
  case FRK_METHOD: return "method";
  case FRK_UPVAL: return "upvalue";
  }
  return NULL; }

static void throw_at(Thread *L, const char *msg)
{ char loc[300], buf[600];
  lj_getlocation(L, 1, loc, sizeof(loc));
  snprintf(buf, sizeof(buf), "%s%s", loc, msg);
  luaP_errorstr(L, buf); }

static void typeerror(Thread *L, int reg, const char *op, const char *t)
{ uint8_t kind = FRK_NONE; Str *nm = opname(L, reg, &kind);
  char buf[256];
  const char *kw = kindword(kind);
  if (nm && kw) snprintf(buf, sizeof(buf), "attempt to %s %s '%s' (%s value)", op, kw, nm->data, t);
  else snprintf(buf, sizeof(buf), "attempt to %s a %s value", op, t);
  throw_at(L, buf); }

/* -------------------------------------------------------- arith/compare -- */
static int arith_num(double a, double b, int op, double *out)
{ switch (op) {
  case MM_ADD: *out = a + b; return 1;
  case MM_SUB: *out = a - b; return 1;
  case MM_MUL: *out = a * b; return 1;
  case MM_DIV: *out = a / b; return 1;
  case MM_MOD: *out = lj_nummod(a, b); return 1;
  case MM_POW: *out = pow(a, b); return 1;
  }
  return 0; }

static int tonumberV(Val v, double *out)
{ if (v.t == TAG_NUM) { *out = v.u.n; return 1; }
  if (v.t == TAG_STR) { Str *s = strV2(v); return str2num(s->data, s->len, out); }
  return 0; }

int lj_arith(Thread *L, Val a, Val b, int op, Val *out, int rega, int regb)
{ double x, y, r;
  if (tonumberV(a, &x) && tonumberV(b, &y)) { arith_num(x, y, op, &r); *out = numV(r); return 1; }
  { Val m = get_binmeta(L, a, b, op);
    if (istrue(m)) {
      int top = L->top;
      luaP_checkstack(L, 4);
      luaP_pushval(L, m);
      luaP_pushval(L, a);
      luaP_pushval(L, b);
      luaP_docall(L, L->top - 3, 2, 1, FRK_META, NULL);
      *out = L->stack[L->top-1];
      L->top = top;
      return 1; } }
  { Val bad = a;
    int badreg = rega;
    if (a.t == TAG_NUM || (a.t == TAG_STR && tonumberV(a, &x))) { bad = b; badreg = regb; }
    if (badreg >= 0) typeerror(L, badreg, "perform arithmetic on", luaP_typename(bad));
    else { char buf[256];
      snprintf(buf, sizeof(buf), "attempt to perform arithmetic on a %s value", luaP_typename(bad));
      throw_at(L, buf); } }
  return 0; }

int lj_unm(Thread *L, Val a, Val *out, int rega)
{ if (a.t == TAG_NUM) { *out = numV(-a.u.n); return 1; }
  { Val m = table_metamethod(L, a, MM_UNM);
    if (istrue(m)) {
      int top = L->top;
      luaP_checkstack(L, 4);
      luaP_pushval(L, m); luaP_pushval(L, a);
      luaP_docall(L, L->top - 2, 1, 1, FRK_META, NULL);
      *out = L->stack[L->top-1];
      L->top = top; return 1; } }
  if (rega >= 0) typeerror(L, rega, "perform arithmetic on", luaP_typename(a));
  else { char buf[256];
    snprintf(buf, sizeof(buf), "attempt to perform arithmetic on a %s value", luaP_typename(a));
    throw_at(L, buf); }
  return 0; }

int lj_compare(Thread *L, Val a, Val b, int op, int *out)
{ if (a.t == TAG_NUM && b.t == TAG_NUM) { *out = (op == MM_LT) ? (a.u.n < b.u.n) : (a.u.n <= b.u.n); return 1; }
  if (a.t == TAG_STR && b.t == TAG_STR) {
    Str *sa = strV2(a), *sb = strV2(b);
    size_t mn = sa->len < sb->len ? sa->len : sb->len;
    int c = memcmp(sa->data, sb->data, mn);
    if (c == 0) c = (int)sa->len - (int)sb->len;
    *out = (op == MM_LT) ? (c < 0) : (c <= 0);
    return 1; }
  { int mm = (op == MM_LT) ? MM_LT : MM_LE;
    Val ma = table_metamethod(L, a, mm), mb = table_metamethod(L, b, mm);
    if (istrue(ma) && istrue(mb)) {
      int top = L->top;
      luaP_checkstack(L, 4);
      luaP_pushval(L, ma);
      luaP_pushval(L, a); luaP_pushval(L, b);
      luaP_docall(L, L->top - 3, 2, 1, FRK_META, NULL);
      *out = istrue(L->stack[L->top-1]);
      L->top = top;
      return 1; }
    { char buf[300];
      if (a.t == TAG_NIL || b.t == TAG_NIL)
	snprintf(buf, sizeof(buf), "attempt to compare %s with %s", luaP_typename(a), luaP_typename(b));
      else
	snprintf(buf, sizeof(buf), "attempt to compare two %s values", luaP_typename(a));
      throw_at(L, buf); } }
  return 0; }

int lj_concat(Thread *L, Val a, Val b, Val *out)
{ Val m;
  if (a.t == TAG_NUM || a.t == TAG_STR) {
    if (b.t == TAG_NUM || b.t == TAG_STR) {
      Str *sa = tostrV(L, a), *sb = tostrV(L, b);
      char *buf = (char*)luaP_malloc(sa->len + sb->len + 1);
      memcpy(buf, sa->data, sa->len); memcpy(buf + sa->len, sb->data, sb->len);
      *out = strV(luaP_newstr(L, buf, sa->len + sb->len));
      free(buf);
      return 1; } }
  m = get_binmeta(L, a, b, MM_CONCAT);
  if (istrue(m)) {
    int top = L->top;
    luaP_checkstack(L, 4);
    luaP_pushval(L, m); luaP_pushval(L, a); luaP_pushval(L, b);
    luaP_docall(L, L->top - 3, 2, 1, FRK_META, NULL);
    *out = L->stack[L->top-1];
    L->top = top;
    return 1; }
  { char buf[300];
    Val bad = (a.t == TAG_STR || a.t == TAG_NUM) ? b : a;
    snprintf(buf, sizeof(buf), "attempt to concatenate a %s value", luaP_typename(bad));
    throw_at(L, buf); }
  return 0; }

int lj_len(Thread *L, Val obj, Val *out, int objreg)
{ if (obj.t == TAG_STR) { *out = numV((double)strV2(obj)->len); return 1; }
  if (obj.t == TAG_TAB) { *out = numV((double)table_getn(tabV2(obj))); return 1; }
  { Val m = table_metamethod(L, obj, MM_LEN);
    if (istrue(m)) {
      int top = L->top;
      luaP_checkstack(L, 4);
      luaP_pushval(L, m); luaP_pushval(L, obj);
      luaP_docall(L, L->top - 2, 1, 1, FRK_META, NULL);
      *out = L->stack[L->top-1];
      L->top = top;
      return 1; } }
  { uint8_t kind = FRK_NONE; Str *nm = NULL;
    char buf[300];
    if (objreg >= 0) nm = opname(L, objreg, &kind);
    if (nm && kindword(kind)) snprintf(buf, sizeof(buf), "attempt to get length of %s '%s' (%s value)", kindword(kind), nm->data, luaP_typename(obj));
    else snprintf(buf, sizeof(buf), "attempt to get length of a %s value", luaP_typename(obj));
    throw_at(L, buf); }
  return 0; }

int lj_index(Thread *L, Val obj, Val key, Val *out, int objreg)
{ if (obj.t == TAG_TAB) {
    Table *t = tabV2(obj);
    Val *v = table_get(t, key);
    Val mm;
    if (v) { *out = *v; return 1; }
    mm = table_metamethod(L, obj, MM_INDEX);
    if (istrue(mm)) {
      if (mm.t == TAG_TAB) { Val *v2 = table_get(tabV2(mm), key);
	*out = v2 ? *v2 : nilV(); return 1; }
      if (mm.t == TAG_FUN) { int top = L->top;
	luaP_checkstack(L, 4);
	luaP_pushval(L, mm); luaP_pushval(L, obj); luaP_pushval(L, key);
	luaP_docall(L, L->top - 3, 2, 1, FRK_META, NULL);
	*out = L->stack[L->top-1];
	L->top = top; return 1; } }
    *out = nilV();
    return 1; }
  if (obj.t == TAG_STR) {
    extern Table *lj_strmeta;
    if (lj_strmeta) { Val *v = table_get(lj_strmeta, key);
      if (v) { *out = *v; return 1; } }
    *out = nilV();
    return 1; }
  if (obj.t == TAG_UDATA || obj.t == TAG_CDATA) {
    Val mm = table_metamethod(L, obj, MM_INDEX);
    if (istrue(mm)) {
      if (mm.t == TAG_TAB) { Val *v2 = table_get(tabV2(mm), key);
	*out = v2 ? *v2 : nilV(); return 1; }
      if (mm.t == TAG_FUN) { int top = L->top;
	luaP_checkstack(L, 4);
	luaP_pushval(L, mm); luaP_pushval(L, obj); luaP_pushval(L, key);
	luaP_docall(L, L->top - 3, 2, 1, FRK_META, NULL);
	*out = L->stack[L->top-1];
	L->top = top; return 1; } } }
  { uint8_t kind = FRK_NONE; Str *nm = NULL;
    char buf[300];
    if (objreg >= 0) nm = opname(L, objreg, &kind);
    if (nm && kindword(kind)) snprintf(buf, sizeof(buf), "attempt to index %s '%s' (%s value)", kindword(kind), nm->data, luaP_typename(obj));
    else snprintf(buf, sizeof(buf), "attempt to index a %s value", luaP_typename(obj));
    throw_at(L, buf); }
  return 0; }

int lj_newindex(Thread *L, Val obj, Val key, Val val, int objreg)
{ if (obj.t == TAG_TAB) {
    Table *t = tabV2(obj);
    Val *v = table_get(t, key);
    Val mm;
    if (v) { *v = val; return 1; }
    mm = table_metamethod(L, obj, MM_NEWINDEX);
    if (istrue(mm)) {
      if (mm.t == TAG_TAB) { table_set(L, tabV2(mm), key, val); return 1; }
      if (mm.t == TAG_FUN) { int top = L->top;
	luaP_checkstack(L, 4);
	luaP_pushval(L, mm); luaP_pushval(L, obj); luaP_pushval(L, key); luaP_pushval(L, val);
	luaP_docall(L, L->top - 4, 3, 0, FRK_META, NULL);
	L->top = top; return 1; } }
    table_set(L, t, key, val);
    return 1; }
  { uint8_t kind = FRK_NONE; Str *nm = NULL;
    char buf[300];
    if (objreg >= 0) nm = opname(L, objreg, &kind);
    if (nm && kindword(kind)) snprintf(buf, sizeof(buf), "attempt to index %s '%s' (%s value)", kindword(kind), nm->data, luaP_typename(obj));
    else snprintf(buf, sizeof(buf), "attempt to index a %s value", luaP_typename(obj));
    throw_at(L, buf); }
  return 0; }
CEOF
wc -l lvm.c"}

actions.command:
cd /workspace/src && cat > lvm.c <<'CEOF'
/* Virtual machine: frames, calls, errors, tracebacks, coroutines, metamethods. */
#include "lua.h"
#include <ctype.h>
#include <float.h>
#include <errno.h>

/* ----------------------------------------------------------- opcodes ----- */
enum {
  OP_MOVE=0, OP_LOADK, OP_LOADBOOL, OP_LOADNIL, OP_GETUPVAL, OP_SETUPVAL,
  OP_GETTABUP, OP_GETTAB, OP_GETTABLE, OP_SETTABUP, OP_SETTAB, OP_SETTABLE,
  OP_NEWTABLE, OP_SETLIST, OP_ADD, OP_SUB, OP_MUL, OP_DIV, OP_MOD, OP_POW,
  OP_UNM, OP_NOT, OP_LEN, OP_CONCAT, OP_JMP, OP_TEST, OP_TESTSET, OP_EQ,
  OP_LT, OP_LE, OP_JTRUE, OP_JFALSE, OP_JEQ, OP_JNE, OP_JLT, OP_JLE,
  OP_CALL, OP_TAILCALL, OP_RETURN, OP_FORPREP, OP_FORLOOP,
  OP_TFORCALL, OP_TFORLOOP, OP_CLOSURE, OP_VARARG, OP_CLOSE, OP_NOP
};

/* ---------------------------------------------------------------- misc --- */
Thread *curthread = NULL;
typedef void (*ContFunc)(Thread *L, int status);
UpVal *openupvals_head = NULL;

static Frame *topframe(Thread *L) { return &L->frames[L->nframes-1]; }

const char *lj_curfuncname(Thread *L)
{ if (L->nframes == 0) return NULL;
  { Frame *fr = topframe(L); if (fr->name) return fr->name->data; }
  return NULL; }

void lj_fixupvals(Thread *L, Val *old, Val *newstack)
{ GCObject *o; int i;
  for (o = (GCObject*)allthreads_head(); o; o = o->nextthread) {
    Thread *t = (Thread*)o;
    if (t->stack != old) continue;
    for (i = 0; i < t->top; i++) {
      Val v = t->stack[i];
      if (v.t == TAG_UPVAL) { UpVal *u = upV2(v);
	if (u && !u->closed && u->v >= old && u->v < old + t->stacksize)
	  u->v = newstack + (u->v - old); } } } }

/* --------------------------------------------------------------- errors -- */
void luaP_error(Thread *L, Val msg)
{ luaP_checkstack(L, 2); L->stack[L->top++] = msg; err_throw(L); }

void err_throw(Thread *L)
{ ErrCtx *ctx = L->ectx;
  if (!ctx) {
    Val msg = L->stack[L->top-1];
    lj_report(L, msg);
    exit(1);
  }
  longjmp(ctx->jb, 2); }

int lj_yieldthrow(Thread *L)
{ ErrCtx *ctx = L->ectx;
  while (ctx) { if (ctx->catchyield) break; ctx = ctx->prev; }
  if (!ctx) return 0;
  longjmp(ctx->jb, 1);
  return 0; }

void luaP_errorstr(Thread *L, const char *msg)
{ luaP_error(L, strV(luaP_newstr(L, msg, strlen(msg)))); }

void luaP_errormsg(Thread *L, const char *fmt, ...)
{ char buf[2048]; va_list ap; va_start(ap, fmt); vsnprintf(buf, sizeof(buf), fmt, ap); va_end(ap);
  luaP_errorstr(L, buf); }

void luaP_errormsg2(Thread *L, int level, const char *fmt, ...)
{ char buf[2048], loc[300], buf2[2400]; va_list ap;
  va_start(ap, fmt); vsnprintf(buf, sizeof(buf), fmt, ap); va_end(ap);
  lj_getlocation(L, level, loc, sizeof(loc));
  if (loc[0]) { snprintf(buf2, sizeof(buf2), "%s%s", loc, buf); luaP_errorstr(L, buf2); }
  else luaP_errorstr(L, buf); }

void lj_getlocation(Thread *L, int level, char *out, size_t outlen)
{ int i, cnt = 0;
  out[0] = 0;
  for (i = L->nframes - 1; i >= 0; i--) {
    Frame *fr = &L->frames[i];
    if (fr->kind != FR_LUA) continue;
    cnt++;
    if (cnt == level) {
      Func *f = funV2(fr->func);
      if (f && f->proto) {
	int line = lj_lineof(f->proto, fr->pc);
	if (f->proto->source) snprintf(out, outlen, "%s:%d: ", f->proto->source->data, line);
	else snprintf(out, outlen, "?:%d: ", line);
      }
      return;
    } } }

int lj_protect(Thread *L, ErrCtx *ctx, int catchyield)
{ ctx->prev = L->ectx; ctx->catchyield = catchyield; ctx->L = L;
  L->ectx = ctx; return setjmp(ctx->jb); }

void lj_unprotect(Thread *L, ErrCtx *ctx) { L->ectx = ctx->prev; }

/* ------------------------------------------------------------- stack ----- */
void luaP_setupstack(Thread *L, int need)
{ if (L->top + need >= L->stacksize) {
    int ns = L->stacksize; Val *old = L->stack;
    while (ns < L->top + need + 1) ns *= 2;
    if (ns > LUA_MAXSTACK) {
      if (L->top + need + 1 > LUA_MAXSTACK) luaP_errorstr(L, "stack overflow");
      ns = LUA_MAXSTACK;
    }
    L->stack = (Val*)luaP_malloc(sizeof(Val)*ns);
    memcpy(L->stack, old, sizeof(Val)*L->stacksize);
    { int i; for (i = L->stacksize; i < ns; i++) L->stack[i] = nilV(); }
    free(old); L->stacksize = ns;
    lj_fixupvals(L, old, L->stack);
  } }

void luaP_checkstack(Thread *L, int n) { luaP_setupstack(L, n); }
void luaP_checkstack_co(Thread *L, int n) { luaP_setupstack(L, n); }

/* ------------------------------------------------------ metamethods ------ */
Table *metatableV(Val v)
{ switch (v.t) {
  case TAG_TAB: return tabV2(((Table*)v.u.g)->mt);
  case TAG_UDATA: return tabV2(((UData*)v.u.g)->mt);
  case TAG_CDATA: return tabV2(((CData*)v.u.g)->mt);
  case TAG_STR: { extern Table *lj_strmeta; return lj_strmeta; }
  case TAG_THREAD: { Thread *t = (Thread*)v.u.g; return tabV2(t->co); }
  }
  return NULL; }

Val table_metamethod(Thread *L, Val obj, int mm)
{ Table *mt = metatableV(obj);
  Val key, *v;
  if (!mt) return nilV();
  key = strV(luaP_newstr(L, lj_mmnames[mm], strlen(lj_mmnames[mm])));
  v = table_get(mt, key);
  if (!v) return nilV();
  return *v; }

static Val get_binmeta(Thread *L, Val a, Val b, int mm)
{ Val m = table_metamethod(L, a, mm);
  if (!istrue(m)) m = table_metamethod(L, b, mm);
  return m; }

int lj_tostring_meta(Thread *L, Val obj, Val *out)
{ Val mm = table_metamethod(L, obj, MM_TOSTRING);
  int top;
  if (!istrue(mm)) return 0;
  top = L->top;
  luaP_checkstack(L, 4);
  luaP_pushval(L, mm);
  luaP_pushval(L, obj);
  luaP_docall(L, L->top - 2, 1, 1, FRK_META, NULL);
  *out = L->stack[L->top-1];
  L->top = top;
  return 1; }

int lj_callmeta(Thread *L, Val obj, int mm, int nargs, int nres)
{ Val m = table_metamethod(L, obj, mm);
  int top, i;
  if (!istrue(m)) return 0;
  top = L->top;
  luaP_checkstack(L, nargs + 4);
  luaP_pushval(L, m);
  for (i = 0; i < nargs; i++) luaP_pushval(L, L->stack[top - nargs + i]);
  luaP_docall(L, L->top - nargs - 1, nargs, nres, FRK_META, NULL);
  L->top = top + nres;
  return 1; }

/* ----------------------------------------------------- slot name lookup -- */
int lj_slotname(Thread *L, Frame *fr, int reg, uint8_t *kind, Str **name)
{ Proto *p; int i, pc;
  Func *f;
  *kind = FRK_NONE; *name = NULL;
  if (fr->func.t != TAG_FUN) return 0;
  f = funV2(fr->func);
  if (!f || !f->proto) return 0;
  p = f->proto;
  pc = fr->pc;
  if (p->locslot) {
    for (i = 0; i < p->nlocs; i++) {
      if (p->locslot[i] == reg && pc >= p->locstart[i] && pc <= p->locend[i]) {
	*kind = FRK_LOCAL; *name = p->locname[i]; return 1; } } }
  if (pc > 0) {
    Ins *ins = &p->code[pc-1];
    if (ins->a == reg) {
      switch (ins->op) {
      case OP_GETTABUP: *kind = FRK_GLOBAL; *name = strV2(p->k[ins->c]); return 1;
      case OP_GETTAB: *kind = FRK_FIELD; *name = strV2(p->k[ins->c]); return 1;
      case OP_GETUPVAL: *kind = FRK_UPVAL; *name = p->uvnames[ins->b]; return 1;
      case OP_SELF: *kind = FRK_METHOD; *name = strV2(p->k[ins->c]); return 1;
      } } }
  return 0; }

static Str *opname(Thread *L, int reg, uint8_t *kind)
{ if (L->nframes == 0) { *kind = FRK_NONE; return NULL; }
  { Frame *fr = topframe(L);
    Str *nm = NULL; uint8_t k = FRK_NONE;
    if (lj_slotname(L, fr, reg, &k, &nm)) { *kind = k; return nm; } }
  *kind = FRK_NONE;
  return NULL; }

static const char *kindword(uint8_t kind)
{ switch (kind) {
  case FRK_LOCAL: return "local";
  case FRK_GLOBAL: return "global";
  case FRK_FIELD: return "field";
  case FRK_METHOD: return "method";
  case FRK_UPVAL: return "upvalue";
  }
  return NULL; }

static void throw_at(Thread *L, const char *msg)
{ char loc[300], buf[600];
  lj_getlocation(L, 1, loc, sizeof(loc));
  snprintf(buf, sizeof(buf), "%s%s", loc, msg);
  luaP_errorstr(L, buf); }

static void typeerror(Thread *L, int reg, const char *op, const char *t)
{ uint8_t kind = FRK_NONE; Str *nm = opname(L, reg, &kind);
  char buf[256];
  const char *kw = kindword(kind);
  if (nm && kw) snprintf(buf, sizeof(buf), "attempt to %s %s '%s' (%s value)", op, kw, nm->data, t);
  else snprintf(buf, sizeof(buf), "attempt to %s a %s value", op, t);
  throw_at(L, buf); }

/* -------------------------------------------------------- arith/compare -- */
static int arith_num(double a, double b, int op, double *out)
{ switch (op) {
  case MM_ADD: *out = a + b; return 1;
  case MM_SUB: *out = a - b; return 1;
  case MM_MUL: *out = a * b; return 1;
  case MM_DIV: *out = a / b; return 1;
  case MM_MOD: *out = lj_nummod(a, b); return 1;
  case MM_POW: *out = pow(a, b); return 1;
  }
  return 0; }

static int tonumberV(Val v, double *out)
{ if (v.t == TAG_NUM) { *out = v.u.n; return 1; }
  if (v.t == TAG_STR) { Str *s = strV2(v); return str2num(s->data, s->len, out); }
  return 0; }

int lj_arith(Thread *L, Val a, Val b, int op, Val *out, int rega, int regb)
{ double x, y, r;
  if (tonumberV(a, &x) && tonumberV(b, &y)) { arith_num(x, y, op, &r); *out = numV(r); return 1; }
  { Val m = get_binmeta(L, a, b, op);
    if (istrue(m)) {
      int top = L->top;
      luaP_checkstack(L, 4);
      luaP_pushval(L, m);
      luaP_pushval(L, a);
      luaP_pushval(L, b);
      luaP_docall(L, L->top - 3, 2, 1, FRK_META, NULL);
      *out = L->stack[L->top-1];
      L->top = top;
      return 1; } }
  { Val bad = a;
    int badreg = rega;
    if (a.t == TAG_NUM || (a.t == TAG_STR && tonumberV(a, &x))) { bad = b; badreg = regb; }
    if (badreg >= 0) typeerror(L, badreg, "perform arithmetic on", luaP_typename(bad));
    else { char buf[256];
      snprintf(buf, sizeof(buf), "attempt to perform arithmetic on a %s value", luaP_typename(bad));
      throw_at(L, buf); } }
  return 0; }

int lj_unm(Thread *L, Val a, Val *out, int rega)
{ if (a.t == TAG_NUM) { *out = numV(-a.u.n); return 1; }
  { Val m = table_metamethod(L, a, MM_UNM);
    if (istrue(m)) {
      int top = L->top;
      luaP_checkstack(L, 4);
      luaP_pushval(L, m); luaP_pushval(L, a);
      luaP_docall(L, L->top - 2, 1, 1, FRK_META, NULL);
      *out = L->stack[L->top-1];
      L->top = top; return 1; } }
  if (rega >= 0) typeerror(L, rega, "perform arithmetic on", luaP_typename(a));
  else { char buf[256];
    snprintf(buf, sizeof(buf), "attempt to perform arithmetic on a %s value", luaP_typename(a));
    throw_at(L, buf); }
  return 0; }

int lj_compare(Thread *L, Val a, Val b, int op, int *out)
{ if (a.t == TAG_NUM && b.t == TAG_NUM) { *out = (op == MM_LT) ? (a.u.n < b.u.n) : (a.u.n <= b.u.n); return 1; }
  if (a.t == TAG_STR && b.t == TAG_STR) {
    Str *sa = strV2(a), *sb = strV2(b);
    size_t mn = sa->len < sb->len ? sa->len : sb->len;
    int c = memcmp(sa->data, sb->data, mn);
    if (c == 0) c = (int)sa->len - (int)sb->len;
    *out = (op == MM_LT) ? (c < 0) : (c <= 0);
    return 1; }
  { int mm = (op == MM_LT) ? MM_LT : MM_LE;
    Val ma = table_metamethod(L, a, mm), mb = table_metamethod(L, b, mm);
    if (istrue(ma) && istrue(mb)) {
      int top = L->top;
      luaP_checkstack(L, 4);
      luaP_pushval(L, ma);
      luaP_pushval(L, a); luaP_pushval(L, b);
      luaP_docall(L, L->top - 3, 2, 1, FRK_META, NULL);
      *out = istrue(L->stack[L->top-1]);
      L->top = top;
      return 1; }
    { char buf[300];
      if (a.t == TAG_NIL || b.t == TAG_NIL)
	snprintf(buf, sizeof(buf), "attempt to compare %s with %s", luaP_typename(a), luaP_typename(b));
      else
	snprintf(buf, sizeof(buf), "attempt to compare two %s values", luaP_typename(a));
      throw_at(L, buf); } }
  return 0; }

int lj_concat(Thread *L, Val a, Val b, Val *out)
{ Val m;
  if (a.t == TAG_NUM || a.t == TAG_STR) {
    if (b.t == TAG_NUM || b.t == TAG_STR) {
      Str *sa = tostrV(L, a), *sb = tostrV(L, b);
      char *buf = (char*)luaP_malloc(sa->len + sb->len + 1);
      memcpy(buf, sa->data, sa->len); memcpy(buf + sa->len, sb->data, sb->len);
      *out = strV(luaP_newstr(L, buf, sa->len + sb->len));
      free(buf);
      return 1; } }
  m = get_binmeta(L, a, b, MM_CONCAT);
  if (istrue(m)) {
    int top = L->top;
    luaP_checkstack(L, 4);
    luaP_pushval(L, m); luaP_pushval(L, a); luaP_pushval(L, b);
    luaP_docall(L, L->top - 3, 2, 1, FRK_META, NULL);
    *out = L->stack[L->top-1];
    L->top = top;
    return 1; }
  { char buf[300];
    Val bad = (a.t == TAG_STR || a.t == TAG_NUM) ? b : a;
    snprintf(buf, sizeof(buf), "attempt to concatenate a %s value", luaP_typename(bad));
    throw_at(L, buf); }
  return 0; }

int lj_len(Thread *L, Val obj, Val *out, int objreg)
{ if (obj.t == TAG_STR) { *out = numV((double)strV2(obj)->len); return 1; }
  if (obj.t == TAG_TAB) { *out = numV((double)table_getn(tabV2(obj))); return 1; }
  { Val m = table_metamethod(L, obj, MM_LEN);
    if (istrue(m)) {
      int top = L->top;
      luaP_checkstack(L, 4);
      luaP_pushval(L, m); luaP_pushval(L, obj);
      luaP_docall(L, L->top - 2, 1, 1, FRK_META, NULL);
      *out = L->stack[L->top-1];
      L->top = top;
      return 1; } }
  { uint8_t kind = FRK_NONE; Str *nm = NULL;
    char buf[300];
    if (objreg >= 0) nm = opname(L, objreg, &kind);
    if (nm && kindword(kind)) snprintf(buf, sizeof(buf), "attempt to get length of %s '%s' (%s value)", kindword(kind), nm->data, luaP_typename(obj));
    else snprintf(buf, sizeof(buf), "attempt to get length of a %s value", luaP_typename(obj));
    throw_at(L, buf); }
  return 0; }

int lj_index(Thread *L, Val obj, Val key, Val *out, int objreg)
{ if (obj.t == TAG_TAB) {
    Table *t = tabV2(obj);
    Val *v = table_get(t, key);
    Val mm;
    if (v) { *out = *v; return 1; }
    mm = table_metamethod(L, obj, MM_INDEX);
    if (istrue(mm)) {
      if (mm.t == TAG_TAB) { Val *v2 = table_get(tabV2(mm), key);
	*out = v2 ? *v2 : nilV(); return 1; }
      if (mm.t == TAG_FUN) { int top = L->top;
	luaP_checkstack(L, 4);
	luaP_pushval(L, mm); luaP_pushval(L, obj); luaP_pushval(L, key);
	luaP_docall(L, L->top - 3, 2, 1, FRK_META, NULL);
	*out = L->stack[L->top-1];
	L->top = top; return 1; } }
    *out = nilV();
    return 1; }
  if (obj.t == TAG_STR) {
    extern Table *lj_strmeta;
    if (lj_strmeta) { Val *v = table_get(lj_strmeta, key);
      if (v) { *out = *v; return 1; } }
    *out = nilV();
    return 1; }
  if (obj.t == TAG_UDATA || obj.t == TAG_CDATA) {
    Val mm = table_metamethod(L, obj, MM_INDEX);
    if (istrue(mm)) {
      if (mm.t == TAG_TAB) { Val *v2 = table_get(tabV2(mm), key);
	*out = v2 ? *v2 : nilV(); return 1; }
      if (mm.t == TAG_FUN) { int top = L->top;
	luaP_checkstack(L, 4);
	luaP_pushval(L, mm); luaP_pushval(L, obj); luaP_pushval(L, key);
	luaP_docall(L, L->top - 3, 2, 1, FRK_META, NULL);
	*out = L->stack[L->top-1];
	L->top = top; return 1; } } }
  { uint8_t kind = FRK_NONE; Str *nm = NULL;
    char buf[300];
    if (objreg >= 0) nm = opname(L, objreg, &kind);
    if (nm && kindword(kind)) snprintf(buf, sizeof(buf), "attempt to index %s '%s' (%s value)", kindword(kind), nm->data, luaP_typename(obj));
    else snprintf(buf, sizeof(buf), "attempt to index a %s value", luaP_typename(obj));
    throw_at(L, buf); }
  return 0; }

int lj_newindex(Thread *L, Val obj, Val key, Val val, int objreg)
{ if (obj.t == TAG_TAB) {
    Table *t = tabV2(obj);
    Val *v = table_get(t, key);
    Val mm;
    if (v) { *v = val; return 1; }
    mm = table_metamethod(L, obj, MM_NEWINDEX);
    if (istrue(mm)) {
      if (mm.t == TAG_TAB) { table_set(L, tabV2(mm), key, val); return 1; }
      if (mm.t == TAG_FUN) { int top = L->top;
	luaP_checkstack(L, 4);
	luaP_pushval(L, mm); luaP_pushval(L, obj); luaP_pushval(L, key); luaP_pushval(L, val);
	luaP_docall(L, L->top - 4, 3, 0, FRK_META, NULL);
	L->top = top; return 1; } }
    table_set(L, t, key, val);
    return 1; }
  { uint8_t kind = FRK_NONE; Str *nm = NULL;
    char buf[300];
    if (objreg >= 0) nm = opname(L, objreg, &kind);
    if (nm && kindword(kind)) snprintf(buf, sizeof(buf), "attempt to index %s '%s' (%s value)", kindword(kind), nm->data, luaP_typename(obj));
    else snprintf(buf, sizeof(buf), "attempt to index a %s value", luaP_typename(obj));
    throw_at(L, buf); }
  return 0; }
