static void typeerror(Thread *L, int reg, const char *op, const char *t)
{ uint8_t kind = FRK_NONE; Str *nm = opname(L, reg, &kind);
  char buf[256];
  const char *kw = kindword(kind);
  if (nm && kw) snprintf(buf, sizeof(buf), "attempt to %s %s '%s' (%s value)", op, kw, nm->data, t);
  else snprintf(buf, sizeof(buf), "attempt to %s a %s value", op, t);
  throw_at(L, buf); }

/* -------------------------------------------------------- arith/compare -- */
static int arith_num(double a, double b, int op, double *out)
{ switch (op) {
  case MM_ADD: *out = a + b; return 1;
  case MM_SUB: *out = a - b; return 1;
  case MM_MUL: *out = a * b; return 1;
  case MM_DIV: *out = a / b; return 1;
  case MM_MOD: *out = lj_nummod(a, b); return 1;
  case MM_POW: *out = pow(a, b); return 1;
  }
  return 0; }

static int tonumberV(Val v, double *out)
{ if (v.t == TAG_NUM) { *out = v.u.n; return 1; }
  if (v.t == TAG_STR) { Str *s = strV2(v); return str2num(s->data, s->len, out); }
  return 0; }

int lj_arith(Thread *L, Val a, Val b, int op, Val *out, int rega, int regb)
{ double x, y, r;
  if (tonumberV(a, &x) && tonumberV(b, &y)) { arith_num(x, y, op, &r); *out = numV(r); return 1; }
  { Val m = get_binmeta(L, a, b, op);
    if (istrue(m)) {
      int top = L->top;
      luaP_checkstack(L, 4);
      luaP_pushval(L, m);
      luaP_pushval(L, a);
      luaP_pushval(L, b);
      luaP_docall(L, L->top - 3, 2, 1, FRK_META, NULL);
      *out = L->stack[L->top-1];
      L->top = top;
      return 1; } }
  { Val bad = a;
    int badreg = rega;
    if (a.t == TAG_NUM || (a.t == TAG_STR && tonumberV(a, &x))) { bad = b; badreg = regb; }
    if (badreg >= 0) typeerror(L, badreg, "perform arithmetic on", luaP_typename(bad));
    else { char buf[256];
      snprintf(buf, sizeof(buf), "attempt to perform arithmetic on a %s value", luaP_typename(bad));
      throw_at(L, buf); } }
  return 0; }

int lj_unm(Thread *L, Val a, Val *out, int rega)
{ if (a.t == TAG_NUM) { *out = numV(-a.u.n); return 1; }
  { Val m = table_metamethod(L, a, MM_UNM);
    if (istrue(m)) {
      int top = L->top;
      luaP_checkstack(L, 4);
      luaP_pushval(L, m); luaP_pushval(L, a);
      luaP_docall(L, L->top - 2, 1, 1, FRK_META, NULL);
      *out = L->stack[L->top-1];
      L->top = top; return 1; } }
  if (rega >= 0) typeerror(L, rega, "perform arithmetic on", luaP_typename(a));
  else { char buf[256];
    snprintf(buf, sizeof(buf), "attempt to perform arithmetic on a %s value", luaP_typename(a));
    throw_at(L, buf); }
  return 0; }

int lj_compare(Thread *L, Val a, Val b, int op, int *out)
{ if (a.t == TAG_NUM && b.t == TAG_NUM) { *out = (op == MM_LT) ? (a.u.n < b.u.n) : (a.u.n <= b.u.n); return 1; }
  if (a.t == TAG_STR && b.t == TAG_STR) {
    Str *sa = strV2(a), *sb = strV2(b);
    size_t mn = sa->len < sb->len ? sa->len : sb->len;
