    case OP_JEQ: if (val_equal(RB(ins.a), RK(ins.b))) pc += ins.c; break;
    case OP_JNE: if (!val_equal(RB(ins.a), RK(ins.b))) pc += ins.c; break;
    case OP_JLT: { int res; lj_compare(L, RB(ins.a), RK(ins.b), MM_LT, &res);
