/* ------------------------------------------------------- upvalue list ---- */
UpVal *find_upval(Thread *L, Val *v)
{ UpVal *u = openupvals_head;
  while (u) { if (u->v == v && !u->closed) return u; u = u->nextopen; }
  return NULL; }

static void close_upvals_from(Thread *L, Val *limit)
{ UpVal **pp = &openupvals_head;
  while (*pp) {
    UpVal *u = *pp;
    if (!u->closed && u->v >= limit) {
      u->closed = 1;
      u->val = *u->v;
      u->v = &u->val;
      *pp = u->nextopen;
    } else pp = &u->nextopen;
  } }

int lj_lineof(Proto *p, int pc)
{ if (pc < 0) pc = 0;
  if (pc >= p->ncode) pc = p->ncode - 1;
  if (p->lines) return p->lines[pc];
  return p->linedefined; }

/* ----------------------------------------------------------- unwinding --- */
static void remove_ctx(ErrCtx **head, ErrCtx *ctx)
{ ErrCtx **pp = head;
  while (*pp) { if (*pp == ctx) { *pp = (*pp)->prev; return; } pp = &(*pp)->prev; } }

static void unwind_to(Thread *L, int nframes)
{ while (L->nframes > nframes) {
    Frame *fr = &L->frames[L->nframes-1];
    if (fr->kind == FR_LUA) close_upvals_from(L, L->stack + fr->base + 1);
    if (fr->ctx) { remove_ctx(&L->ectx, fr->ctx); fr->ctx = NULL; }
    L->nframes--; } }

static void finish_call(Thread *L, int funcidx, int n, int nresults)
{ if (nresults > 0) {
    if (n < nresults) { int i;
      luaP_checkstack(L, funcidx + nresults + 2);
      for (i = n; i < nresults; i++) L->stack[funcidx + i] = nilV(); }
    L->top = funcidx + nresults;
  } else {
    L->top = funcidx + n;
  } }

/* ------------------------------------------------------------ calls ------ */
static void call_error(Thread *L, int funcidx, Val fv)
{ uint8_t kind = FRK_NONE; Str *nm = NULL;
  char kwbuf[16] = "";
  const char *kw = NULL;
  char loc[300], buf[600];
  if (L->nframes) {
    Frame *fr = topframe(L);
    int reg = funcidx - fr->base - 1;
    if (reg >= 0) lj_slotname(L, fr, reg, &kind, &nm);
  }
  kw = kindword(kind);
  lj_getlocation(L, 1, loc, sizeof(loc));
  if (nm && kw) { snprintf(buf, sizeof(buf), "%sattempt to call %s '%s' (%s value)", loc, kw, nm->data, luaP_typename(fv)); }
  else snprintf(buf, sizeof(buf), "%sattempt to call a %s value", loc, luaP_typename(fv));
  luaP_errorstr(L, buf); }

void luaP_docall(Thread *L, int funcidx, int nargs, int nresults,
		 uint8_t namekind, Str *name)
{ Val fv;
  int target;
  extern void lj_pcall_frame(Thread *L, int funcidx, int nargs, int nresults, Func *f,
			     uint8_t namekind, Str *name);
  extern CFunction_ lib_base_pcall, lib_base_xpcall;
  if (funcidx + 1 > L->top) { L->top = funcidx + 1; L->stack[funcidx] = nilV(); }
  fv = L->stack[funcidx];
  target = L->nframes;
  if (fv.t != TAG_FUN) call_error(L, funcidx, fv);
  { Func *f = funV2(fv);
    if (f->isC) {
      if (f->cf == lib_base_pcall || f->cf == lib_base_xpcall) {
	lj_pcall_frame(L, funcidx, nargs, nresults, f, namekind, name);
	return;
      }
      { Frame fr;
	memset(&fr, 0, sizeof(fr));
	fr.base = funcidx; fr.top = funcidx + nargs + 1; fr.kind = FR_C; fr.func = fv;
	fr.namewhat = namekind; fr.name = name; fr.pc = -1;
	luaP_pushframe(L, fr);
	L->top = funcidx + nargs + 1;
	f->cf(L);
	luaP_popframe(L);
	finish_call(L, funcidx, L->top - funcidx, nresults);
	return; } }
    else {
      Proto *p = f->proto;
      Frame fr;
      int i;
      if (L->nframes >= FRAME_LIMIT) luaP_errorstr(L, "stack overflow");
      memset(&fr, 0, sizeof(fr));
      fr.base = funcidx; fr.kind = FR_LUA; fr.func = fv;
      fr.namewhat = namekind; fr.name = name;
      fr.nresults = nresults;
      luaP_pushframe(L, fr);
      luaP_setupstack(L, p->maxstack + nargs + 16);
      { int np = p->numparams;
	int na = nargs < np ? nargs : np;
	for (i = na; i < np; i++) L->stack[funcidx + 1 + i] = nilV();
	if (p->isvararg) {
	  int extra = nargs - np;
	  if (extra < 0) extra = 0;
	  if (extra > 0 && funcidx + 1 + np != funcidx + 1 + p->maxstack)
	    memmove(&L->stack[funcidx + 1 + p->maxstack],
		    &L->stack[funcidx + 1 + np], sizeof(Val) * extra);
	  L->top = funcidx + 1 + p->maxstack + extra;
	} else {
	  for (i = np; i < p->maxstack; i++) L->stack[funcidx + 1 + i] = nilV();
	  L->top = funcidx + 1 + p->maxstack;
	} }
      fr.pc = 0;
      L->frames[L->nframes-1].pc = 0;
      L->frames[L->nframes-1].top = L->top;
      luaP_run(L, target);
      finish_call(L, funcidx, L->top - funcidx, nresults);
      return; } } }

void luaP_call(Thread *L, int nargs, int nresults)
{ int funcidx = L->top - nargs - 1;
  luaP_docall(L, funcidx, nargs, nresults, FRK_NONE, NULL);
  if (nresults > 0) L->top = funcidx + nresults; }

/* ------------------------------------------------------- the VM loop ----- */
int luaP_run(Thread *L, int stopframes)
{
  for (;;) {
    Frame *fr;
    if (L->nframes <= stopframes) return 0;
    fr = &L->frames[L->nframes-1];
    if (fr->kind == FR_LUA) { luaP_runframe(L); continue; }
    if (fr->kind == FR_C) {
      if (fr->cont && fr->needscont) { ((ContFunc)(fr->cont))(L, 1); continue; }
      return 3;
    }
    return 3;
  }
}

void luaP_runframe(Thread *L)
{
  Frame *fr = &L->frames[L->nframes-1];
  Func *f = funV2(fr->func);
  Proto *p = f->proto;
  Ins *code = p->code;
  int pc = fr->pc;
  int base = fr->base;
#define RB(i) (L->stack[base + 1 + (i)])
#define K(i)  (p->k[(i)])
#define RK(i) (((i) & 0x100) ? K((i) & 0xff) : RB((i) & 0xff))
  for (;;) {
    Ins ins;
    if (pc >= p->ncode) {
      L->frames[L->nframes-1].pc = pc;
      close_upvals_from(L, L->stack + base + 1);
      L->nframes--;
      L->top = base;
      return;
    }
    ins = code[pc];
    L->frames[L->nframes-1].pc = pc;
    pc++;
    switch (ins.op) {
    case OP_MOVE: RB(ins.a) = RB(ins.b); break;
    case OP_LOADK: RB(ins.a) = K(ins.b); break;
    case OP_LOADNIL: { int i; for (i = 0; i < ins.b; i++) RB(ins.a + i) = nilV(); break; }
    case OP_LOADBOOL: RB(ins.a) = boolV(ins.b != 0); if (ins.c) pc++; break;
    case OP_GETUPVAL: { UpVal *u = f->upvals[ins.b];
      RB(ins.a) = u->closed ? u->val : *u->v; break; }
    case OP_SETUPVAL: { UpVal *u = f->upvals[ins.b];
      if (u->closed) u->val = RB(ins.a); else *u->v = RB(ins.a); break; }
    case OP_GETTABUP: { UpVal *u = f->upvals[ins.b];
      Val uv = u->closed ? u->val : *u->v;
      lj_index(L, uv, K(ins.c), &RB(ins.a), ins.a); break; }
    case OP_SETTABUP: { UpVal *u = f->upvals[ins.a];
      Val uv = u->closed ? u->val : *u->v;
      lj_newindex(L, uv, K(ins.b), RB(ins.c), -1); break; }
    case OP_GETTAB: lj_index(L, RB(ins.b), K(ins.c), &RB(ins.a), ins.b); break;
    case OP_SETTAB: lj_newindex(L, RB(ins.b), K(ins.c), RB(ins.a), ins.b); break;
    case OP_GETTABLE: lj_index(L, RB(ins.b), RB(ins.c), &RB(ins.a), ins.b); break;
    case OP_SETTABLE: lj_newindex(L, RB(ins.b), RB(ins.c), RB(ins.a), ins.b); break;
    case OP_NEWTABLE: { Table *t = luaP_newtable(L);
      if (ins.b > 0 || ins.c > 0) table_resize(L, t, (uint32_t)ins.b, (uint32_t)ins.c);
      RB(ins.a) = tabV(t); break; }
    case OP_SETLIST: { Table *t = tabV2(RB(ins.a));
      int i, n = ins.b;
      if (n == 0) n = L->top - (base + 1 + ins.a) - 1;
      for (i = 0; i < n; i++) table_set(L, t, numV((double)(ins.c + i)), RB(ins.a + 1 + i));
      if (ins.b == 0) L->top = base + 1 + ins.a + 1;
      break; }
    case OP_ADD: case OP_SUB: case OP_MUL: case OP_DIV: case OP_MOD: case OP_POW:
      lj_arith(L, RK(ins.b), RK(ins.c), MM_ADD + (ins.op - OP_ADD), &RB(ins.a),
	       ((ins.b & 0x100) ? -1 : (ins.b & 0xff)), ((ins.c & 0x100) ? -1 : (ins.c & 0xff)));
      break;
    case OP_UNM: lj_unm(L, RK(ins.b), &RB(ins.a), (ins.b & 0x100) ? -1 : (ins.b & 0xff)); break;
    case OP_NOT: RB(ins.a) = boolV(!istrue(RK(ins.b))); break;
    case OP_LEN: lj_len(L, RK(ins.b), &RB(ins.a), (ins.b & 0x100) ? -1 : (ins.b & 0xff)); break;
    case OP_CONCAT: { int i, n = ins.c - ins.b + 1;
      int hasmeta = 0;
      for (i = 0; i < n; i++) {
	Val v = RK(ins.b + i);
	if (v.t != TAG_STR && v.t != TAG_NUM) {
	  if (istrue(table_metamethod(L, v, MM_CONCAT))) hasmeta = 1; } }
      if (hasmeta) {
	int idx = ins.c;
	Val acc = RK(idx);
	for (i = ins.c - 1; i >= ins.b; i--) { Val nv; lj_concat(L, RK(i), acc, &nv); acc = nv; }
	RB(ins.a) = acc;
      } else {
	int j;
	Val acc = RK(ins.b);
	for (j = ins.b + 1; j <= ins.c; j++) { Val nv; lj_concat(L, acc, RK(j), &nv); acc = nv; }
	RB(ins.a) = acc; }
      break; }
    case OP_JMP: pc += ins.c; break;
    case OP_TEST: if (istrue(RB(ins.a)) != (ins.c != 0)) pc++; break;
    case OP_TESTSET: if (istrue(RB(ins.b)) == (ins.c != 0)) RB(ins.a) = RB(ins.b); else pc++; break;
    case OP_EQ: RB(ins.a) = boolV(val_equal(RB(ins.a), RK(ins.b))); break;
    case OP_LT: case OP_LE: { int res;
      lj_compare(L, RK(ins.b), RK(ins.c), ins.op == OP_LT ? MM_LT : MM_LE, &res);
      RB(ins.a) = boolV(res); break; }
    case OP_JEQ: if (val_equal(RB(ins.a), RK(ins.b))) pc += ins.c; break;
    case OP_JNE: if (!val_equal(RB(ins.a), RK(ins.b))) pc += ins.c; break;
    case OP_JLT: { int res; lj_compare(L, RB(ins.a), RK(ins.b), MM_LT, &res);
      if (res) pc += ins.c; break; }
    case OP_JLE: { int res; lj_compare(L, RB(ins.a), RK(ins.b), MM_LE, &res);
      if (res) pc += ins.c; break; }
    case OP_JTRUE: if (istrue(RB(ins.a))) pc += ins.c; break;
    case OP_JFALSE: if (!istrue(RB(ins.a))) pc += ins.c; break;
    case OP_CALL: {
      int a = ins.a, b = ins.b, c = ins.c;
      int funcidx = base + 1 + a;
      int nargs;
      uint8_t nk = (p->callnamekind) ? p->callnamekind[pc-1] : (uint8_t)FRK_NONE;
      Str *nm = (p->callnamekind && p->callnamestr) ? p->callnamestr[pc-1] : NULL;
      if (b == 0) nargs = L->top - funcidx - 1;
      else nargs = b - 1;
      L->frames[L->nframes-1].pc = pc;
      if (c) {
	L->top = funcidx + nargs + 1;
	luaP_docall(L, funcidx, nargs, c, nk, nm);
	L->top = funcidx + c;
      } else {
	L->top = funcidx + nargs + 1;
	luaP_docall(L, funcidx, nargs, 0, nk, nm);
      }
      break; }
    case OP_TAILCALL: {
      int a = ins.a, b = ins.b;
      int funcidx = base + 1 + a;
      int nargs = b ? b - 1 : (L->top - funcidx - 1);
      uint8_t inhk = fr->namewhat; Str *inhn = fr->name;
      int n;
      L->frames[L->nframes-1].pc = pc;
      close_upvals_from(L, L->stack + base + 1);
      L->nframes--;
      if (b == 0) L->top = funcidx + nargs + 1;
      luaP_docall(L, funcidx, nargs, 0, inhk, inhn);
      n = L->top - funcidx;
      if (funcidx != base) memmove(&L->stack[base], &L->stack[funcidx], sizeof(Val) * n);
      L->top = base + n;
      return; }
    case OP_RETURN: {
      int a = ins.a, b = ins.b;
      int n = b ? b - 1 : (L->top - (base + 1 + a));
      L->frames[L->nframes-1].pc = pc;
      close_upvals_from(L, L->stack + base + 1);
      if (a != 0 && n > 0) memmove(&L->stack[base], &L->stack[base + 1 + a], sizeof(Val) * n);
      L->top = base + n;
      L->nframes--;
      return; }
    case OP_FORPREP: {
      Val init = RB(ins.a), limit = RB(ins.a+1), step = RB(ins.a+2);
      double di, dl, ds;
      if (!tonumberV(limit, &dl)) { throw_at(L, "'for' limit must be a number"); }
      if (!tonumberV(step, &ds)) { throw_at(L, "'for' step must be a number"); }
      if (ds == 0) luaP_errorstr(L, "'for' step is zero");
      if (!tonumberV(init, &di)) { throw_at(L, "'for' initial value must be a number"); }
      RB(ins.a) = numV(di - ds);
      RB(ins.a+3) = nilV();
      pc += ins.c;
      break; }
    case OP_FORLOOP: {
      double idx = 0, limit = 0, step = 0;
      tonumberV(RB(ins.a), &idx); tonumberV(RB(ins.a+1), &limit); tonumberV(RB(ins.a+2), &step);
      idx += step;
      if (step > 0 ? idx <= limit : limit <= idx) {
	RB(ins.a) = numV(idx);
	RB(ins.a+3) = numV(idx);
	pc += ins.c;
      } else RB(ins.a+3) = numV(idx);
      break; }
    case OP_TFORCALL: {
      int a = ins.a;
      int funcidx = base + 1 + a;
      L->frames[L->nframes-1].pc = pc;
      L->top = funcidx + 3;
      luaP_docall(L, funcidx, 2, 2, FRK_NONE, NULL);
      L->top = funcidx + 2;
      break; }
    case OP_TFORLOOP: {
      if (!isfalse(RB(ins.a + 3))) { RB(ins.a + 2) = RB(ins.a + 3); pc += ins.c; }
      break; }
    case OP_CLOSURE: {
      int i, nuv;
      Proto *cp;
      UpVal **ups;
      Func *nf;
      if (!p->children || ins.b >= p->nchildren) { RB(ins.a) = nilV(); break; }
      cp = p->children[ins.b];
      nuv = cp->nuv;
      ups = (UpVal**)luaP_malloc(sizeof(UpVal*) * (nuv ? nuv : 1));
      for (i = 0; i < nuv; i++) {
	int inparent = p->uvinfo[2*i];
	int idx = p->uvinfo[2*i+1];
	if (inparent) {
	  UpVal *u = find_upval(L, &L->stack[base + 1 + idx]);
	  if (!u) { u = luaP_newupval(L); u->v = &L->stack[base + 1 + idx];
	    u->closed = 0; u->nextopen = openupvals_head; openupvals_head = u; }
	  ups[i] = u;
	} else ups[i] = f->upvals[idx];
      }
      nf = luaP_newfunc(L, cp, ups, nuv);
      RB(ins.a) = funV(nf);
      break; }
    case OP_VARARG: {
      int nvar = L->top - (base + 1 + p->maxstack);
      if (nvar < 0) nvar = 0;
      if (ins.b == 0) {
	int i;
	luaP_setupstack(L, nvar + 4);
	for (i = 0; i < nvar; i++) RB(ins.a + i) = L->stack[base + 1 + p->maxstack + i];
	L->top = base + 1 + ins.a + nvar;
      } else {
	int want = ins.b - 1, i;
	for (i = 0; i < want; i++) {
	  if (i < nvar) RB(ins.a + i) = L->stack[base + 1 + p->maxstack + i];
	  else RB(ins.a + i) = nilV();
	} }
      break; }
    case OP_CLOSE: close_upvals_from(L, L->stack + base + 1 + ins.a); break;
    case OP_NOP: break;
    default: break;
    }
    if (L->nframes <= 0) return;
    fr = &L->frames[L->nframes-1];
    if (fr->kind != FR_LUA) return;
    base = fr->base;
    f = funV2(fr->func);
    p = f->proto;
    code = p->code;
  }
#undef RB
#undef K
#undef RK
}
