    case OP_JMP: pc += ins.c; break;
    case OP_TEST: if (istrue(RB(ins.a)) != (ins.c != 0)) pc++; break;
    case OP_TESTSET: if (istrue(RB(ins.b)) == (ins.c != 0)) RB(ins.a) = RB(ins.b); else pc++; break;
    case OP_EQ: RB(ins.a) = boolV(val_equal(RB(ins.a), RK(ins.b))); break;
    case OP_LT: case OP_LE: { int res;
      lj_compare(L, RK(ins.b), RK(ins.c), ins.op == OP_LT ? MM_LT : MM_LE, &res);
      RB(ins.a) = boolV(res); break; }
    case OP_JEQ: if (val_equal(RB(ins.a), RK(ins.b))) pc += ins.c; break;
    case OP_JNE: if (!val_equal(RB(ins.a), RK(ins.b))) pc += ins.c; break;
    case OP_JLT: { int res; lj_compare(L, RB(ins.a), RK(ins.b), MM_LT, &res);
      if (res) pc += ins.c; break; }
    case OP_JLE: { int res; lj_compare(L, RB(ins.a), RK(ins.b), MM_LE, &res);
      if (res) pc += ins.c; break; }
    case OP_JTRUE: if (istrue(RB(ins.a))) pc += ins.c; break;
    case OP_JFALSE: if (!istrue(RB(ins.a))) pc += ins.c; break;
    case OP_CALL: {
      int a = ins.a, b = ins.b, c = ins.c;
      int funcidx = base + 1 + a;
      int nargs;
      uint8_t nk = (p->callnamekind) ? p->callnamekind[pc-1] : (uint8_t)FRK_NONE;
      Str *nm = (p->callnamekind && p->callnamestr) ? p->callnamestr[pc-1] : NULL;
      if (b == 0) nargs = L->top - funcidx - 1;
      else nargs = b - 1;
      L->frames[L->nframes-1].pc = pc;
      if (c) {
	L->top = funcidx + nargs + 1;
	luaP_docall(L, funcidx, nargs, c, nk, nm);
	L->top = funcidx + c;
      } else {
	L->top = funcidx + nargs + 1;
	luaP_docall(L, funcidx, nargs, 0, nk, nm);
      }
      break; }
    case OP_TAILCALL: {
      int a = ins.a, b = ins.b;
      int funcidx = base + 1 + a;
      int nargs = b ? b - 1 : (L->top - funcidx - 1);
      uint8_t inhk = fr->namewhat; Str *inhn = fr->name;
      int n;
      L->frames[L->nframes-1].pc = pc;
      close_upvals_from(L, L->stack + base + 1);
      L->nframes--;
      if (b == 0) L->top = funcidx + nargs + 1;
      luaP_docall(L, funcidx, nargs, 0, inhk, inhn);
      n = L->top - funcidx;
      if (funcidx != base) memmove(&L->stack[base], &L->stack[funcidx], sizeof(Val) * n);
      L->top = base + n;
      return; }
    case OP_RETURN: {
      int a = ins.a, b = ins.b;
      int n = b ? b - 1 : (L->top - (base + 1 + a));
      L->frames[L->nframes-1].pc = pc;
      close_upvals_from(L, L->stack + base + 1);
      if (a != 0 && n > 0) memmove(&L->stack[base], &L->stack[base + 1 + a], sizeof(Val) * n);
      L->top = base + n;
      L->nframes--;
      return; }
    case OP_FORPREP: {
      Val init = RB(ins.a), limit = RB(ins.a+1), step = RB(ins.a+2);
      double di, dl, ds;
      if (!tonumberV(limit, &dl)) { throw_at(L, "'for' limit must be a number"); }
      if (!tonumberV(step, &ds)) { throw_at(L, "'for' step must be a number"); }
      if (ds == 0) luaP_errorstr(L, "'for' step is zero");
      if (!tonumberV(init, &di)) { throw_at(L, "'for' initial value must be a number"); }
      RB(ins.a) = numV(di - ds);
      RB(ins.a+3) = nilV();
      pc += ins.c;
      break; }
    case OP_FORLOOP: {
      double idx = 0, limit = 0, step = 0;
      tonumberV(RB(ins.a), &idx); tonumberV(RB(ins.a+1), &limit); tonumberV(RB(ins.a+2), &step);
      idx += step;
      if (step > 0 ? idx <= limit : limit <= idx) {
	RB(ins.a) = numV(idx);
	RB(ins.a+3) = numV(idx);
	pc += ins.c;
      } else RB(ins.a+3) = numV(idx);
      break; }
    case OP_TFORCALL: {
      int a = ins.a;
      int funcidx = base + 1 + a;
      L->frames[L->nframes-1].pc = pc;
      L->top = funcidx + 3;
      luaP_docall(L, funcidx, 2, 2, FRK_NONE, NULL);
      L->top = funcidx + 2;
      break; }
    case OP_TFORLOOP: {
      if (!isfalse(RB(ins.a + 3))) { RB(ins.a + 2) = RB(ins.a + 3); pc += ins.c; }
      break; }
    case OP_CLOSURE: {
      int i, nuv;
      Proto *cp;
      UpVal **ups;
      Func *nf;
      if (!p->children || ins.b >= p->nchildren) { RB(ins.a) = nilV(); break; }
      cp = p->children[ins.b];
      nuv = cp->nuv;
      ups = (UpVal**)luaP_malloc(sizeof(UpVal*) * (nuv ? nuv : 1));
      for (i = 0; i < nuv; i++) {
	int inparent = p->uvinfo[2*i];
	int idx = p->uvinfo[2*i+1];
	if (inparent) {
	  UpVal *u = find_upval(L, &L->stack[base + 1 + idx]);
	  if (!u) { u = luaP_newupval(L); u->v = &L->stack[base + 1 + idx];
	    u->closed = 0; u->nextopen = openupvals_head; openupvals_head = u; }
	  ups[i] = u;
	} else ups[i] = f->upvals[idx];
