/* --------------------------------------------------- pcall/xpcall frame -- */
static void unwind_to(Thread *L, int nframes);

static void remove_ctx(ErrCtx **head, ErrCtx *ctx)
{ ErrCtx **pp = head;
  while (*pp) { if (*pp == ctx) { *pp = (*pp)->prev; return; } pp = &(*pp)->prev; } }

static void pcall_cont(Thread *L, int status)
{ Frame *fr = &L->frames[L->nframes-1];
  int base = fr->base;
  int isx = fr->isxpcall;
  ErrCtx ctx;
  int st;
  int nres = fr->nresults;
  int i, n;
  st = lj_protect(L, &ctx, 0);
  fr->ctx = &ctx;
  if (st == 0) {
    luaP_run(L, L->nframes - 1);
    luaP_popframe(L);
    fr->ctx = NULL;
    n = L->top - base;
    { Val *res = (Val*)luaP_malloc(sizeof(Val) * (n + 1));
      res[0] = trueV();
      for (i = 0; i < n; i++) res[i+1] = L->stack[base + i];
      L->top = base;
      luaP_checkstack(L, n + 4);
      for (i = 0; i <= n; i++) L->stack[base + i] = res[i];
      free(res);
      L->top = base + n + 1; }
    finish_call(L, base, n + 1, nres);
    lj_unprotect(L, &ctx);
    return;
  } else {
    Val err = L->stack[L->top-1];
    L->top--;
    unwind_to(L, L->nframes - 1);
    lj_unprotect(L, &ctx);
    if (isx && fr->errfunc.t == TAG_FUN) {
      ErrCtx ctx2; int st2 = lj_protect(L, &ctx2, 0);
      if (st2 == 0) {
	luaP_pushval(L, fr->errfunc);
	luaP_pushval(L, err);
	luaP_docall(L, L->top - 2, 1, 1, FRK_META, NULL);
	err = L->stack[L->top-1];
	L->top--;
	lj_unprotect(L, &ctx2);
      } else { err = L->stack[L->top-1]; L->top--; lj_unprotect(L, &ctx2); }
    }
    luaP_popframe(L);
    { Val *res = (Val*)luaP_malloc(sizeof(Val) * 2);
      res[0] = falseV(); res[1] = err;
      luaP_checkstack(L, 4);
      for (i = 0; i < 2; i++) L->stack[base + i] = res[i];
      free(res);
      L->top = base + 2; }
