void lj_pcall_frame(Thread *L, int funcidx, int nargs, int nresults, Func *f,
		    uint8_t namekind, Str *name)
{ int isx = (f->cf == lib_base_xpcall);
  ErrCtx ctx;
  int st;
  Frame fr;
  int i, n;
  extern CFunction_ lib_base_pcall, lib_base_xpcall;
  memset(&fr, 0, sizeof(fr));
  fr.base = funcidx; fr.kind = FR_C; fr.func = funV(f);
  fr.namewhat = namekind; fr.name = name;
