/* ------------------------------------------------------- tracebacks ------ */
static void tb_frame(Thread *L, int i, char *out, size_t outlen)
{ Frame *fr = &L->frames[i];
  if (fr->kind == FR_LUA) {
    Func *f = funV2(fr->func);
    Proto *p = f ? f->proto : NULL;
    const char *src = (p && p->source) ? p->source->data : "?";
    int line = p ? lj_lineof(p, fr->pc) : -1;
    const char *kw = kindword(fr->namewhat);
    if (p && p->ismain) {
      snprintf(out, outlen, "\t%s:%d: in main chunk", src, line);
    } else if (fr->name && kw) {
      snprintf(out, outlen, "\t%s:%d: in %s '%s'", src, line, kw, fr->name->data);
    } else {
      snprintf(out, outlen, "\t%s:%d: in function <%s:%d>", src, line, src, p ? p->linedefined : 0);
    }
  } else {
    /* C frame */
    if (fr->name) snprintf(out, outlen, "\t[C]: in function '%s'", fr->name->data);
    else {
      Func *f = (fr->func.t == TAG_FUN) ? funV2(fr->func) : NULL;
      unsigned long addr = f ? (unsigned long)(void*)f->cf : 0x0UL;
      snprintf(out, outlen, "\t[C]: at 0x%08lx", addr);
    }
  } }

void lj_print_traceback(Thread *L, int level, FILE *out)
{ int total = L->nframes;
  int i;
  fprintf(out, "stack traceback:\n");
  if (total > 23) {
    int first = 12 - level;
    int cnt = 0;
    if (first < 0) first = 0;
    for (i = level; i < total && cnt < first; i++, cnt++) {
      char buf[1024];
      tb_frame(L, i, buf, sizeof(buf));
      fprintf(out, "%s\n", buf);
    }
    fprintf(out, "\t...\n");
    for (i = total - 10; i < total; i++) {
      char buf[1024];
      if (i < 0) continue;
      tb_frame(L, i, buf, sizeof(buf));
      fprintf(out, "%s\n", buf);
    }
  } else {
    for (i = level; i < total; i++) {
      char buf[1024];
      tb_frame(L, i, buf, sizeof(buf));
      fprintf(out, "%s\n", buf);
    }
  } }

Str *lj_traceback_str(Thread *L, int level)
{ FILE *f = tmpfile();
  char *buf;
  size_t sz;
  Str *s;
  if (!f) return NULL;
  lj_print_traceback(L, level, f);
  sz = (size_t)ftell(f);
  buf = (char*)luaP_malloc(sz + 1);
  rewind(f);
  if (fread(buf, 1, sz, f) != sz) { /* ignore */ }
  buf[sz] = 0;
  fclose(f);
  s = luaP_newstr(L, buf, sz);
  free(buf);
  return s; }

/* debug.traceback(msg, level) */
Str *lj_debug_traceback(Thread *L, Val msg, int level)
{ Str *tb;
  if (!istrue(msg) && msg.t != TAG_NUM) {
    if (msg.t == TAG_NIL) return NULL;
    return strV2(msg);
  }
  tb = lj_traceback_str(L, level);
  if (!tb) return strV2(msg);
  { size_t ml = (size_t)strV2(msg)->len + tb->len + 2;
    char *buf = (char*)luaP_malloc(ml + 1);
    snprintf(buf, ml + 1, "%s\n%s", strV2(msg)->data, tb->data);
    { Str *r = luaP_newstr(L, buf, strlen(buf)); free(buf); return r; } } }

/* ------------------------------------------------------- coroutines ------ */
void luaP_yield(Thread *L, int nargs)
{ int i;
  for (i = L->nframes - 1; i >= 0; i--) {
    Frame *fr = &L->frames[i];
    if (fr->kind == FR_C) {
