/* ------------------------------------------------------- coroutines ------ */
void luaP_yield(Thread *L, int nargs)
{ int i;
  for (i = L->nframes - 1; i >= 0; i--) {
    Frame *fr = &L->frames[i];
    if (fr->kind == FR_C) {
      if (fr->cont) {
	fr->needscont = 1;
	if (fr->ctx) { remove_ctx(&L->ectx, fr->ctx); fr->ctx = NULL; }
      } else luaP_errorstr(L, "attempt to yield across C-call boundary");
    } }
  L->status = 1;
  L->yieldargs = nargs;
  if (!lj_yieldthrow(L)) luaP_errorstr(L, "attempt to yield across C-call boundary"); }

static int cont_scan(Thread *L)
{ int i;
  for (i = L->nframes - 1; i >= 0; i--) {
    Frame *fr = &L->frames[i];
    if (fr->kind == FR_C && fr->cont && fr->needscont) return i;
    if (fr->kind == FR_C && !fr->cont) return -2;   /* cannot continue */
  }
  return -1; }

