/* Lexer */
#include "lex.h"
#include <ctype.h>

static const char *reserved[] = {
  "and", "break", "do", "else", "elseif", "end", "false", "for", "function",
  "goto", "if", "in", "local", "nil", "not", "or", "repeat", "return",
  "then", "true", "until", "while"
};

int lex_isreserved(const char *s, size_t len)
{
  int i;
  for (i = 0; i < (int)(sizeof(reserved)/sizeof(reserved[0])); i++)
    if (strlen(reserved[i]) == len && memcmp(reserved[i], s, len) == 0)
      return TK_AND + i;
  return 0;
}

const char *luaX_tokenname(int token)
{
  switch (token) {
  case TK_AND: return "<and>"; case TK_BREAK: return "<break>";
  case TK_DO: return "<do>"; case TK_ELSE: return "<else>";
  case TK_ELSEIF: return "<elseif>"; case TK_END: return "<end>";
  case TK_FALSE: return "<false>"; case TK_FOR: return "<for>";
  case TK_FUNCTION: return "<function>"; case TK_GOTO: return "<goto>";
  case TK_IF: return "<if>"; case TK_IN: return "<in>";
  case TK_LOCAL: return "<local>"; case TK_NIL: return "<nil>";
  case TK_NOT: return "<not>"; case TK_OR: return "<or>";
  case TK_REPEAT: return "<repeat>"; case TK_RETURN: return "<return>";
  case TK_THEN: return "<then>"; case TK_TRUE: return "<true>";
  case TK_UNTIL: return "<until>"; case TK_WHILE: return "<while>";
  case TK_CONCAT: return "'..'";
  case TK_DOTS: return "'...'";
  case TK_EQ: return "'=='";
  case TK_GE: return "'>='";
  case TK_LE: return "'<='";
  case TK_NE: return "'~='";
  case TK_NUMBER: return "<number>";
  case TK_NAME: return "<name>";
  case TK_STRING: return "<string>";
  case TK_EOS: return "<eof>";
  }
  { static char buf[8];
    if (token >= 32 && token < 127) { buf[0] = (char)token; buf[1] = 0; return buf; }
    snprintf(buf, sizeof(buf), "'%d'", token);
    return buf; }
}

void luaX_init(LexState *ls, Thread *L, const char *src, size_t len, Str *chunkname)
{
  ls->p = src; ls->pe = src + len;
  ls->linenumber = 1; ls->lastline = 1;
  ls->chunkname = chunkname;
  ls->L = L;
  ls->errflag = 0;
  ls->errbuf[0] = 0;
  /* skip a UTF-8 BOM */
  if (len >= 3 && (unsigned char)src[0] == 0xEF && (unsigned char)src[1] == 0xBB && (unsigned char)src[2] == 0xBF)
    ls->p += 3;
  /* skip a shebang line */
  if (ls->p < ls->pe && ls->p[0] == '#' && ls->p[1] == '!') {
    while (ls->p < ls->pe && *ls->p != '\n') ls->p++;
    if (ls->p < ls->pe) ls->p++;
    ls->linenumber = 2;
  }
  luaX_next(ls);
}

static void syntaxerror(LexState *ls, const char *fmt, ...)
{
  char buf[512];
  va_list ap;
  va_start(ap, fmt);
  vsnprintf(buf, sizeof(buf), fmt, ap);
  va_end(ap);
  snprintf(ls->errbuf, sizeof(ls->errbuf), "%s:%d: %s",
	   ls->chunkname ? ls->chunkname->data : "?", ls->linenumber, buf);
  ls->errflag = 1;
  longjmp(ls->errjmp, 1);
}

