#include <ctype.h>
#include <stdarg.h>

static void inclinenumber(LexState *ls)
{ int old = ls->linenumber;
  ls->linenumber++;
  if (ls->linenumber < old) syntaxerror(ls, "chunk has too many lines");
  while (ls->p < ls->pe && (*ls->p == '\r' || *ls->p == '\n')) {
    if (*ls->p == '\n') { ls->p++; break; }
    ls->p++;
  } }

static int curr(LexState *ls) { return (ls->p < ls->pe) ? (unsigned char)*ls->p : -1; }
static void nextc(LexState *ls) { if (ls->p < ls->pe) ls->p++; }

static int check_next1(LexState *ls, int c)
{ if (curr(ls) == c) { nextc(ls); return 1; }
  return 0; }

static int check_next2(LexState *ls, const char *set)
{ if (curr(ls) == (unsigned char)set[0] && ls->p+1 < ls->pe && ls->p[1] == set[1]) {
    ls->p += 2; return 1; }
  return 0; }

/* skip whitespace and comments */
static void skipws(LexState *ls)
{
  for (;;) {
    int c = curr(ls);
    if (c == '\n' || c == '\r') { inclinenumber(ls); continue; }
    if (c == ' ' || c == '\t' || c == '\v' || c == '\f') { nextc(ls); continue; }
    if (c == '-') {
      if (ls->p + 1 < ls->pe && ls->p[1] == '-') {
	/* comment */
	ls->p += 2;
	if (ls->p + 1 < ls->pe && ls->p[0] == '[' && ls->p[1] == '[') {
	  /* long comment */
	  int sep = 0;
	  ls->p += 2;
	  while (ls->p < ls->pe && *ls->p == '=') { sep++; ls->p++; }
	  if (curr(ls) == '[') {
	    ls->p++;
	    for (;;) {
	      if (ls->p >= ls->pe) syntaxerror(ls, "unfinished long comment");
	      if (*ls->p == ']') {
		/* check for the closing sequence ]==] */
		size_t k = 0;
		while (k < (size_t)sep && ls->p + 1 + k < ls->pe && ls->p[1+k] == '=') k++;
		if (k == (size_t)sep && ls->p + 1 + k < ls->pe && ls->p[1+k] == ']') {
		  ls->p += 1 + k + 1;
		  break;
		}
	      }
	      if (*ls->p == '\n' || *ls->p == '\r') inclinenumber(ls); else ls->p++;
	    }
	    continue;
	  }
	}
	/* line comment */
	while (ls->p < ls->pe && *ls->p != '\n' && *ls->p != '\r') ls->p++;
	continue;
      }
      break;
    }
    break;
  }
}

