/* Recursive-descent parser / bytecode generator. */
#include "parse.h"
#include <ctype.h>

#define MAXVARS 200
#define MAXUPVAL 200

/* ------------------------------------------------------------ proto ops -- */
static void ins_reserve(FuncState *fs, int n)
{ Proto *p = fs->proto;
  if (p->ncode + n > fs->codecap) {
    int nc = fs->codecap ? fs->codecap * 2 : 64;
    while (nc < p->ncode + n) nc *= 2;
    { Ins *ni = (Ins*)luaP_malloc(sizeof(Ins) * nc);
      int32_t *nl = (int32_t*)luaP_malloc(sizeof(int32_t) * nc);
      if (p->code) { memcpy(ni, p->code, sizeof(Ins) * p->ncode); free(p->code); }
      if (p->lines) { memcpy(nl, p->lines, sizeof(int32_t) * p->ncode); free(p->lines); }
      else { int i; for (i = 0; i < nc; i++) nl[i] = fs->ls->linenumber; }
      p->code = ni; p->lines = nl;
      { int i; for (i = p->ncode; i < nc; i++) nl[i] = fs->ls->linenumber; }
    }
    fs->codecap = nc;
  } }

static int emit_at(FuncState *fs, Ins ins)
{ Proto *p = fs->proto;
  ins_reserve(fs, 1);
  p->code[p->ncode] = ins;
  p->lines[p->ncode] = fs->ls->linenumber;
  return p->ncode++; }

static int emit(FuncState *fs, int op, int a, int b, int c)
{ Ins ins; ins.op = (uint8_t)op; ins.a = a; ins.b = b; ins.c = c;
  return emit_at(fs, ins); }

static void setline(FuncState *fs, int idx, int line)
{ fs->proto->lines[idx] = line; }

static int addk(FuncState *fs, Val k)
{ Proto *p = fs->proto;
  int i;
  for (i = 0; i < p->nk; i++) {
    if (p->k[i].t == k.t) {
      if (k.t == TAG_NUM) { if (p->k[i].u.n == k.u.n) return i; }
      else if (p->k[i].u.g == k.u.g) return i;
    } }
  if (p->nk >= fs->kcap) {
    int nc = fs->kcap ? fs->kcap * 2 : 16;
    Val *nk = (Val*)luaP_malloc(sizeof(Val) * nc);
    if (p->k) { memcpy(nk, p->k, sizeof(Val) * p->nk); free(p->k); }
    p->k = nk; fs->kcap = nc;
  }
  p->k[p->nk] = k;
  return p->nk++; }

static int addkstr(FuncState *fs, Str *s) { return addk(fs, strV(s)); }
static int addknum(FuncState *fs, double d) { return addk(fs, numV(d)); }

/* registers */
static int newreg(FuncState *fs)
{ int r = fs->freereg++;
  if (fs->freereg > fs->maxreg) fs->maxreg = fs->freereg;
  if (fs->freereg > 200) luaX_error(fs->ls, "function or expression needs too many registers");
  return r; }

static void free_reg(FuncState *fs, int r)
{ if (r + 1 == fs->freereg) fs->freereg = r; }

/* locals */
static int newlocalvar(FuncState *fs, Str *name)
{ int n = fs->nactvar++;
  fs->actvar[n].name = name;
  fs->actvar[n].startpc = fs->proto->ncode;
  return n; }

static int searchlocal(FuncState *fs, Str *name)
{ int i;
  for (i = fs->nactvar - 1; i >= 0; i--)
    if (fs->actvar[i].name == name) return i;
  return -1; }

static int localreg(FuncState *fs, int idx) { return idx; }

static int searchupval(FuncState *fs, Str *name)
{ int i;
  for (i = 0; i < fs->nuv; i++)
    if (fs->upvals[i].name == name) return i;
  return -1; }

static void addupval(FuncState *fs, Str *name, int inparent, int idx)
{ if (fs->nuv >= MAXUPVAL) luaX_error(fs->ls, "too many upvalues");
  fs->upvals[fs->nuv].name = name;
  fs->upvals[fs->nuv].inparent = inparent;
  fs->upvals[fs->nuv].idx = idx;
  fs->nuv++; }

static void singlevaraux(FuncState *fs, Str *name, ExpDesc *e);

static void singlevar(FuncState *fs, Str *name, ExpDesc *e)
{ singlevaraux(fs, name, e); }

static void singlevaraux(FuncState *fs, Str *name, ExpDesc *e)
{ int i = searchlocal(fs, name);
  if (i >= 0) {
    e->k = E_LOCAL; e->reg = i;
    e->nres = 1;
    return;
  }
  i = searchupval(fs, name);
  if (i >= 0) {
    e->k = E_UPVAL; e->reg = i; e->nres = 1;
    return;
  }
  { FuncState *prev = fs->prev;
    if (prev) {
      int j = searchlocal(prev, name);
      if (j >= 0) {
	addupval(fs, name, 1, j);
	e->k = E_UPVAL; e->reg = fs->nuv - 1; e->nres = 1;
	return; } }
  }
  /* global */
  e->k = E_INDEX;
  e->objreg = -1;       /* the env upvalue */
  e->keystr = name;
  e->keyreg = -1;
  e->nres = 1;
  (void)fs;
}
CEOF
echo ok; wc -l lparse.c"}

