/* ------------------------------------------------------- expressions ----- */
static void discharge(FuncState *fs, ExpDesc *e)
{
  switch (e->k) {
  case E_NIL: { int r = newreg(fs); emit(fs, OP_LOADNIL, r, 1, 0); e->k = E_REG; e->reg = r; break; }
  case E_TRUE: { int r = newreg(fs); emit(fs, OP_LOADBOOL, r, 1, 0); e->k = E_REG; e->reg = r; break; }
  case E_FALSE: { int r = newreg(fs); emit(fs, OP_LOADBOOL, r, 0, 0); e->k = E_REG; e->reg = r; break; }
  case E_UPVAL: { int r = newreg(fs); emit(fs, OP_GETUPVAL, r, e->reg, 0); e->k = E_REG; e->reg = r; break; }
  case E_GLOBAL: { int r = newreg(fs); int ki = addkstr(fs, e->keystr);
    emit(fs, OP_GETTABUP, r, 0, ki); e->k = E_REG; e->reg = r; break; }
  case E_INDEX: {
    if (e->objreg < 0) { /* env upvalue */ }
    if (e->keyreg >= 0) {
      int r = newreg(fs);
      emit(fs, OP_GETTABLE, r, e->objreg, e->keyreg);
      free_reg(fs, e->keyreg);
      e->k = E_REG; e->reg = r;
    } else {
      int r = newreg(fs);
      int ki = addkstr(fs, e->keystr);
      emit(fs, OP_GETTAB, r, e->objreg, ki);
      e->k = E_REG; e->reg = r; }
    break; }
  case E_CALL: {
    if (e->nres != 1) { fs->proto->code[e->callpc].c = 1; e->nres = 1; }
    e->k = E_REG;
    break; }
  case E_VARARG: {
    fs->proto->code[e->callpc].b = 2;
    e->nres = 1;
    e->k = E_REG;
    break; }
  case E_REG: break;
  }
}

static int to_reg(FuncState *fs, ExpDesc *e)
{ discharge(fs, e);
  if (e->k != E_REG && e->k != E_LOCAL) { /* shouldn't happen */ }
  return e->reg; }

static int to_topreg(FuncState *fs, ExpDesc *e)
{ int r = to_reg(fs, e);
  if (r != fs->freereg - 1) {
    int nr = newreg(fs);
    emit(fs, OP_MOVE, nr, r);
    r = nr;
  }
  return r; }

/* mark a multret expression as producing a single value at a given register */
static void set_one_result(FuncState *fs, ExpDesc *e)
{ if (e->k == E_CALL) {
    if (e->nres != 1) { fs->proto->code[e->callpc].c = 1; e->nres = 1; e->k = E_REG; }
  } else if (e->k == E_VARARG) {
    fs->proto->code[e->callpc].b = 2; e->nres = 1; e->k = E_REG; } }

/* ------------------------------------------------------- function calls -- */
static void funcargs(FuncState *fs, ExpDesc *e, int line)
{
  LexState *ls = fs->ls;
  int freg;
  int nparams = 0;
  int multret = 0;
  switch (ls->t.token) {
  case '(': {
    luaX_next(ls);
    freg = to_topreg(fs, e);
    if (fs->freereg != freg + 1) { /* ensure the next free register is freg+1 */
      fs->freereg = freg + 1; }
    if (ls->t.token != ')') {
      ExpDesc arg;
      int first = 1;
      for (;;) {
	int islast;
	/* peek: parse the expression */
	subexpr(fs, &arg, 0);
	islast = (ls->t.token != ',');
	if (!islast) { luaX_next(ls); }
	if (arg.k == E_CALL || arg.k == E_VARARG) {
	  if (islast) { multret = 1; /* keep multret: the results are at arg.reg..top */ 
	    nparams = -1;   /* computed at runtime */
	    break; }
	  else set_one_result(fs, &arg);
	} else {
	  discharge(fs, &arg);
	}
	nparams++;
	if (islast) break;
      }
    }
    check_match(ls, ')', '(', line);
    break; }
  case TK_STRING: {
    Str *s = ls->t.s;
    int r;
    luaX_next(ls);
    freg = to_topreg(fs, e);
    fs->freereg = freg + 1;
    r = newreg(fs);
    emit(fs, OP_LOADK, r, addkstr(fs, s), 0);
    nparams = 1;
    break; }
  case '{': {
    int r;
    freg = to_topreg(fs, e);
    fs->freereg = freg + 1;
    r = newreg(fs);
    tablector(fs, &r);
    nparams = 1;
    break; }
  default: luaX_error(ls, "function arguments expected near '%s'", luaX_tokenname(ls->t.token));
    return;
  }
  /* record the call name */
  { int pc;
    if (multret) pc = emit(fs, OP_CALL, freg, 0, 0);
    else pc = emit(fs, OP_CALL, freg, nparams + 1, 0);
    setcallname(fs, pc, e);
    e->k = E_CALL;
    e->reg = freg;
    e->callpc = pc;
    e->nres = 0;
    if (multret) fs->freereg = freg;
    else fs->freereg = freg + 1; }
  (void)line;
}
