void luaX_error(LexState *ls, const char *fmt, ...)
{
  char buf[512];
  va_list ap;
  va_start(ap, fmt);
  vsnprintf(buf, sizeof(buf), fmt, ap);
  va_end(ap);
  snprintf(ls->errbuf, sizeof(ls->errbuf), "%s:%d: %s",
	   ls->chunkname ? ls->chunkname->data : "?", ls->linenumber, buf);
  ls->errflag = 1;
  longjmp(ls->errjmp, 1);
}

void check_match(LexState *ls, int what, int who, int who_line)
{
  if (ls->t.token != what) {
    if (who_line == ls->linenumber)
      luaX_error(ls, "'%s' expected near '%s'", luaX_tokenname(what), luaX_tokenname(ls->t.token));
    else {
      char msg[256];
      snprintf(msg, sizeof(msg), "'%s' expected (to close '%s' at line %d) near '%s'",
	       luaX_tokenname(what), luaX_tokenname(who), who_line, luaX_tokenname(ls->t.token));
      { /* Lua reports this error at the line of the mismatching token */
	int saved = ls->linenumber;
	(void)saved;
	luaX_error(ls, "%s", msg); }
    }
  }
  luaX_next(ls);
}

