  case E_FALSE: { int r = newreg(fs); emit(fs, OP_LOADBOOL, r, 0, 0); e->k = E_REG; e->reg = r; break; }
  case E_UPVAL: { int r = newreg(fs); emit(fs, OP_GETUPVAL, r, e->reg, 0); e->k = E_REG; e->reg = r; break; }
