/* ------------------------------------------------------ table constructor */
static void tablector(FuncState *fs, ExpDesc *e)
{ LexState *ls = fs->ls;
  int line = ls->linenumber;
  int narr = 0, nhash = 0;
  int treg;
  int flushidx = 0;
  luaX_next(ls);   /* skip '{' */
  treg = newreg(fs);
  emit(fs, OP_NEWTABLE, treg, 0, 0);
  e->k = E_REG; e->reg = treg; e->nres = 1;
  if (ls->t.token == '}') { luaX_next(ls); return; }
  for (;;) {
    ExpDesc key, val;
    int iskey = 0;
    key.k = E_VOID;
    if (ls->t.token == '[') {
      int l2 = ls->linenumber;
      luaX_next(ls);
      subexpr(fs, &key, 0);
      check_match(ls, ']', '[', l2);
      if (ls->t.token != '=') luaX_error(ls, "'=' expected near '%s'", luaX_tokenname(ls->t.token));
      luaX_next(ls);
      iskey = 1;
      subexpr(fs, &val, 0);
      if (val.k == E_CALL || val.k == E_VARARG) { /* single result */ set_one(fs, &val); }
    } else if (ls->t.token == TK_NAME) {
      Str *kname = ls->t.s;
