	/* positional value: the key is the name itself */
	key.k = E_REG; /* the name as a value */
	/* hmm: in Lua, `{name}` means `["name"] = name` */
	key.k = E_VOID;
	{ int r = newreg(fs); emit(fs, OP_LOADK, r, addkstr(fs, kname), 0);
	  key.k = E_REG; key.reg = r; }
	iskey = 0;
	subexpr(fs, &val, 0);
	if (val.k == E_CALL || val.k == E_VARARG) set_one(fs, &val);
	/* the key is the *name string*, the value is the variable `name` */
	{ ExpDesc v2; singlevar(fs, kname, &v2);
	  discharge(fs, &v2);
	  val = v2; }
      } else {
	luaX_next(ls);
	iskey = 1;
	subexpr(fs, &val, 0);
	if (val.k == E_CALL || val.k == E_VARARG) set_one(fs, &val);
	key.k = E_VOID;
	{ int r = newreg(fs); emit(fs, OP_LOADK, r, addkstr(fs, kname), 0);
	  key.k = E_REG; key.reg = r; }
      }
    } else {
      subexpr(fs, &val, 0);
      if (ls->t.token == ',' || ls->t.token == '}') {
	if (val.k == E_CALL || val.k == E_VARARG) {
	  if (ls->t.token == '}') { /* multret: flush as list items */ }
	  else set_one(fs, &val);
	} else discharge(fs, &val);
	iskey = 0;
	key.k = E_VOID;
      } else luaX_error(ls, "'}' expected near '%s'", luaX_tokenname(ls->t.token));
    }
