      /* we need: t[key] = val -> OP_SETTABLE with a=0 unused */
      { Ins *ins = &fs->proto->code[fs->proto->ncode-1];
	ins->op = OP_SETTABLE; ins->a = vr; ins->b = treg; ins->c = kr; }
      nhash++;
      fs->freereg = treg + 1;
    } else {
      int vr = to_reg(fs, &val);
      if (flushidx == 0) flushidx = narr + 1;
      narr++;
      /* store into the table at position narr */
      emit(fs, OP_SETLIST, treg, 1, narr);
      /* patch: the value register is treg+1 */
      { Ins *ins = &fs->proto->code[fs->proto->ncode-1];
	ins->op = OP_SETLIST; ins->a = treg; ins->b = 1; ins->c = narr; }
      (void)vr;
      fs->freereg = treg + 1;
    }
    if (ls->t.token == ',' || ls->t.token == ';') { luaX_next(ls); continue; }
    if (ls->t.token == '}') { luaX_next(ls); break; }
    luaX_error(ls, "'}' expected near '%s'", luaX_tokenname(ls->t.token));
  }
  /* patch the NEWTABLE with the final sizes */
  { Ins *ins = &fs->proto->code[fs->newtablepc];
    ins->b = narr; ins->c = nhash ? nhash : 0; }
  fs->freereg = treg + 1;
}
