{"command": "cd /workspace/src && cat > lparse.c <<'CEOF'
/* Recursive-descent parser / bytecode generator. */
#include "parse.h"
#include <ctype.h>
#include <stdarg.h>

#define MAXREGS 190

void luaX_error(LexState *ls, const char *fmt, ...)
{ char buf[512]; va_list ap;
  va_start(ap, fmt); vsnprintf(buf, sizeof(buf), fmt, ap); va_end(ap);
  snprintf(ls->errbuf, sizeof(ls->errbuf), "%s:%d: %s",
	   ls->chunkname ? ls->chunkname->data : "?", ls->linenumber, buf);
  ls->errflag = 1;
  longjmp(ls->errjmp, 1); }

/* --------------------------------------------------------- proto helpers - */
static void ins_reserve(FuncState *fs, int n)
{ Proto *p = fs->proto;
  if (p->ncode + n > fs->codecap) {
    int nc = fs->codecap ? fs->codecap * 2 : 64;
    Ins *ni; int32_t *nl; int i;
    while (nc < p->ncode + n) nc *= 2;
    ni = (Ins*)luaP_malloc(sizeof(Ins) * nc);
    nl = (int32_t*)luaP_malloc(sizeof(int32_t) * nc);
    if (p->code) { memcpy(ni, p->code, sizeof(Ins) * p->ncode); free(p->code); }
    if (p->lines) { memcpy(nl, p->lines, sizeof(int32_t) * p->ncode); free(p->lines); }
    for (i = 0; i < nc; i++) nl[i] = fs->ls->linenumber;
    if (p->callnamekind) {
      uint8_t *ck = (uint8_t*)luaP_malloc(nc);
      Str **cs = (Str**)luaP_malloc(sizeof(Str*) * nc);
      memcpy(ck, p->callnamekind, p->ncode);
      memcpy(cs, p->callnamestr, sizeof(Str*) * p->ncode);
      free(p->callnamekind); free(p->callnamestr);
      p->callnamekind = ck; p->callnamestr = cs;
    }
    p->code = ni; p->lines = nl;
    fs->codecap = nc;
  } }

static int emit(FuncState *fs, int op, int a, int b, int c)
{ Proto *p = fs->proto; Ins ins;
  ins_reserve(fs, 1);
  ins.op = (uint8_t)op; ins.a = a; ins.b = b; ins.c = c;
  p->code[p->ncode] = ins;
  p->lines[p->ncode] = fs->ls->linenumber;
  return p->ncode++; }

static int addk(FuncState *fs, Val k)
{ Proto *p = fs->proto; int i;
  for (i = 0; i < p->nk; i++) {
    if (p->k[i].t == k.t) {
      if (k.t == TAG_NUM) { if (p->k[i].u.n == k.u.n) return i; }
      else if (p->k[i].u.g == k.u.g) return i;
    } }
  if (p->nk >= fs->kcap) {
    int nc = fs->kcap ? fs->kcap * 2 : 16;
    Val *nk = (Val*)luaP_malloc(sizeof(Val) * nc);
    if (p->k) { memcpy(nk, p->k, sizeof(Val) * p->nk); free(p->k); }
    p->k = nk; fs->kcap = nc;
  }
  p->k[p->nk] = k;
  return p->nk++; }

static int addkstr(FuncState *fs, Str *s) { return addk(fs, strV(s)); }

/* ------------------------------------------------------------ registers -- */
static void set_maxreg(FuncState *fs, int r)
{ if (r + 1 > fs->maxreg) fs->maxreg = r + 1; }

static int newreg(FuncState *fs)
{ int r = fs->freereg++;
  set_maxreg(fs, r);
  if (fs->freereg > MAXREGS) luaX_error(fs->ls, "function or expression needs too many registers");
  return r; }

/* ------------------------------------------------------------ locals ----- */
static int newlocalvar(FuncState *fs, Str *name)
{ int n = fs->nactvar++;
  fs->actvar[n].name = name;
  fs->actvar[n].startpc = fs->proto->ncode;
  return n; }

static int searchlocal(FuncState *fs, Str *name)
{ int i;
  for (i = fs->nactvar - 1; i >= 0; i--)
    if (fs->actvar[i].name == name) return i;
  return -1; }

static int searchupval(FuncState *fs, Str *name)
{ int i;
  for (i = 0; i < fs->nuv; i++)
    if (fs->upvals[i].name == name) return i;
  return -1; }

static void markparentupval(FuncState *fs, int localidx)
{ FuncState *prev = fs->prev;
  BlockCtx *b;
  if (!prev) return;
  for (b = prev->blocks; b; b = b->prev) {
    if (b->nactvar0 <= localidx) b->hasupval = 1;
  } }

static void addupval(FuncState *fs, Str *name, int inparent, int idx)
{ if (fs->nuv >= MAXUPVAL) luaX_error(fs->ls, "too many upvalues");
  fs->upvals[fs->nuv].name = name;
  fs->upvals[fs->nuv].inparent = inparent;
  fs->upvals[fs->nuv].idx = idx;
  fs->nuv++; }

/* ---------------------------------------------------------- expressions -- */
static void subexpr(FuncState *fs, ExpDesc *e, int limit);
static void simpleexp(FuncState *fs, ExpDesc *e);
static void primaryexp(FuncState *fs, ExpDesc *e);
static void statement(FuncState *fs);
static void block(FuncState *fs);
static void funcargs(FuncState *fs, ExpDesc *e, int line, int selfmethod);
static void tablector(FuncState *fs, ExpDesc *e);
static void body(FuncState *fs, ExpDesc *e, int ismethod, int line);
static void explist(FuncState *fs, ExpDesc *v, int *n, int *lastmulti);

static void discharge(FuncState *fs, ExpDesc *e)
{ switch (e->k) {
  case E_NIL: { int r = newreg(fs); emit(fs, OP_LOADNIL, r, 1, 0); e->k = E_REG; e->reg = r; break; }
  case E_TRUE: { int r = newreg(fs); emit(fs, OP_LOADBOOL, r, 1, 0); e->k = E_REG; e->reg = r; break; }
  case E_FALSE: { int r = newreg(fs); emit(fs, OP_LOADBOOL, r, 0, 0); e->k = E_REG; e->reg = r; break; }
  case E_UPVAL: { int r = newreg(fs); emit(fs, OP_GETUPVAL, r, e->reg, 0); e->k = E_REG; e->reg = r; break; }
  case E_GLOBAL: { int r = newreg(fs); int ki = addkstr(fs, e->keystr);
    emit(fs, OP_GETTABUP, r, 0, ki); e->k = E_REG; e->reg = r; break; }
  case E_INDEX: {
    if (e->keyreg >= 0) {
      int r = newreg(fs);
      emit(fs, OP_GETTABLE, r, e->objreg, e->keyreg);
      e->k = E_REG; e->reg = r;
      fs->freereg = r + 1;
    } else {
      int r = newreg(fs);
      int ki = addkstr(fs, e->keystr);
      emit(fs, OP_GETTAB, r, e->objreg, ki);
      e->k = E_REG; e->reg = r;
      fs->freereg = r + 1; }
    break; }
  case E_CALL: { if (e->nres != 1) { fs->proto->code[e->callpc].c = 1; e->nres = 1; }
    e->k = E_REG; fs->freereg = e->reg + 1; break; }
  case E_VARARG: { fs->proto->code[e->callpc].b = 2; e->nres = 1; e->k = E_REG;
    fs->freereg = e->reg + 1; break; }
  case E_REG: fs->freereg = e->reg + 1; break;
  case E_LOCAL: fs->freereg = e->reg + 1; break;
  } }

static int to_reg(FuncState *fs, ExpDesc *e) { discharge(fs, e); return e->reg; }

static int to_topreg(FuncState *fs, ExpDesc *e)
{ int r = to_reg(fs, e);
  if (r != fs->freereg - 1) { int nr = newreg(fs); emit(fs, OP_MOVE, nr, r); r = nr; }
  return r; }

static void singlevar(FuncState *fs, Str *name, ExpDesc *e)
{ int i = searchlocal(fs, name);
  if (i >= 0) { e->k = E_LOCAL; e->reg = i; e->nres = 1; return; }
  i = searchupval(fs, name);
  if (i >= 0) { e->k = E_UPVAL; e->reg = i; e->nres = 1; return; }
  if (fs->prev) {
    int j = searchlocal(fs->prev, name);
    if (j >= 0) {
      addupval(fs, name, 1, j);
      markparentupval(fs, j);
      e->k = E_UPVAL; e->reg = fs->nuv - 1; e->nres = 1;
      return; } }
  e->k = E_GLOBAL; e->keystr = name; e->keyreg = -1; e->objreg = 0; e->nres = 1; }

static void setcallname(FuncState *fs, int pc, ExpDesc *e)
{ Proto *p = fs->proto;
  uint8_t kind = FRK_NONE;
  Str *nm = NULL;
  switch (e->k) {
  case E_LOCAL: { int i;
    kind = FRK_LOCAL;
    for (i = 0; i < fs->nactvar; i++) if (i == e->reg) { nm = fs->actvar[i].name; break; }
    break; }
  case E_INDEX: kind = FRK_FIELD; nm = e->keystr; break;
  case E_GLOBAL: kind = FRK_GLOBAL; nm = e->keystr; break;
  case E_UPVAL: kind = FRK_UPVAL; nm = fs->upvals[e->reg].name; break;
  default: kind = FRK_NONE; break;
  }
  if (!p->callnamekind) {
    p->callnamekind = (uint8_t*)luaP_malloc(fs->codecap);
    p->callnamestr = (Str**)luaP_malloc(sizeof(Str*) * fs->codecap);
    memset(p->callnamestr, 0, sizeof(Str*) * fs->codecap);
  }
  p->callnamekind[pc] = kind;
  p->callnamestr[pc] = nm; }

void check_match(LexState *ls, int what, int who, int who_line)
{ if (ls->t.token != what) {
    if (who_line == ls->linenumber)
      luaX_error(ls, "'%s' expected near '%s'", luaX_tokenname(what), luaX_tokenname(ls->t.token));
    else
      luaX_error(ls, "'%s' expected (to close '%s' at line %d) near '%s'",
		 luaX_tokenname(what), luaX_tokenname(who), who_line, luaX_tokenname(ls->t.token));
  }
  luaX_next(ls); }

/* ------------------------------------------------------ table constructor */
static void tablector(FuncState *fs, ExpDesc *e)
{ LexState *ls = fs->ls;
  int line = ls->linenumber;
  int narr = 0, nhash = 0;
  int treg;
  int flushidx = 0;
  luaX_next(ls);   /* skip '{' */
  treg = newreg(fs);
  emit(fs, OP_NEWTABLE, treg, 0, 0);
  e->k = E_REG; e->reg = treg; e->nres = 1;
  if (ls->t.token == '}') { luaX_next(ls); return; }
  for (;;) {
    ExpDesc key, val;
    int iskey = 0;
    key.k = E_VOID;
    if (ls->t.token == '[') {
      int l2 = ls->linenumber;
      luaX_next(ls);
      subexpr(fs, &key, 0);
      check_match(ls, ']', '[', l2);
      if (ls->t.token != '=') luaX_error(ls, "'=' expected near '%s'", luaX_tokenname(ls->t.token));
      luaX_next(ls);
      iskey = 1;
      subexpr(fs, &val, 0);
      if (val.k == E_CALL || val.k == E_VARARG) { /* single result */ set_one(fs, &val); }
    } else if (ls->t.token == TK_NAME) {
      Str *kname = ls->t.s;
      luaX_next(ls);
      if (ls->t.token != '=') {
	/* positional value: the key is the name itself */
	key.k = E_REG; /* the name as a value */
	/* hmm: in Lua, `{name}` means `["name"] = name` */
	key.k = E_VOID;
	{ int r = newreg(fs); emit(fs, OP_LOADK, r, addkstr(fs, kname), 0);
	  key.k = E_REG; key.reg = r; }
	iskey = 0;
	subexpr(fs, &val, 0);
	if (val.k == E_CALL || val.k == E_VARARG) set_one(fs, &val);
	/* the key is the *name string*, the value is the variable `name` */
	{ ExpDesc v2; singlevar(fs, kname, &v2);
	  discharge(fs, &v2);
	  val = v2; }
      } else {
	luaX_next(ls);
	iskey = 1;
	subexpr(fs, &val, 0);
	if (val.k == E_CALL || val.k == E_VARARG) set_one(fs, &val);
	key.k = E_VOID;
	{ int r = newreg(fs); emit(fs, OP_LOADK, r, addkstr(fs, kname), 0);
	  key.k = E_REG; key.reg = r; }
      }
    } else {
      subexpr(fs, &val, 0);
      if (ls->t.token == ',' || ls->t.token == '}') {
	if (val.k == E_CALL || val.k == E_VARARG) {
	  if (ls->t.token == '}') { /* multret: flush as list items */ }
	  else set_one(fs, &val);
	} else discharge(fs, &val);
	iskey = 0;
	key.k = E_VOID;
      } else luaX_error(ls, "'}' expected near '%s'", luaX_tokenname(ls->t.token));
    }
    if (iskey) {
      int vr = to_reg(fs, &val);
      int kr = to_reg(fs, &key);
      emit(fs, OP_SETTABLE, 0, treg, kr);   /* placeholder; handled below */
      /* we need: t[key] = val -> OP_SETTABLE with a=0 unused */
      { Ins *ins = &fs->proto->code[fs->proto->ncode-1];
	ins->op = OP_SETTABLE; ins->a = vr; ins->b = treg; ins->c = kr; }
      nhash++;
      fs->freereg = treg + 1;
    } else {
      int vr = to_reg(fs, &val);
      if (flushidx == 0) flushidx = narr + 1;
      narr++;
      /* store into the table at position narr */
      emit(fs, OP_SETLIST, treg, 1, narr);
      /* patch: the value register is treg+1 */
      { Ins *ins = &fs->proto->code[fs->proto->ncode-1];
	ins->op = OP_SETLIST; ins->a = treg; ins->b = 1; ins->c = narr; }
      (void)vr;
      fs->freereg = treg + 1;
    }
    if (ls->t.token == ',' || ls->t.token == ';') { luaX_next(ls); continue; }
    if (ls->t.token == '}') { luaX_next(ls); break; }
    luaX_error(ls, "'}' expected near '%s'", luaX_tokenname(ls->t.token));
  }
  /* patch the NEWTABLE with the final sizes */
  { Ins *ins = &fs->proto->code[fs->newtablepc];
    ins->b = narr; ins->c = nhash ? nhash : 0; }
  fs->freereg = treg + 1;
}
