cat >> lparse.c <<'CEOF'

static void set_one_result(FuncState *fs, ExpDesc *e)
{ if (e->k == E_CALL) { if (e->nres != 1) { fs->proto->code[e->callpc].c = 1; e->nres = 1; e->k = E_REG; } }
  else if (e->k == E_VARARG) { fs->proto->code[e->callpc].b = 2; e->nres = 1; e->k = E_REG; } }

/* ------------------------------------------------------ table constructor */
static void tablector(FuncState *fs, ExpDesc *e)
{ LexState *ls = fs->ls;
  int line = ls->linenumber;
  int narr = 0, nhash = 0;
  int treg;
  int ismulti = 0;
  luaX_next(ls);
  treg = newreg(fs);
  fs->newtablepc = fs->proto->ncode;
  emit(fs, OP_NEWTABLE, treg, 0, 0);
  e->k = E_REG; e->reg = treg; e->nres = 1;
  if (ls->t.token == '}') { luaX_next(ls); fs->freereg = treg + 1; return; }
  for (;;) {
    ExpDesc key, val;
    int iskey = 0;
    key.k = E_VOID; key.reg = -1; key.keystr = NULL; key.keyreg = -1; key.objreg = -1;
    key.callpc = 0; key.nres = 1;
    val.k = E_VOID; val.reg = -1; val.keystr = NULL; val.keyreg = -1; val.objreg = -1;
    val.callpc = 0; val.nres = 1;
    if (ls->t.token == '[') {
      int l2 = ls->linenumber;
      luaX_next(ls);
      subexpr(fs, &key, 0);
      check_match(ls, ']', '[', l2);
      if (ls->t.token != '=') luaX_error(ls, "'=' expected near '%s'", luaX_tokenname(ls->t.token));
      luaX_next(ls);
      iskey = 1;
      subexpr(fs, &val, 0);
      if (val.k == E_CALL || val.k == E_VARARG) set_one_result(fs, &val);
      else discharge(fs, &val);
    } else if (ls->t.token == TK_NAME && ls->t.s) {
      Str *kname = ls->t.s;
      luaX_next(ls);
      if (ls->t.token == '=') {
	luaX_next(ls);
	iskey = 1;
	{ int r = newreg(fs); emit(fs, OP_LOADK, r, addkstr(fs, kname), 0);
	  key.k = E_REG; key.reg = r; }
	subexpr(fs, &val, 0);
	if (val.k == E_CALL || val.k == E_VARARG) set_one_result(fs, &val);
	else discharge(fs, &val);
      } else {
	{ int r = newreg(fs); emit(fs, OP_LOADK, r, addkstr(fs, kname), 0);
	  key.k = E_REG; key.reg = r; }
	{ ExpDesc v2; singlevar(fs, kname, &v2);
	  discharge(fs, &v2);
	  val = v2; }
	iskey = 0;
      }
    } else {
      subexpr(fs, &val, 0);
      if (val.k == E_CALL || val.k == E_VARARG) {
	if (ls->t.token == ',') set_one_result(fs, &val);
	else { ismulti = 1; }
      } else discharge(fs, &val);
      iskey = 0;
    }
    if (iskey) {
      int vr = to_reg(fs, &val);
      int kr = to_reg(fs, &key);
      emit(fs, OP_SETTABLE, vr, treg, kr);
      nhash++;
      fs->freereg = treg + 1;
    } else if (ismulti) {
      emit(fs, OP_SETLIST, treg, 0, narr + 1);
      narr += 0;   /* unknown count */
      fs->freereg = treg + 1;
    } else {
      int vr = to_reg(fs, &val);
      if (vr != treg + 1) { int nr = newreg(fs); emit(fs, OP_MOVE, nr, vr); vr = nr; }
      emit(fs, OP_SETLIST, treg, 1, narr + 1);
      narr++;
      fs->freereg = treg + 1;
    }
    if (ls->t.token == ',' || ls->t.token == ';') { luaX_next(ls);
      if (ismulti) { ismulti = 0; }
      continue; }
    if (ls->t.token == '}') { luaX_next(ls); break; }
    luaX_error(ls, "'}' expected near '%s'", luaX_tokenname(ls->t.token));
  }
  { Ins *ins = &fs->proto->code[fs->newtablepc];
    ins->b = narr; ins->c = nhash; }
  fs->freereg = treg + 1;
  (void)line;
}

/* ------------------------------------------------------------ func args -- */
static void funcargs(FuncState *fs, ExpDesc *e, int line, int selfmethod)
{ LexState *ls = fs->ls;
  int freg = e->reg;
  int nparams = selfmethod ? 1 : 0;
  int multret = 0;
  switch (ls->t.token) {
  case '(': {
    int l2 = ls->linenumber;
    luaX_next(ls);
    fs->freereg = freg + 1 + nparams;
    if (ls->t.token != ')') {
      int first = 1;
      for (;;) {
	ExpDesc arg;
	int islast;
	arg.k = E_VOID; arg.reg = -1; arg.keystr = NULL; arg.keyreg = -1;
	arg.objreg = -1; arg.callpc = 0; arg.nres = 1;
	subexpr(fs, &arg, 0);
	islast = (ls->t.token != ',');
	if (!islast) luaX_next(ls);
	if (arg.k == E_CALL || arg.k == E_VARARG) {
	  if (islast) { multret = 1; break; }
	  set_one_result(fs, &arg);
	} else discharge(fs, &arg);
	nparams++;
	if (islast) break;
	first = 0;
      }
    }
    check_match(ls, ')', '(', l2);
    break; }
  case TK_STRING: {
    Str *s = ls->t.s;
    int r;
    luaX_next(ls);
    fs->freereg = freg + 1 + nparams;
    r = newreg(fs);
    emit(fs, OP_LOADK, r, addkstr(fs, s), 0);
    nparams++;
    fs->freereg = r + 1;
    break; }
  case '{': {
    ExpDesc arg;
    int r;
    arg.k = E_VOID; arg.reg = -1; arg.keystr = NULL; arg.keyreg = -1;
    arg.objreg = -1; arg.callpc = 0; arg.nres = 1;
    fs->freereg = freg + 1 + nparams;
    r = newreg(fs);
    arg.k = E_REG; arg.reg = r; arg.nres = 1;
    tablector(fs, &arg);
    nparams++;
    fs->freereg = r + 1;
    break; }
  default:
    luaX_error(ls, "function arguments expected near '%s'", luaX_tokenname(ls->t.token));
    return;
  }
  { int pc;
    if (multret) pc = emit(fs, OP_CALL, freg, 0, 0);
    else pc = emit(fs, OP_CALL, freg, nparams + 1, 0);
    setcallname(fs, pc, e);
    e->k = E_CALL;
    e->reg = freg;
    e->callpc = pc;
    e->nres = 0;
    fs->freereg = freg + 1; }
  (void)line;
}

/* --------------------------------------------------------- primary exp --- */
static void primaryexp(FuncState *fs, ExpDesc *e)
{ LexState *ls = fs->ls;
  int line = ls->linenumber;
  switch (ls->t.token) {
  case '(': {
    luaX_next(ls);
    subexpr(fs, e, 0);
    check_match(ls, ')', '(', line);
