  case TK_NAME: {
    Str *name = ls->t.s;
    luaX_next(ls);
    singlevar(fs, name, e);
    break; }
  default:
    luaX_error(ls, "unexpected symbol near '%s'", luaX_tokenname(ls->t.token));
