    switch (ls->t.token) {
    case '.': {
      Str *key;
      luaX_next(ls);
      if (ls->t.token != TK_NAME) luaX_error(ls, "'<name>' expected near '%s'", luaX_tokenname(ls->t.token));
      key = ls->t.s;
      luaX_next(ls);
      if (e->k == E_CALL || e->k == E_VARARG) set_one_result(fs, e);
      if (e->k == E_GLOBAL || e->k == E_UPVAL) discharge(fs, e);
      if (e->k == E_LOCAL) discharge(fs, e);
      if (e->k == E_INDEX) discharge(fs, e);
