      e->k = E_INDEX;
      e->objreg = e->reg;
      e->keystr = key;
      e->keyreg = -1;
      fs->freereg = e->reg + 1;
      break; }
    case '[': {
      ExpDesc key;
      int l2 = ls->linenumber;
      luaX_next(ls);
      subexpr(fs, &key, 0);
      check_match(ls, ']', '[', l2);
      if (e->k == E_CALL || e->k == E_VARARG) set_one_result(fs, e);
      if (key.k == E_CALL || key.k == E_VARARG) set_one_result(fs, &key);
      discharge(fs, &key);
      discharge(fs, e);
      e->k = E_INDEX;
      e->objreg = e->reg;
      e->keyreg = key.reg;
      e->keystr = NULL;
      break; }
    case ':': {
      Str *key;
      luaX_next(ls);
      if (ls->t.token != TK_NAME) luaX_error(ls, "'<name>' expected near '%s'", luaX_tokenname(ls->t.token));
      key = ls->t.s;
      luaX_next(ls);
      if (e->k == E_CALL || e->k == E_VARARG) set_one_result(fs, e);
      if (e->k == E_GLOBAL || e->k == E_UPVAL || e->k == E_INDEX) discharge(fs, e);
      if (e->k == E_LOCAL) { int r = to_topreg(fs, e); e->reg = r; e->k = E_REG; }
      { int objreg = e->reg;
	int ki = addkstr(fs, key);
