	fs->freereg = objreg + 2;
	{ ExpDesc tmp;
	  tmp.k = E_REG; tmp.reg = objreg; tmp.nres = 1; tmp.callpc = 0;
	  tmp.objreg = -1; tmp.keyreg = -1; tmp.keystr = NULL;
	  funcargs(fs, &tmp, ls->linenumber, 1);
	  e->k = E_CALL; e->reg = objreg; e->callpc = fs->proto->ncode - 1;
	  e->nres = 0;
	  /* fix up the call name: the method name */
	  { Proto *p = fs->proto;
	    if (p->callnamekind) {
	      p->callnamekind[fs->proto->ncode-1] = FRK_METHOD;
	      p->callnamestr[fs->proto->ncode-1] = key; } }
	  fs->freereg = objreg + 1; } }
      break; }
    case '(': case TK_STRING: case '{': {
      if (e->k == E_CALL || e->k == E_VARARG) set_one_result(fs, e);
      if (e->k == E_GLOBAL || e->k == E_UPVAL || e->k == E_INDEX) discharge(fs, e);
      if (e->k == E_LOCAL) { int r = to_topreg(fs, e); e->reg = r; e->k = E_REG; }
      funcargs(fs, e, ls->linenumber, 0);
      break; }
    default:
      return;
    } } }

/* ---------------------------------------------------------- simple exp --- */
static void simpleexp(FuncState *fs, ExpDesc *e)
{ LexState *ls = fs->ls;
  switch (ls->t.token) {
  case TK_NUMBER: {
    int r = newreg(fs);
    emit(fs, OP_LOADK, r, addk(fs, numV(ls->t.r)), 0);
