    e->k = E_REG; e->reg = r; e->nres = 1;
    luaX_next(ls);
    break; }
  case TK_NIL: { e->k = E_NIL; e->nres = 1; luaX_next(ls); break; }
  case TK_TRUE: { e->k = E_TRUE; e->nres = 1; luaX_next(ls); break; }
  case TK_FALSE: { e->k = E_FALSE; e->nres = 1; luaX_next(ls); break; }
  case TK_DOTS: {
    int r = newreg(fs);
    int pc = emit(fs, OP_VARARG, r, 0, 0);
    e->k = E_VARARG; e->reg = r; e->callpc = pc; e->nres = 0;
    luaX_next(ls);
