    if (b->nactvar0 <= localidx) b->hasupval = 1; }

static void addupval(FuncState *fs, Str *name, int inparent, int idx)
{ if (fs->nuv >= MAXUPVAL) luaX_error(fs->ls, "too many upvalues");
