static void discharge(FuncState *fs, ExpDesc *e)
{ switch (e->k) {
  case E_NIL: { int r = newreg(fs); emit(fs, OP_LOADNIL, r, 1, 0); e->k = E_REG; e->reg = r; break; }
  case E_TRUE: { int r = newreg(fs); emit(fs, OP_LOADBOOL, r, 1, 0); e->k = E_REG; e->reg = r; break; }
  case E_FALSE: { int r = newreg(fs); emit(fs, OP_LOADBOOL, r, 0, 0); e->k = E_REG; e->reg = r; break; }
  case E_UPVAL: { int r = newreg(fs); emit(fs, OP_GETUPVAL, r, e->reg, 0); e->k = E_REG; e->reg = r; break; }
  case E_GLOBAL: { int r = newreg(fs); int ki = addkstr(fs, e->keystr);
    emit(fs, OP_GETTABUP, r, 0, ki); e->k = E_REG; e->reg = r; break; }
  case E_INDEX: {
    if (e->keyreg >= 0) { int r = newreg(fs); emit(fs, OP_GETTABLE, r, e->objreg, e->keyreg);
      e->k = E_REG; e->reg = r; }
    else { int r = newreg(fs); int ki = addkstr(fs, e->keystr);
      emit(fs, OP_GETTAB, r, e->objreg, ki); e->k = E_REG; e->reg = r; }
    fs->freereg = e->reg + 1;
    break; }
  case E_CALL: { if (e->nres != 1) { fs->proto->code[e->callpc].c = 1; e->nres = 1; }
    e->k = E_REG; fs->freereg = e->reg + 1; break; }
  case E_VARARG: { fs->proto->code[e->callpc].b = 2; e->nres = 1; e->k = E_REG;
    fs->freereg = e->reg + 1; break; }
  case E_REG: case E_LOCAL: fs->freereg = e->reg + 1; break;
  } }

static int to_reg(FuncState *fs, ExpDesc *e) { discharge(fs, e); return e->reg; }

static int to_topreg(FuncState *fs, ExpDesc *e)
{ int r = to_reg(fs, e);
  if (r != fs->freereg - 1) { int nr = newreg(fs); emit(fs, OP_MOVE, nr, r); r = nr; }
  return r; }

static void set_one_result(FuncState *fs, ExpDesc *e)
{ if (e->k == E_CALL) { if (e->nres != 1) { fs->proto->code[e->callpc].c = 1; e->nres = 1; e->k = E_REG; } }
  else if (e->k == E_VARARG) { fs->proto->code[e->callpc].b = 2; e->nres = 1; e->k = E_REG; } }

static void singlevar(FuncState *fs, Str *name, ExpDesc *e)
{ int i = searchlocal(fs, name);
  if (i >= 0) { e->k = E_LOCAL; e->reg = fs->actvar[i].reg; e->nres = 1; return; }
  i = searchupval(fs, name);
  if (i >= 0) { e->k = E_UPVAL; e->reg = i; e->nres = 1; return; }
  if (fs->prev) {
    int j = searchlocal(fs->prev, name);
    if (j >= 0) { addupval(fs, name, 1, j); markparentupval(fs, j);
      e->k = E_UPVAL; e->reg = fs->nuv - 1; e->nres = 1; return; } }
  e->k = E_GLOBAL; e->keystr = name; e->keyreg = -1; e->objreg = 0; e->nres = 1; }

static void setcallname(FuncState *fs, int pc, ExpDesc *e)
{ Proto *p = fs->proto;
  uint8_t kind = FRK_NONE; Str *nm = NULL;
  switch (e->k) {
  case E_LOCAL: { int i; kind = FRK_LOCAL;
    for (i = 0; i < fs->nactvar; i++) if (fs->actvar[i].reg == e->reg) { nm = fs->actvar[i].name; break; }
    break; }
  case E_INDEX: kind = FRK_FIELD; nm = e->keystr; break;
  case E_GLOBAL: kind = FRK_GLOBAL; nm = e->keystr; break;
  case E_UPVAL: kind = FRK_UPVAL; nm = fs->upvals[e->reg].name; break;
  default: kind = FRK_NONE; break;
  }
  if (!p->callnamekind) {
    p->callnamekind = (uint8_t*)luaP_malloc(fs->codecap);
    p->callnamestr = (Str**)luaP_malloc(sizeof(Str*) * fs->codecap);
    memset(p->callnamestr, 0, sizeof(Str*) * fs->codecap);
  }
  p->callnamekind[pc] = kind;
  p->callnamestr[pc] = nm; }

void check_match(LexState *ls, int what, int who, int who_line)
{ if (ls->t.token != what) {
    if (who_line == ls->linenumber)
      luaX_error(ls, "'%s' expected near '%s'", luaX_tokenname(what), luaX_tokenname(ls->t.token));
    else
      luaX_error(ls, "'%s' expected (to close '%s' at line %d) near '%s'",
		 luaX_tokenname(what), luaX_tokenname(who), who_line, luaX_tokenname(ls->t.token));
  }
  luaX_next(ls); }

/* ------------------------------------------------------ table constructor */
static void tablector(FuncState *fs, ExpDesc *e)
{ LexState *ls = fs->ls;
  int narr = 0, nhash = 0;
  int treg;
  int ismulti = 0;
  luaX_next(ls);
  treg = newreg(fs);
  fs->newtablepc = fs->proto->ncode;
  emit(fs, OP_NEWTABLE, treg, 0, 0);
  e->k = E_REG; e->reg = treg; e->nres = 1;
  if (ls->t.token == '}') { luaX_next(ls); fs->freereg = treg + 1; return; }
  for (;;) {
    ExpDesc key, val;
    int iskey = 0;
    memset(&key, 0, sizeof(key)); memset(&val, 0, sizeof(val));
    key.k = E_VOID; val.k = E_VOID;
    if (ls->t.token == '[') {
      int l2 = ls->linenumber;
      luaX_next(ls);
      subexpr(fs, &key, 0);
      check_match(ls, ']', '[', l2);
      if (ls->t.token != '=') luaX_error(ls, "'=' expected near '%s'", luaX_tokenname(ls->t.token));
      luaX_next(ls);
      iskey = 1;
      subexpr(fs, &val, 0);
      if (val.k == E_CALL || val.k == E_VARARG) set_one_result(fs, &val);
