	luaX_next(ls);
	iskey = 1;
	{ int r = newreg(fs); emit(fs, OP_LOADK, r, addkstr(fs, kname), 0);
	  key.k = E_REG; key.reg = r; }
	subexpr(fs, &val, 0);
	if (val.k == E_CALL || val.k == E_VARARG) set_one_result(fs, &val);
	else discharge(fs, &val);
      } else {
	{ int r = newreg(fs); emit(fs, OP_LOADK, r, addkstr(fs, kname), 0);
	  key.k = E_REG; key.reg = r; }
	{ ExpDesc v2; singlevar(fs, kname, &v2); discharge(fs, &v2); val = v2; }
	iskey = 0;
      }
