      int vr = to_reg(fs, &val);
      int kr = to_reg(fs, &key);
      emit(fs, OP_SETTABLE, vr, treg, kr);
      nhash++;
      fs->freereg = treg + 1;
    } else if (ismulti) {
      emit(fs, OP_SETLIST, treg, 0, narr + 1);
      fs->freereg = treg + 1;
    } else {
      int vr = to_reg(fs, &val);
      if (vr != treg + 1) { int nr = newreg(fs); emit(fs, OP_MOVE, nr, vr); vr = nr; }
      emit(fs, OP_SETLIST, treg, 1, narr + 1);
      narr++;
      fs->freereg = treg + 1;
    }
