/* ------------------------------------------------------------ func args -- */
static void funcargs(FuncState *fs, ExpDesc *e, int line, int selfmethod)
{ LexState *ls = fs->ls;
  int freg = e->reg;
  int nparams = selfmethod ? 1 : 0;
  int multret = 0;
  switch (ls->t.token) {
  case '(': {
    int l2 = ls->linenumber;
    luaX_next(ls);
    fs->freereg = freg + 1 + nparams;
    if (ls->t.token != ')') {
      for (;;) {
	ExpDesc arg;
	int islast;
	memset(&arg, 0, sizeof(arg)); arg.k = E_VOID;
	subexpr(fs, &arg, 0);
	islast = (ls->t.token != ',');
	if (!islast) luaX_next(ls);
