    break; }
  case '{': {
    ExpDesc arg;
    int r;
    memset(&arg, 0, sizeof(arg)); arg.k = E_VOID;
    fs->freereg = freg + 1 + nparams;
    r = newreg(fs);
    arg.k = E_REG; arg.reg = r; arg.nres = 1;
