/* --------------------------------------------------------- primary exp --- */
static void primaryexp(FuncState *fs, ExpDesc *e)
{ LexState *ls = fs->ls;
  int line = ls->linenumber;
  switch (ls->t.token) {
  case '(': {
    luaX_next(ls);
    subexpr(fs, e, 0);
    check_match(ls, ')', '(', line);
    if (e->k == E_CALL || e->k == E_VARARG) set_one_result(fs, e);
    else discharge(fs, e);
