      if (e->k != E_REG) discharge(fs, e);
      { int objreg = to_topreg(fs, e);
	int ki = addkstr(fs, key);
	ExpDesc tmp;
	fs->freereg = objreg + 2;
	emit(fs, OP_MOVE, objreg + 1, objreg);
	emit(fs, OP_GETTAB, objreg, objreg + 1, ki);
