/* ---------------------------------------------------------- simple exp --- */
static void simpleexp(FuncState *fs, ExpDesc *e)
{ LexState *ls = fs->ls;
  switch (ls->t.token) {
  case TK_NUMBER: {
    int r = newreg(fs);
    emit(fs, OP_LOADK, r, addk(fs, numV(ls->t.r)), 0);
    e->k = E_REG; e->reg = r; e->nres = 1;
    luaX_next(ls);
    break; }
  case TK_STRING: {
    int r = newreg(fs);
    emit(fs, OP_LOADK, r, addkstr(fs, ls->t.s), 0);
    e->k = E_REG; e->reg = r; e->nres = 1;
    luaX_next(ls);
    break; }
  case TK_NIL: e->k = E_NIL; e->nres = 1; e->reg = -1; luaX_next(ls); break;
  case TK_TRUE: e->k = E_TRUE; e->nres = 1; e->reg = -1; luaX_next(ls); break;
  case TK_FALSE: e->k = E_FALSE; e->nres = 1; e->reg = -1; luaX_next(ls); break;
  case TK_DOTS: {
    int r = newreg(fs);
