/* --------------------------------------------------------- proto helpers - */
static void ins_reserve(FuncState *fs, int n)
{ Proto *p = fs->proto;
  if (p->ncode + n > fs->codecap) {
    int nc = fs->codecap ? fs->codecap * 2 : 64;
    Ins *ni; int32_t *nl; int i;
    while (nc < p->ncode + n) nc *= 2;
    ni = (Ins*)luaP_malloc(sizeof(Ins) * nc);
    nl = (int32_t*)luaP_malloc(sizeof(int32_t) * nc);
    if (p->code) { memcpy(ni, p->code, sizeof(Ins) * p->ncode); free(p->code); }
    if (p->lines) { memcpy(nl, p->lines, sizeof(int32_t) * p->ncode); free(p->lines); }
    for (i = 0; i < nc; i++) nl[i] = fs->ls->linenumber;
    if (p->callnamekind) {
      uint8_t *ck = (uint8_t*)luaP_malloc(nc);
      Str **cs = (Str**)luaP_malloc(sizeof(Str*) * nc);
      memcpy(ck, p->callnamekind, p->ncode);
      memcpy(cs, p->callnamestr, sizeof(Str*) * p->ncode);
      free(p->callnamekind); free(p->callnamestr);
      p->callnamekind = ck; p->callnamestr = cs;
    }
    p->code = ni; p->lines = nl;
    fs->codecap = nc;
  } }

static int emit(FuncState *fs, int op, int a, int b, int c)
{ Proto *p = fs->proto; Ins ins;
  ins_reserve(fs, 1);
  ins.op = (uint8_t)op; ins.a = a; ins.b = b; ins.c = c;
  p->code[p->ncode] = ins;
  p->lines[p->ncode] = fs->ls->linenumber;
  return p->ncode++; }

static int addk(FuncState *fs, Val k)
{ Proto *p = fs->proto; int i;
  for (i = 0; i < p->nk; i++) {
    if (p->k[i].t == k.t) {
      if (k.t == TAG_NUM) { if (p->k[i].u.n == k.u.n) return i; }
      else if (p->k[i].u.g == k.u.g) return i;
    } }
  if (p->nk >= fs->kcap) {
    int nc = fs->kcap ? fs->kcap * 2 : 16;
    Val *nk = (Val*)luaP_malloc(sizeof(Val) * nc);
    if (p->k) { memcpy(nk, p->k, sizeof(Val) * p->nk); free(p->k); }
    p->k = nk; fs->kcap = nc;
  }
  p->k[p->nk] = k;
  return p->nk++; }

static int addkstr(FuncState *fs, Str *s) { return addk(fs, strV(s)); }

/* ------------------------------------------------------------ registers -- */
static void set_maxreg(FuncState *fs, int r) { if (r + 1 > fs->maxreg) fs->maxreg = r + 1; }
static int newreg(FuncState *fs)
{ int r = fs->freereg++;
  set_maxreg(fs, r);
  if (fs->freereg > MAXREGS) luaX_error(fs->ls, "function or expression needs too many registers");
  return r; }

/* ------------------------------------------------------------ locals ----- */
static int newlocalvar(FuncState *fs, Str *name)
{ int n = fs->nactvar++;
  fs->actvar[n].name = name;
  fs->actvar[n].startpc = fs->proto->ncode;
  fs->actvar[n].reg = n;
  if (n + 1 > fs->maxreg) fs->maxreg = n + 1;
  return n; }

static int newlocalvar_at(FuncState *fs, Str *name, int reg)
{ int n = fs->nactvar++;
  fs->actvar[n].name = name;
  fs->actvar[n].startpc = fs->proto->ncode;
  fs->actvar[n].reg = reg;
  if (reg + 1 > fs->maxreg) fs->maxreg = reg + 1;
  return n; }

static int searchlocal(FuncState *fs, Str *name)
{ int i;
  for (i = fs->nactvar - 1; i >= 0; i--)
    if (fs->actvar[i].name == name) return i;
  return -1; }

static int searchupval(FuncState *fs, Str *name)
{ int i;
  for (i = 0; i < fs->nuv; i++)
    if (fs->upvals[i].name == name) return i;
  return -1; }

static void markparentupval(FuncState *fs, int localidx)
{ FuncState *prev = fs->prev;
  BlockCtx *b;
  if (!prev) return;
  for (b = prev->blocks; b; b = b->prev)
    if (b->nactvar0 <= localidx) b->hasupval = 1; }

