  default: primaryexp(fs, e); break;
  } }

/* ---------------------------------------------------------- subexpr ------ */
static void subexpr(FuncState *fs, ExpDesc *e, int limit)
{ LexState *ls = fs->ls;
  int unary[8], nunary = 0;
  while (nunary < 8 && (ls->t.token == TK_NOT || ls->t.token == '-' || ls->t.token == '#')) {
    unary[nunary++] = ls->t.token;
    luaX_next(ls);
  }
  simpleexp(fs, e);
  { int i;
    for (i = nunary - 1; i >= 0; i--) {
      if (e->k == E_CALL || e->k == E_VARARG) set_one_result(fs, e);
      discharge(fs, e);
      { int r = to_reg(fs, e), rr;
	switch (unary[i]) {
	case '-': rr = newreg(fs); emit(fs, OP_UNM, rr, r, 0); break;
	case '#': rr = newreg(fs); emit(fs, OP_LEN, rr, r, 0); break;
	default: rr = newreg(fs); emit(fs, OP_NOT, rr, r, 0); break;
	}
	e->k = E_REG; e->reg = rr;
	fs->freereg = rr + 1; } } }
  for (;;) {
    int tok = ls->t.token;
    int op = 0, lft = 0, rgt = 0;
    switch (tok) {
    case TK_OR: op = 1; lft = 1; rgt = 1; break;
    case TK_AND: op = 2; lft = 2; rgt = 2; break;
    case '<': case '>': case TK_LE: case TK_GE: case TK_NE: case TK_EQ:
      op = 3; lft = 3; rgt = 3; break;
    case TK_CONCAT: op = 4; lft = 5; rgt = 4; break;
    case '+': case '-': op = 5; lft = 6; rgt = 6; break;
    case '*': case '/': case '%': op = 6; lft = 7; rgt = 7; break;
    case '^': op = 7; lft = 10; rgt = 9; break;
    default: op = 0; break;
    }
    if (!op || lft <= limit) return;
    luaX_next(ls);
    if (op == 1 || op == 2) {
      int areg, jpc, bstart;
      if (e->k == E_CALL || e->k == E_VARARG) set_one_result(fs, e);
      areg = to_topreg(fs, e);
      jpc = emit(fs, op == 1 ? OP_JTRUE : OP_JFALSE, areg, 0, 0);
      bstart = fs->proto->ncode;
      { ExpDesc e2;
	memset(&e2, 0, sizeof(e2)); e2.k = E_VOID;
	subexpr(fs, &e2, rgt);
	if (e2.k == E_CALL || e2.k == E_VARARG) set_one_result(fs, &e2);
	else discharge(fs, &e2);
	{ int breg = to_reg(fs, &e2);
	  if (breg != areg) emit(fs, OP_MOVE, areg, breg); } }
      fs->proto->code[jpc].c = fs->proto->ncode - (jpc + 1);
      e->k = E_REG; e->reg = areg; e->nres = 1;
      fs->freereg = areg + 1;
      continue;
    }
    { ExpDesc e2;
      memset(&e2, 0, sizeof(e2)); e2.k = E_VOID;
      subexpr(fs, &e2, rgt);
      if (e2.k == E_CALL || e2.k == E_VARARG) set_one_result(fs, &e2);
      else discharge(fs, &e2);
      if (e->k == E_CALL || e->k == E_VARARG) set_one_result(fs, e);
      else discharge(fs, e);
      { int ra = to_reg(fs, e), rb = to_reg(fs, &e2), r;
	switch (op) {
	case 3: {
	  r = newreg(fs);
	  switch (tok) {
	  case '<': emit(fs, OP_LT, r, ra, rb); break;
	  case '>': emit(fs, OP_LT, r, rb, ra); break;
	  case TK_LE: emit(fs, OP_LE, r, ra, rb); break;
	  case TK_GE: emit(fs, OP_LE, r, rb, ra); break;
	  case TK_EQ: emit(fs, OP_EQ, r, ra, rb); break;
	  case TK_NE: emit(fs, OP_EQ, r, ra, rb);
	    { int r2 = newreg(fs); emit(fs, OP_NOT, r2, r, 0); r = r2; }
	    break;
	  }
	  e->k = E_REG; e->reg = r;
	  fs->freereg = r + 1;
	  break; }
	case 4: {
	  r = newreg(fs);
	  emit(fs, OP_CONCAT, r, ra, rb);
	  e->k = E_REG; e->reg = r;
	  fs->freereg = r + 1;
	  break; }
	default: {
	  int oop = 0;
	  switch (tok) {
	  case '+': oop = 0; break; case '-': oop = 1; break; case '*': oop = 2; break;
	  case '/': oop = 3; break; case '%': oop = 4; break; case '^': oop = 5; break;
	  }
	  r = newreg(fs);
	  emit(fs, OP_ADD + oop, r, ra, rb);
	  e->k = E_REG; e->reg = r;
	  fs->freereg = r + 1;
	  break; }
	} } } } }
