static void store_var(FuncState *fs, ExpDesc *v, ExpDesc *e)
{ switch (v->k) {
  case E_LOCAL: { int r = to_reg(fs, e);
    if (r != v->reg) emit(fs, OP_MOVE, v->reg, r);
    break; }
  case E_GLOBAL: { int r = to_reg(fs, e);
    int ki = addkstr(fs, v->keystr);
    emit(fs, OP_SETTABUP, 0, ki, r);
    break; }
  case E_UPVAL: { int r = to_reg(fs, e);
    emit(fs, OP_SETUPVAL, r, v->reg, 0);
    break; }
  case E_INDEX: { int r = to_reg(fs, e);
    if (v->keyreg >= 0) emit(fs, OP_SETTABLE, r, v->objreg, v->keyreg);
    else { int ki = addkstr(fs, v->keystr); emit(fs, OP_SETTAB, r, v->objreg, ki); }
    break; }
  default: break;
  } }

static void explist_assign(FuncState *fs, int nvars, ExpDesc *targets)
{ LexState *ls = fs->ls;
  int i = 0;
  if (ls->t.token != '=') {
    /* expression statement (a function call) */
    if (nvars != 1 || (targets[0].k != E_CALL)) {
      luaX_error(ls, "syntax error near '%s'", luaX_tokenname(ls->t.token));
    }
    return;
  }
  luaX_next(ls);
  for (;;) {
    ExpDesc e;
    int islast;
    memset(&e, 0, sizeof(e)); e.k = E_VOID;
    if (i < nvars) {
      /* compile into the target's register position */
      int basereg;
      if (targets[i].k == E_LOCAL) basereg = targets[i].reg;
      else if (targets[i].k == E_GLOBAL || targets[i].k == E_INDEX || targets[i].k == E_UPVAL) {
	/* reserve a register for the value */
	basereg = reserve_reg(fs);
      } else basereg = newreg(fs);
      fs->freereg = basereg;
      subexpr(fs, &e, 0);
      islast = (ls->t.token != ',');
      if (!islast) luaX_next(ls);
      if (islast && (e.k == E_CALL || e.k == E_VARARG)) {
	/* multret: patch the result count to the remaining targets */
	int want = nvars - i;
	if (want > 0) {
	  if (e.k == E_CALL) fs->proto->code[e.callpc].c = want;
	  else fs->proto->code[e.callpc].b = want + 1;
	}
	/* the results are in registers base..base+want-1 */
	for (; i < nvars; i++) {
	  if (targets[i].k != E_LOCAL) { /* copy to a temp then store */
	    ExpDesc tmp; memset(&tmp, 0, sizeof(tmp));
	    tmp.k = E_REG; tmp.reg = basereg + (i - (i - i));
	    store_var(fs, &targets[i], &tmp);
	  }
	}
	break;
      } else {
	if (e.k == E_CALL || e.k == E_VARARG) set_one_result(fs, &e);
	else discharge(fs, e);
	store_var(fs, &targets[i], &e);
	if (targets[i].k != E_LOCAL) unreserve(fs, 1);
	i++;
      }
      if (islast) break;
    } else break;
  }
  /* extra targets get nil */
  for (; i < nvars; i++) {
    ExpDesc e; memset(&e, 0, sizeof(e)); e.k = E_NIL;
    store_var(fs, &targets[i], &e);
  }
  /* for multret results: handle the remaining targets */
