/* --------------------------------------------------- blocks & control ---- */
static int blockdepth(FuncState *fs) { return fs->nblocks; }

static void enterblock(FuncState *fs, BlockCtx *b, int isloop)
{ b->prev = fs->blocks;
  b->nactvar0 = fs->nactvar;
  b->freereg0 = fs->freereg;
  b->hasupval = 0;
  b->isloop = isloop;
  b->nbreaks = 0;
  b->firstlabel = fs->nlabels;
  b->firstgoto = fs->ngotos;
  fs->blocks = b;
  fs->nblocks++; }

static void addbreak(FuncState *fs, int pc)
{ BlockCtx *b;
  for (b = fs->blocks; b; b = b->prev) if (b->isloop) break;
  if (!b) luaX_error(fs->ls, "break outside a loop");
  if (b->nbreaks >= b->capbreaks) {
    int nc = b->capbreaks ? b->capbreaks * 2 : 4;
    int *nb = (int*)luaP_malloc(sizeof(int) * nc);
    if (b->breaks) { memcpy(nb, b->breaks, sizeof(int) * b->nbreaks); free(b->breaks); }
    b->breaks = nb; b->capbreaks = nc;
  }
  b->breaks[b->nbreaks++] = pc; }

static void patchbreaks(FuncState *fs, BlockCtx *b, int target)
{ int i;
  for (i = 0; i < b->nbreaks; i++) {
    int pc = b->breaks[i];
    fs->proto->code[pc].c = target - (pc + 1);
  }
  b->nbreaks = 0; }

static void leaveblock(FuncState *fs)
{ BlockCtx *b = fs->blocks;
  int i;
  /* resolve pending gotos that belong to this block and are not resolvable */
  if (b->hasupval) emit(fs, OP_CLOSE, b->nactvar0, 0, 0);
  for (i = fs->ngotos - 1; i >= b->firstgoto; i--) {
    /* gotos recorded in this block: keep them (they may be resolved outside) */
  }
  fs->nlabels = b->firstlabel;
  fs->nactvar = b->nactvar0;
  fs->freereg = b->freereg0;
  if (fs->freereg < fs->nactvar) fs->freereg = fs->nactvar;
  fs->blocks = b->prev;
  fs->nblocks--; }

/* ------------------------------------------------------------- labels ---- */
static void gotostat(FuncState *fs, Str *name)
{ int i;
  int depth = fs->nblocks;
  for (i = fs->nlabels - 1; i >= 0; i--) {
    if (fs->labels[i].name == name && fs->labels[i].blockdepth <= depth) {
      int pc = emit(fs, OP_JMP, 0, 0, 0);
      fs->proto->code[pc].c = fs->labels[i].pc - (pc + 1);
      return;
    }
    if (fs->labels[i].blockdepth < depth) break;
  }
  { int pc = emit(fs, OP_JMP, 0, 0, 0);
    if (fs->ngotos >= 256) luaX_error(fs->ls, "too many goto statements");
    fs->gotos[fs->ngotos].name = name;
    fs->gotos[fs->ngotos].pc = pc;
    fs->gotos[fs->ngotos].line = fs->ls->linenumber;
    fs->gotos[fs->ngotos].blockdepth = depth;
    fs->ngotos++; } }

static void labelstat(FuncState *fs, Str *name)
{ int i;
  int depth = fs->nblocks;
  int pc = fs->proto->ncode;
  for (i = fs->nlabels - 1; i >= 0; i--) {
    if (fs->labels[i].blockdepth < depth) break;
    if (fs->labels[i].name == name) {
      /* duplicate label in the same block */
      { /* allowed in Lua? report error */
	int line = fs->ls->linenumber;
	(void)line;
	luaX_error(fs->ls, "label '%s' already defined", name->data); }
    }
  }
  if (fs->nlabels >= 256) luaX_error(fs->ls, "too many labels");
  fs->labels[fs->nlabels].name = name;
  fs->labels[fs->nlabels].pc = pc;
  fs->labels[fs->nlabels].blockdepth = depth;
  fs->nlabels++;
  for (i = 0; i < fs->ngotos; i++) {
    if (fs->gotos[i].name == name && fs->gotos[i].blockdepth >= depth) {
      fs->proto->code[fs->gotos[i].pc].c = pc - (fs->gotos[i].pc + 1);
      /* remove by marking as resolved */
      fs->gotos[i].name = NULL;
    } }
  { int w = 0;
    for (i = 0; i < fs->ngotos; i++) if (fs->gotos[i].name) fs->gotos[w++] = fs->gotos[i];
    fs->ngotos = w; } }

