{ switch (fs->ls->t.token) {
  case TK_EOS: case TK_END: case TK_ELSE: case TK_ELSEIF:
  case TK_UNTIL: case TK_RETURN: case TK_BREAK:
    return 1;
  }
  return 0; }

static void exprstat(FuncState *fs)
{ LexState *ls = fs->ls;
  ExpDesc v;
  int nvars = 0;
  ExpDesc targets[64];
  int line = ls->linenumber;
  memset(&v, 0, sizeof(v)); v.k = E_VOID;
  primaryexp(fs, &v);
  if (v.k == E_VOID) return;
  if (ls->t.token == '=' || ls->t.token == ',') {
    targets[nvars++] = v;
    while (ls->t.token == ',') {
      ExpDesc nv;
      luaX_next(ls);
      memset(&nv, 0, sizeof(nv)); nv.k = E_VOID;
