  np->linedefined = ls->linenumber;
  np->source = fs->proto->source;
  memset(&nfs, 0, sizeof(nfs));
  nfs.ls = ls;
  nfs.prev = fs;
  nfs.proto = np;
  nfs.maxreg = 0;
  if (ismethod) {
    Str *self = luaP_newstr(ls->L, "self", 4);
    newlocalvar(&nfs, self);
    nparams++;
  }
  check_match(ls, '(', TK_FUNCTION, line);
  if (ls->t.token != ')') {
    for (;;) {
      if (ls->t.token == TK_NAME) {
	newlocalvar(&nfs, ls->t.s);
	nparams++;
	luaX_next(ls);
	if (ls->t.token == ',') { luaX_next(ls); continue; }
	if (ls->t.token == ')') break;
	if (ls->t.token == TK_DOTS) { np->isvararg = 1; luaX_next(ls);
	  check_match(ls, ')', '(', line); break; }
	luaX_error(ls, "',' expected near '%s'", luaX_tokenname(ls->t.token));
      } else if (ls->t.token == TK_DOTS) {
	np->isvararg = 1;
	luaX_next(ls);
	check_match(ls, ')', '(', line);
	break;
      } else luaX_error(ls, "'<name>' expected near '%s'", luaX_tokenname(ls->t.token));
    }
  } else luaX_next(ls);
  np->numparams = (uint8_t)(nparams + (ismethod ? 0 : 0));
  enterblock(&nfs, &b, 0);
  block(&nfs);
  check_match(ls, TK_END, TK_FUNCTION, line);
  leaveblock(&nfs);
  checkgotos(&nfs);
  np->lastlinedefined = ls->linenumber;
  np->maxstack = (uint8_t)(nfs.maxreg + 2 > 250 ? 250 : nfs.maxreg + 2);
  if (np->maxstack < np->numparams + 2) np->maxstack = (uint8_t)(np->numparams + 2);
  /* register the child proto */
  { int idx;
    if (fs->proto->nchildren >= fs->childcap) {
      int nc = fs->childcap ? fs->childcap * 2 : 4;
      Proto **ncp = (Proto**)luaP_malloc(sizeof(Proto*) * nc);
      if (fs->proto->children) { memcpy(ncp, fs->proto->children, sizeof(Proto*) * fs->proto->nchildren); free(fs->proto->children); }
      fs->proto->children = ncp;
      fs->childcap = nc;
    }
    idx = fs->proto->nchildren++;
    fs->proto->children[idx] = np;
    { int r = newreg(fs);
      emit(fs, OP_CLOSURE, r, idx, 0);
      e->k = E_REG; e->reg = r; e->nres = 1; } }
  /* store the upvalue info into the child proto */
  { int i;
    np->nuv = (uint16_t)nfs.nuv;
    np->uvinfo = (int32_t*)luaP_malloc(sizeof(int32_t) * 2 * (nfs.nuv ? nfs.nuv : 1));
    np->uvnames = (Str**)luaP_malloc(sizeof(Str*) * (nfs.nuv ? nfs.nuv : 1));
    for (i = 0; i < nfs.nuv; i++) {
      np->uvinfo[2*i] = nfs.upvals[i].inparent;
      np->uvinfo[2*i+1] = nfs.upvals[i].idx;
      np->uvnames[i] = nfs.upvals[i].name;
    } }
  /* collect the local variable debug info */
  { /* gather all locals that appeared during compilation: we track them via
       a simple list of (name, reg, startpc, endpc) accumulated per scope */
  }
  (void)oldline;
}

/* local variable debug info: track declarations */
typedef struct LocInfo { Str *name; int reg; int startpc; int endpc; } LocInfo;

/* ---------------------------------------------------------------- entry -- */
Proto *luaY_parse(LexState *ls)
{ FuncState fs;
  Proto *p = (Proto*)luaP_malloc(sizeof(Proto));
  BlockCtx b;
  memset(p, 0, sizeof(Proto));
  p->tt = TAG_PROTO;
  p->ismain = 1;
  p->source = ls->chunkname;
  memset(&fs, 0, sizeof(fs));
  fs.ls = ls;
  fs.proto = p;
  if (setjmp(ls->errjmp)) return NULL;
  luaX_init(ls, NULL, NULL, 0, ls->chunkname);
  /* re-init the lexer with the real source */
  luaX_next(ls);
  enterblock(&fs, &b, 0);
  while (ls->t.token != TK_EOS) {
    statement(&fs);
    if (ls->t.token == TK_EOS) break;
  }
  leaveblock(&fs);
  checkgotos(&fs);
  emit(&fs, OP_RETURN, -1, 1, 0);
  p->maxstack = (uint8_t)(fs.maxreg + 2 > 250 ? 250 : fs.maxreg + 2);
  p->numparams = 0;
  p->isvararg = 1;
  p->nuv = 0;
  p->lastlinedefined = ls->linenumber;
  return p; }
