void lib_base_tonumber(Thread *L)
{ Val v = luaP_get(L, 1);
  Val base = luaP_optval(L, 2);
  luaP_settop(L, 0);
  if (base.t != TAG_NIL && base.t != TAG_FALSE && base.t != TAG_TRUE) {
    /* tonumber(s, base) */
    Str *s = luaP_checkstr2(L, v);
    double b = luaP_optnum(L, 2, 10);
    const char *p = s->data;
    size_t len = s->len;
    double res = 0;
    int neg = 0, got = 0;
    while (len && (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r' || *p == '\v' || *p == '\f')) { p++; len--; }
    if (len && (*p == '+' || *p == '-')) { neg = (*p == '-'); p++; len--; }
    while (len) {
      int c = (unsigned char)*p;
      int d;
      if (c >= '0' && c <= '9') d = c - '0';
      else if (c >= 'a' && c <= 'z') d = c - 'a' + 10;
      else if (c >= 'A' && c <= 'Z') d = c - 'A' + 10;
      else break;
      if (d >= b) break;
      res = res * b + d;
      p++; len--; got = 1;
    }
    if (!got) { luaP_pushnil(L); return; }
    luaP_pushnum(L, neg ? -res : res);
    return;
  }
  if (v.t == TAG_NUM) { luaP_pushnum(L, v.u.n); return; }
  if (v.t == TAG_STR) {
    double d;
    if (str2num(strV2(v)->data, strV2(v)->len, &d)) { luaP_pushnum(L, d); return; }
  }
  luaP_pushnil(L);
