  if (v.t == TAG_STR && strV2(v)->len == 1 && strV2(v)->data[0] == '#') {
    luaP_pushnum(L, (double)(n - 1));
    return;
  }
  { int i = luaP_checkint(L, 1);
    if (i < 0) i = n + i;
    else if (i > n) i = n + 1;
    if (i < 1) i = 1;
    luaP_settop(L, 0);
    { int j;
      for (j = i; j <= n; j++) luaP_pushval(L, luaP_get(L, j + 1)); } }
