  Val res = nilV();
  luaP_settop(L, 0);
  if (mt) {
    Val protect = table_getstr(mt, luaP_newstr(L, "__metatable", 11));
    res = istrue(protect) ? protect : tabV(mt);
  }
  luaP_pushval(L, res); }

void lib_base_setmetatable(Thread *L)
{ Val t = luaP_get(L, 1), mt = luaP_optval(L, 2);
  luaP_settop(L, 0);
  if (t.t == TAG_TAB) { Table *tb = tabV2(t);
    if (mt.t == TAG_TAB) { Table *m = tabV2(mt);
      Val protect = table_getstr(m, luaP_newstr(L, "__metatable", 11));
      if (istrue(protect)) {
	luaP_errormsg(L, "cannot change a protected metatable");
      }
    }
    tb->mt = mt;
    luaP_pushval(L, t);
    return; }
  if (t.t == TAG_UDATA) { udV2(t)->mt = mt; luaP_pushval(L, t); return; }
  if (t.t == TAG_CDATA) { cdV2(t)->mt = mt; luaP_pushval(L, t); return; }
  luaP_typeerror(L, 1, "nil or table"); }

void lib_base_getfenv(Thread *L)
{ Val f = luaP_get(L, 1);
  luaP_settop(L, 0);
  if (f.t == TAG_FUN) { Func *fn = funV2(f);
    if (fn->isC) { luaP_pushval(L, fn->env); return; }
    luaP_pushval(L, fn->env);
    return; }
  /* level 1: the current function's env */
  if (L->nframes) { Frame *fr = topframe_(L);
    if (fr->func.t == TAG_FUN) { luaP_pushval(L, funV2(fr->func)->env); return; } }
  luaP_pushnil(L); }

void lib_base_setfenv(Thread *L)
{ Val f = luaP_get(L, 1), t = luaP_get(L, 2);
  luaP_settop(L, 0);
  if (t.t != TAG_TAB) luaP_errormsg(L, "bad argument #2 to 'setfenv' (table expected, got %s)", luaP_typename(t));
  if (f.t != TAG_FUN) {
    luaP_errormsg(L, "bad argument #1 to 'setfenv' (function expected, got %s)", luaP_typename(f));
  }
  funV2(f)->env = t;
  luaP_pushval(L, t); }

void lib_base_gcinfo(Thread *L)
{ extern size_t lj_heapsize(void);
  luaP_settop(L, 0);
  luaP_pushnum(L, (double)lj_heapsize() / 1024.0); }

void lib_base_collectgarbage(Thread *L)
{ Val opt = luaP_optval(L, 1);
  luaP_settop(L, 0);
  if (opt.t == TAG_NIL || opt.t == TAG_FALSE) { lj_gc_collect(L); luaP_pushnum(L, 0); return; }
  if (opt.t == TAG_STR) {
    Str *s = strV2(opt);
    if (strcmp(s->data, "collect") == 0) { lj_gc_collect(L); luaP_pushnum(L, 0); return; }
    if (strcmp(s->data, "count") == 0) {
      extern size_t lj_heapsize(void);
      luaP_pushnum(L, (double)lj_heapsize() / 1024.0);
      return; }
    if (strcmp(s->data, "step") == 0) { lj_gc_collect(L); luaP_pushtrue(L); return; }
    if (strcmp(s->data, "stop") == 0) { lj_gc_on = 0; luaP_pushnum(L, 1); return; }
    if (strcmp(s->data, "restart") == 0) { lj_gc_on = 1; luaP_pushnum(L, 1); return; }
    if (strcmp(s->data, "setpause") == 0 || strcmp(s->data, "setstepmul") == 0) {
      luaP_pushnum(L, 200); return; }
    if (strcmp(s->data, "incremental") == 0 || strcmp(s->data, "generational") == 0) {
      luaP_pushnum(L, 0); return; }
    if (strcmp(s->data, "isrunning") == 0) { luaP_pushbool(L, lj_gc_on); return; }
  }
  luaP_errormsg(L, "invalid option '%s' to 'collectgarbage'", luaP_typename(opt)); }

void lib_base_newproxy(Thread *L)
{ Val v = luaP_get(L, 1);
  luaP_settop(L, 0);
  if (istrue(v) && v.t == TAG_TRUE) {
    /* newproxy(true): with a new metatable */
    UData *u = luaP_newudata(L, UD_OTHER, NULL);
    Table *mt = luaP_newtable(L);
    u->mt = tabV(mt);
    luaP_pushval(L, udV(u));
    return; }
  { UData *u = luaP_newudata(L, UD_OTHER, NULL);
    luaP_pushval(L, udV(u)); } }

void lib_base_loadstring(Thread *L);
void lib_base_load(Thread *L);
void lib_base_loadfile(Thread *L);
void lib_base_dofile(Thread *L);
CEOF
echo ok; wc -l llib.c"}

