  if (opt.t == TAG_STR) {
    Str *s = strV2(opt);
    if (strcmp(s->data, "collect") == 0) { lj_gc_collect(L); luaP_pushnum(L, 0); return; }
    if (strcmp(s->data, "count") == 0) {
      extern size_t lj_heapsize(void);
