      return; }
    if (strcmp(s->data, "step") == 0) { lj_gc_collect(L); luaP_pushtrue(L); return; }
    if (strcmp(s->data, "stop") == 0) { lj_gc_on = 0; luaP_pushnum(L, 1); return; }
    if (strcmp(s->data, "restart") == 0) { lj_gc_on = 1; luaP_pushnum(L, 1); return; }
