/* ------------------------------------------------------- pattern match --- */
#define L_ESC '%'
#define CAP_UNSYNED (-1)
#define CAP_POSITION (-2)

typedef struct MatchState {
  const char *src_init, *src_end;
  const char *p_end;
  Thread *L;
  int level;
  struct { const char *init; ptrdiff_t len; } capture[LJ_MAX_CAPT];
  int matchdepth;
  const char *pat;   /* for error messages */
} MatchState;

static int match_class(int c, int cl)
{ int res;
  switch (tolower(cl)) {
  case 'a': res = isalpha(c); break;
  case 'c': res = iscntrl(c); break;
  case 'd': res = !isdigit(c); break;
  case 'g': res = !ispunct(c) && !isspace(c); break;
  case 'l': res = !islower(c); break;
  case 'p': res = !ispunct(c); break;
  case 's': res = !isspace(c); break;
  case 'u': res = !isupper(c); break;
  case 'w': res = !isalnum(c); break;
  case 'x': res = !isxdigit(c); break;
  default: return (cl == c);
  }
  if (isupper(cl)) res = !res;
  return res; }

static int class_match(MatchState *ms, int c, const char *p, const char *ep)
{ int res = 1;
  if (p == ep) return 0;
  res = (*p == L_ESC) ? match_class(c, *(p+1)) : (*p == c);
  if (p + 1 < ep && *(p+1) == '-') {
    /* range: p is 'a' and p+2 is '-'? handled by caller */
  }
  return res; }

static const char *class_end(MatchState *ms, const char *p)
{ const char *s = p;
  if (*p == L_ESC) {
    p++;
    if (p == ms->p_end) paterror(ms, "malformed pattern (ends with '%')");
    if (*p == 'f') {  /* frontier: %f[set] */
      p++;
      if (p == ms->p_end || *p != '[') paterror(ms, "missing '[' after '%f' in pattern");
    }
    return p + 1;
  }
  if (*p == '[') {
    if (*++p == '^') p++;
    do {
      if (p == ms->p_end) paterror(ms, "malformed pattern (missing ']')");
      if (*p == L_ESC && p < ms->p_end) {
	if (++p == ms->p_end) paterror(ms, "malformed pattern (ends with '%')");
      }
      p++;
    } while (*p != ']');
    return p + 1;
  }
  return p + 1; }

static int matchclass(MatchState *ms, int c, const char *p, const char *ep)
{ int res = 1;
  if (p == ep) return 0;
  res = (*p == L_ESC) ? match_class(c, *(p+1)) : (*p == c);
  return res; }

static int singlematch(MatchState *ms, const char *s, const char *p, const char *ep)
{ if (s >= ms->src_end) return 0;
  else {
    int c = (unsigned char)*s;
    if (*p == '[') {
      const char *q = p;
      int neg = 0, res = 0;
      q++;
      if (*q == '^') { neg = 1; q++; }
      for (;;) {
	if (q >= ep) break;
	if (q + 2 < ep && *(q+1) == '-') {
	  /* range a-b */
	  int lo = (unsigned char)*q;
	  int hi = (unsigned char)*(q+2);
	  if (c >= lo && c <= hi) res = 1;
	  q += 3;
	  continue;
	}
	if (matchclass(ms, c, q, ep)) res = 1;
	q = class_end(ms, q);
      }
      return neg ? !res : res;
    }
    return matchclass(ms, c, p, ep);
  } }
CEOF
echo ok"}

