/* ------------------------------------------------------- pattern match --- */
#define L_ESC '%'
#define CAP_UNSYNED (-1)
#define CAP_POSITION (-2)
#define MATCH_MAXDEPTH 200

typedef struct MatchState {
  const char *src_init, *src_end;
  const char *p_end;
  Thread *L;
  int level;
  struct { const char *init; ptrdiff_t len; } capture[LJ_MAX_CAPT];
  int matchdepth;
} MatchState;

static void paterror(MatchState *ms, const char *msg)
{ luaP_errormsg2(ms->L, 1, "%s", msg); }

static int check_capture(MatchState *ms, int l)
{ l -= '1';
  if (l < 0 || l >= ms->level || ms->capture[l].len == CAP_UNSYNED)
    paterror(ms, "invalid capture index");
  return l; }

static int push_captures(MatchState *ms, const char *s, const char *e, int whole)
{ int nlevels = (ms->level == 0 && s) ? 1 : ms->level;
  int i;
  if (nlevels >= LJ_MAX_CAPT) nlevels = LJ_MAX_CAPT;
  for (i = 0; i < nlevels; i++) {
    if (i == 0 && ms->level == 0 && s) {
      /* the whole match */
      luaP_pushlstr(ms->L, s, (size_t)(e - s));
    } else {
      ptrdiff_t l = ms->capture[i].len;
      if (l == CAP_POSITION) {
	luaP_pushint(ms->L, (int)((ms->capture[i].init - ms->src_init) + 1));
      } else {
	ptrdiff_t len = (l == CAP_UNSYNED) ? (e - ms->capture[i].init) : l;
	luaP_pushlstr(ms->L, ms->capture[i].init, (size_t)len);
      }
    }
  }
  return nlevels; }

static int get_capture_len(MatchState *ms, int l, const char *s, const char *e)
{ ptrdiff_t l2 = ms->capture[l].len;
  if (l2 == CAP_POSITION) return 0;
  if (l2 == CAP_UNSYNED) return (int)(e - ms->capture[l].init);
  return (int)l2; }

static const char *class_end(MatchState *ms, const char *p)
{ switch (*p++) {
  case L_ESC: {
    if (p == ms->p_end) paterror(ms, "malformed pattern (ends with '%')");
    if (*p == 'f') {
      p++;
      if (p >= ms->p_end || *p != '[') paterror(ms, "missing '[' after '%f' in pattern");
    }
    return p + 1;
  }
  case '[': {
    if (*p == '^') p++;
    do {
      if (p == ms->p_end) paterror(ms, "malformed pattern (missing ']')");
      if (*(p++) == L_ESC && p < ms->p_end) p++;
    } while (*p != ']');
    return p + 1;
  }
  default: return p;
  } }

static int match_class(int c, int cl)
{ int res;
  switch (tolower(cl)) {
  case 'a': res = isalpha(c); break;
  case 'c': res = iscntrl(c); break;
  case 'd': res = isdigit(c); break;
  case 'g': res = !ispunct(c) && !isspace(c); break;
  case 'l': res = islower(c); break;
  case 'p': res = ispunct(c); break;
  case 's': res = isspace(c); break;
  case 'u': res = isupper(c); break;
  case 'w': res = isalnum(c); break;
  case 'x': res = isxdigit(c); break;
  default: return (cl == c);
  }
  if (isupper(cl)) res = !res;
  return res; }

static int matchbracketclass(MatchState *ms, int c, const char *p, const char *ec)
{ int sig = 1;
  if (*(p+1) == '^') { sig = 0; p++; }
  while (++p < ec) {
    if (*p == L_ESC) {
      p++;
      if (match_class(c, (unsigned char)*p)) return sig;
    } else if (*(p+1) == '-' && p+2 < ec) {
      if ((unsigned char)*p <= c && c <= (unsigned char)*(p+2)) return sig;
      p += 2;
    } else if ((unsigned char)*p == c) return sig;
  }
  return !sig; }

static int singlematch(MatchState *ms, const char *s, const char *p, const char *ep)
{ if (s >= ms->src_end) return 0;
  else {
    int c = (unsigned char)*s;
    switch (*p) {
    case '.': return 1;
    case L_ESC: return match_class(c, (unsigned char)*(p+1));
    case '[': return matchbracketclass(ms, c, p, ep-1);
    default: return ((unsigned char)*p == c);
    } } }

static const char *matchbalance(MatchState *ms, const char *s, const char *p)
{ if (p >= ms->p_end - 1)
    paterror(ms, "malformed pattern (missing arguments to '%b')");
  if (*s != *p) return NULL;
  else {
    int b = *p;
    int e = *(p+1);
    int cont = 1;
    while (++s < ms->src_end) {
      if (*s == e) {
	if (--cont == 0) return s+1;
      } else if (*s == b) cont++;
    }
  }
  return NULL; }

static const char *max_expand(MatchState *ms, const char *s, const char *p, const char *ep)
{ ptrdiff_t i = 0;
  while (singlematch(ms, s + i, p, ep)) i++;
  while (i >= 0) {
    const char *res = match(ms, (s+i), ep+1);
    if (res) return res;
    i--;
  }
  return NULL; }

static const char *min_expand(MatchState *ms, const char *s, const char *p, const char *ep)
{ for (;;) {
    const char *res = match(ms, s, ep+1);
    if (res != NULL) return res;
    else if (singlematch(ms, s, p, ep)) s++;
