#define CAP_UNSYNED (-1)
#define CAP_POSITION (-2)
#define MATCH_MAXDEPTH 200

typedef struct MatchState {
  const char *src_init, *src_end;
  const char *p_end;
  Thread *L;
  int level;
  struct { const char *init; ptrdiff_t len; } capture[LJ_MAX_CAPT];
  int matchdepth;
} MatchState;

static void paterror(MatchState *ms, const char *msg)
{ luaP_errormsg2(ms->L, 1, "%s", msg); }

static int check_capture(MatchState *ms, int l)
{ l -= '1';
  if (l < 0 || l >= ms->level || ms->capture[l].len == CAP_UNSYNED)
    paterror(ms, "invalid capture index");
  return l; }

static int capture_to_close(MatchState *ms)
{ int level = ms->level;
  for (level--; level >= 0; level--) {
    if (ms->capture[level].len == CAP_UNSYNED) return level;
  }
  paterror(ms, "invalid pattern capture");
  return 0; }

static const char *class_end(MatchState *ms, const char *p)
{ switch (*p++) {
  case L_ESC: {
    if (p == ms->p_end) paterror(ms, "malformed pattern (ends with '%')");
    if (*p == 'f') {
      p++;
      if (p >= ms->p_end || *p != '[') paterror(ms, "missing '[' after '%f' in pattern");
    }
    return p + 1;
  }
  case '[': {
    if (*p == '^') p++;
    do {
      if (p == ms->p_end) paterror(ms, "malformed pattern (missing ']')");
      if (*(p++) == L_ESC && p < ms->p_end) p++;
    } while (*p != ']');
    return p + 1;
  }
  default: return p;
  } }

static int match_class(int c, int cl)
{ int res;
  switch (tolower(cl)) {
  case 'a': res = isalpha(c); break;
  case 'c': res = iscntrl(c); break;
  case 'd': res = isdigit(c); break;
  case 'g': res = !ispunct(c) && !isspace(c); break;
  case 'l': res = islower(c); break;
  case 'p': res = ispunct(c); break;
  case 's': res = isspace(c); break;
  case 'u': res = isupper(c); break;
  case 'w': res = isalnum(c); break;
  case 'x': res = isxdigit(c); break;
  default: return (cl == c);
  }
  if (isupper(cl)) res = !res;
  return res; }

static int matchbracketclass(int c, const char *p, const char *ec)
{ int sig = 1;
  if (*(p+1) == '^') { sig = 0; p++; }
  while (++p < ec) {
    if (*p == L_ESC) {
      p++;
      if (match_class(c, (unsigned char)*p)) return sig;
    } else if (*(p+1) == '-' && p+2 < ec) {
      if ((unsigned char)*p <= c && c <= (unsigned char)*(p+2)) return sig;
      p += 2;
    } else if ((unsigned char)*p == c) return sig;
  }
  return !sig; }

static int singlematch(MatchState *ms, const char *s, const char *p, const char *ep)
{ if (s >= ms->src_end) return 0;
  else {
    int c = (unsigned char)*s;
    switch (*p) {
    case '.': return 1;
    case L_ESC: return match_class(c, (unsigned char)*(p+1));
    case '[': return matchbracketclass(c, p, ep-1);
    default: return ((unsigned char)*p == c);
    } } }

static const char *matchbalance(MatchState *ms, const char *s, const char *p)
{ if (p >= ms->p_end - 1)
    paterror(ms, "malformed pattern (missing arguments to '%b')");
  if (*s != *p) return NULL;
  else {
    int b = (unsigned char)*p;
    int e = (unsigned char)*(p+1);
    int cont = 1;
    while (++s < ms->src_end) {
      if (*s == e) {
	if (--cont == 0) return s+1;
      } else if (*s == b) cont++;
    }
  }
  return NULL; }

static const char *max_expand(MatchState *ms, const char *s, const char *p, const char *ep)
{ ptrdiff_t i = 0;
  while (singlematch(ms, s + i, p, ep)) i++;
  while (i >= 0) {
    const char *res = match(ms, (s+i), ep+1);
    if (res) return res;
    i--;
  }
  return NULL; }

static const char *min_expand(MatchState *ms, const char *s, const char *p, const char *ep)
{ for (;;) {
    const char *res = match(ms, s, ep+1);
    if (res != NULL) return res;
    else if (singlematch(ms, s, p, ep)) s++;
    else return NULL;
  } }

static const char *start_capture(MatchState *ms, const char *s, const char *p, int what)
{ const char *res;
  int level = ms->level;
  if (level >= LJ_MAX_CAPT) paterror(ms, "too many captures");
  ms->capture[level].len = what;
  ms->capture[level].init = s;
  ms->level = level + 1;
  if ((res = match(ms, s, p+1)) == NULL)
    ms->level--;
  return res; }

static const char *end_capture(MatchState *ms, const char *s, const char *p)
{ int l = capture_to_close(ms);
  const char *cap = ms->capture[l].init;
  if (ms->capture[l].len == CAP_UNSYNED)
    ms->capture[l].len = s - cap;
  return match(ms, s, p); }

static const char *match_capture(MatchState *ms, const char *s, const char *p)
{ int l = check_capture(ms, *(p+1));
  ptrdiff_t len = ms->capture[l].len;
  if ((size_t)(ms->src_end - s) >= (size_t)len && memcmp(ms->capture[l].init, s, (size_t)len) == 0)
    return s + len;
  else return NULL; }

static const char *match(MatchState *ms, const char *s, const char *p)
{ if (ms->matchdepth-- <= 0) paterror(ms, "pattern too complex");
 init:
  if (p != ms->p_end) {
    switch (*p) {
    case '(': {
      if (*(p + 1) == ')') s = start_capture(ms, s, p, CAP_POSITION);
      else s = start_capture(ms, s, p, CAP_UNSYNED);
      break;
    }
    case ')': {
      s = end_capture(ms, s, p + 1);
      break;
    }
    case '$': {
      if ((p + 1) != ms->p_end) goto dflt;
      s = (s == ms->src_end) ? s : NULL;
      break;
    }
    case L_ESC: {
      switch (*(p + 1)) {
      case 'b': {
	s = matchbalance(ms, s, p + 2);
	if (s != NULL) { p += 4; goto init; }
	break;
      }
      case 'f': {
	const char *ep;
	char previous;
	p += 2;
	if (*p != '[') paterror(ms, "missing '[' after '%f' in pattern");
	ep = class_end(ms, p);
	previous = (s == ms->src_init) ? '\0' : *(s - 1);
	if (!singlematch(ms, s, p, ep) != !(previous ? singlematch(ms, s-1, p, ep) : 0)) {
	  p = ep; goto init;
	}
	s = NULL;
	break;
      }
      default: {
	if (*(p+1) >= '1' && *(p+1) <= '9') {
	  s = match_capture(ms, s, p);
	  if (s != NULL) { p += 2; goto init; }
	  break;
	}
	goto dflt;
      }
      }
      break;
    }
    default: dflt: {
      const char *ep = class_end(ms, p);
      if (!singlematch(ms, s, p, ep)) {
	if (*ep == '*' || *ep == '?' || *ep == '-') { p = ep + 1; goto init; }
	else s = NULL;
      } else {
	switch (*ep) {
	case '?': {
	  const char *res = match(ms, s + 1, ep + 1);
	  if (res != NULL) { ms->matchdepth++; return res; }
	  p = ep + 1; goto init;
	}
	case '+': s++;
	case '*': { const char *r = max_expand(ms, s, p, ep); ms->matchdepth++; return r; }
	case '-': { const char *r = min_expand(ms, s, p, ep); ms->matchdepth++; return r; }
	default: { s++; p = ep; goto init; }
	}
      }
      break;
    }
    }
  }
  ms->matchdepth++;
  return s;
}

static int getcaptures(MatchState *ms, const char *s, const char *e, int whole)
{ int nlevels = (ms->level == 0 && s) ? 1 : ms->level;
  int i;
  if (nlevels >= LJ_MAX_CAPT) nlevels = LJ_MAX_CAPT - 1;
