static int getcaptures(MatchState *ms, const char *s, const char *e, int whole)
{ int nlevels = (ms->level == 0 && s) ? 1 : ms->level;
  int i;
  if (nlevels >= LJ_MAX_CAPT) nlevels = LJ_MAX_CAPT - 1;
