void lib_str_find(Thread *L) { str_find_aux(L, 1); }
void lib_str_match(Thread *L) { str_find_aux(L, 0); }

typedef struct GMatchState { MatchState ms; Str *s; Str *p; int pos; } GMatchState;

void lib_str_gmatch(Thread *L)
{ Val sv = lget(L, 1), pv = lget(L, 2);
  GMatchState *gm;
  if (sv.t != TAG_STR || pv.t != TAG_STR) ltypeerror(L, sv.t != TAG_STR ? 1 : 2, "string");
