  gm->s = strV2(sv);
  gm->p = strV2(pv);
  gm->pos = 0;
  gm->ms.src_init = gm->s->data;
  gm->ms.src_end = gm->s->data + gm->s->len;
  gm->ms.p_end = gm->p->data + gm->p->len;
  gm->ms.L = L;
  gm->ms.matchdepth = MATCH_MAXDEPTH;
