void lib_str_gmatch_iter(Thread *L)
{ Val uv = lget(L, 1);
  GMatchState *gm = (GMatchState*)udV2(uv)->data;
  MatchState *ms = &gm->ms;
  const char *src = gm->s->data + gm->pos;
  const char *e;
  if (gm->pos > (int)gm->s->len) { lpushnil(L); ret(L, 1); return; }
  ms->level = 0;
  e = match_(ms, src, gm->p->data);
  if (e != NULL) {
    int n = getcaptures2(ms, src, e);
    gm->pos = (int)(e - gm->s->data);
