static void add_s(MatchState *ms, char **buf, size_t *len, size_t *cap,
		  const char *s, const char *e, Str *r)
{ size_t l = r->len, i;
  for (i = 0; i < l; i++) {
    if (r->data[i] != L_ESC) {
      APPEND(buf, len, cap, r->data + i, 1);
    } else {
      i++;
      if (i >= l) paterror(ms, "malformed pattern?");  /* hmm */
      if (!isdigit((unsigned char)r->data[i])) {
	if (r->data[i] != L_ESC)
	  lerrorstr(ms->L, "invalid use of '%' in replacement string");
	APPEND(buf, len, cap, r->data + i, 1);
      } else if (r->data[i] == '0') {
	APPEND(buf, len, cap, s, (size_t)(e - s));
      } else {
	int idx = r->data[i] - '1';
	push_onecapture(ms, idx, s, e);
	{ Val v = L->stack[L->top-1];
	  Str *sv = strV2(tostringV(L, v));
	  L->top--;
	  if (sv) APPEND(buf, len, cap, sv->data, sv->len); }
      }
    }
  } }

static void add_value(MatchState *ms, char **buf, size_t *len, size_t *cap,
		      const char *s, const char *e, int tr, Val repl)
{ Thread *L = ms->L;
  if (tr == 2) {  /* function */
    int n;
    lpushval(L, repl);
    n = getcaptures2(ms, s, e);
    lpushval(L, repl);
    ldocall(L, L->top - n - 1, n, 1);
    { Val v = L->stack[L->top-1];
      if (!isfalse(v)) {
	Str *sv = strV2(tostringV(L, v));
	if (!sv) lerrorstr(ms->L, "invalid replacement value (a %s)");
	APPEND(buf, len, cap, sv->data, sv->len);
      }
      L->top--; }
  } else if (tr == 1) {  /* table */
    int n = getcaptures2(ms, s, e);
    { Val key = L->stack[L->top - n];
      Val *res = table_get(tabV2(repl), key);
      Val v = res ? *res : nilV();
      L->top -= n;
      if (!isfalse(v)) {
	Str *sv = strV2(tostringV(L, v));
	if (!sv) lerrorstr(ms->L, "invalid replacement value (a %s)");
	APPEND(buf, len, cap, sv->data, sv->len); } }
  } else {
    Str *r = (repl.t == TAG_STR) ? strV2(repl) : strV2(tostringV(L, repl));
    add_s(ms, buf, len, cap, s, e, r);
  } }

void lib_str_gsub(Thread *L)
{ Str *s = lcheckstr(L, 1);
  Str *p = lcheckstr(L, 2);
  Val repl = lget(L, 3);
  int max_s = loptint(L, 4, -1);
  int anchor = (p->len > 0 && p->data[0] == '^');
  size_t n = 0;
  MatchState ms;
  char *buf = NULL;
  size_t len = 0, cap = 0;
  const char *src = s->data;
  int tr = (repl.t == TAG_FUN) ? 2 : ((repl.t == TAG_TAB) ? 1 : 0);
  const char *pat = p->data + (anchor ? 1 : 0);
  ms.src_init = s->data; ms.src_end = s->data + s->len;
  ms.p_end = p->data + p->len;
  ms.L = L;
  ms.level = 0;
  ms.matchdepth = MATCH_MAXDEPTH;
  if (max_s < 0) max_s = (int)s->len + 1;
  while (n < (size_t)max_s) {
    const char *e;
    ms.level = 0;
    e = match_(&ms, src, pat);
    if (e != NULL) {
      n++;
      add_value(&ms, &buf, &len, &cap, src, e, tr, repl);
    }
    if (e && e > src) src = e;
    else if (src < ms.src_end) APPEND(&buf, &len, &cap, src, 1), src++;
    else break;
    if (anchor) break;
  }
  APPEND(&buf, &len, &cap, src, (size_t)(ms.src_end - src));
  lsettop(L, 0);
  lpushlstr(L, buf ? buf : "", len);
  lpushnum(L, (double)n);
  ret(L, 2);
  if (buf) free(buf); }

