void lib_str_sub(Thread *L)
{ Str *s = lcheckstr(L, 1);
  size_t l = s->len;
  int start = posrelat(loptint(L, 2, 1), l);
  int end = posrelat(loptint(L, 3, -1), l);
  const char *p;
  if (start < 1) start = 1;
  if (end > (int)l) end = (int)l;
  if (start > end) { lsettop(L, 0); lpushlstr(L, "", 0); ret(L, 1); return; }
  p = s->data + start - 1;
  lsettop(L, 0);
  lpushlstr(L, p, (size_t)(end - start + 1)); }

