  lsettop(L, 0);
  lpushlstr(L, b, s->len);
  free(b); }

void lib_str_rep(Thread *L)
{ Str *s = lcheckstr(L, 1);
  int n = lcheckint(L, 2);
  Str *sep = (lgettop(L) >= 3 && istrue(lget(L, 3))) ? lcheckstr(L, 3) : NULL;
  size_t total;
  char *b;
  size_t i, j;
  if (n <= 0) { lsettop(L, 0); lpushlstr(L, "", 0); ret(L, 1); return; }
  total = (size_t)n * s->len + (sep ? (size_t)(n-1) * sep->len : 0);
  if (total > 100000000) lerrorstr(L, "resulting string too large");
