/* --------------------------------------------------------- string funcs -- */
static void push_onecapture(MatchState *ms, int i, const char *s, const char *e)
{ if (i < 0) {
    if (s == NULL) lerrorstr(ms->L, "invalid capture index");
    else lpushlstr(ms->L, s, (size_t)(e - s));
  } else {
    ptrdiff_t l = ms->capture[i].len;
    if (l == CAP_UNSYNED) {
      if (s == NULL) lerrorstr(ms->L, "unfinished capture");
      lpushlstr(ms->L, ms->capture[i].init, (size_t)(e - ms->capture[i].init));
    } else if (l == CAP_POSITION) {
      lpushint(ms->L, (int)((ms->capture[i].init - ms->src_init) + 1));
    } else {
      lpushlstr(ms->L, ms->capture[i].init, (size_t)l);
    }
  }
  (void)0; }

static int getcaptures2(MatchState *ms, const char *s, const char *e)
{ int nlevels = (ms->level == 0 && s) ? 1 : ms->level;
  int i;
  for (i = 0; i < nlevels; i++) push_onecapture(ms, i, s, e);
  return nlevels; }

static void str_find_aux(Thread *L, int find)
{ Str *s = lcheckstr(L, 1);
  Str *p = lcheckstr(L, 2);
  size_t l1 = s->len, l2 = p->len;
  int init = loptint(L, 3, 1);
  int plain = istrue(lget(L, 4));
  MatchState ms;
  const char *s1, *e = NULL;
  int spos = 0;
  init = posrelat(init, l1);
  if (init < 1) init = 1;
  else if ((size_t)init > l1 + 1) {
    lpushnil(L);
    if (find) lpushnil(L);
    ret(L, find ? 2 : 1);
    return;
  }
  s1 = s->data + init - 1;
  ms.src_init = s->data; ms.src_end = s->data + l1;
  ms.p_end = p->data + l2;
  ms.L = L;
  ms.level = 0;
  ms.matchdepth = MATCH_MAXDEPTH;
  if (plain) {
    const char *q = s1;
    while (q + l2 <= s->data + l1) {
      if (memcmp(q, p->data, l2) == 0) { e = q + l2; break; }
      q++;
    }
    if (e) {
      spos = (int)(q - s->data) + 1;
      lpushint(L, spos);
      lpushint(L, (int)(e - s->data));
      ret(L, 2);
      return;
    }
    lpushnil(L);
    if (find) lpushnil(L);
    ret(L, find ? 2 : 1);
    return;
  }
  {
    const char *pp = p->data;
    do {
      ms.level = 0;
      e = match_(&ms, s1, pp);
      if (e != NULL) break;
      s1++;
    } while (s1 <= ms.src_end);
  }
  if (e == NULL) {
    lpushnil(L);
    if (find) lpushnil(L);
    ret(L, find ? 2 : 1);
    return;
  }
  if (find) {
    spos = (int)(s1 - s->data) + 1;
    lpushint(L, spos);
    lpushint(L, (int)(e - s->data));
    ret(L, 2 + getcaptures2(&ms, s1, e));
  } else {
    lsettop(L, lgettop(L) - 0);
    ret(L, getcaptures2(&ms, s1, e));
  }
}

void lib_str_find(Thread *L) { str_find_aux(L, 1); }
void lib_str_match(Thread *L) { str_find_aux(L, 0); }

typedef struct GMatchState { MatchState ms; Str *s; Str *p; int pos; } GMatchState;

void lib_str_gmatch(Thread *L)
{ Val sv = lget(L, 1), pv = lget(L, 2);
  GMatchState *gm;
  if (sv.t != TAG_STR || pv.t != TAG_STR) ltypeerror(L, sv.t != TAG_STR ? 1 : 2, "string");
  gm = (GMatchState*)luaP_malloc(sizeof(GMatchState));
  gm->s = strV2(sv);
  gm->p = strV2(pv);
  gm->pos = 0;
  gm->ms.src_init = gm->s->data;
  gm->ms.src_end = gm->s->data + gm->s->len;
  gm->ms.p_end = gm->p->data + gm->p->len;
  gm->ms.L = L;
  gm->ms.matchdepth = MATCH_MAXDEPTH;
  lsettop(L, 0);
  lpushcfunc(L, lib_str_gmatch_iter, lnextid(), "gmatch_iter");
  lpushval(L, udV(luaP_newudata(L, UD_OTHER, (void*)gm)));
}

void lib_str_gmatch_iter(Thread *L)
{ Val uv = lget(L, 1);
  GMatchState *gm = (GMatchState*)udV2(uv)->data;
  MatchState *ms = &gm->ms;
  const char *src = gm->s->data + gm->pos;
  const char *e;
  if (gm->pos > (int)gm->s->len) { lpushnil(L); ret(L, 1); return; }
  ms->level = 0;
  e = match_(ms, src, gm->p->data);
  if (e != NULL) {
    int n = getcaptures2(ms, src, e);
    gm->pos = (int)(e - gm->s->data);
    if (e == src) gm->pos++;
    ret(L, n);
  } else {
    lpushnil(L);
    ret(L, 1);
  } }

static void add_s(MatchState *ms, char **buf, size_t *len, size_t *cap,
		  const char *s, const char *e, Str *r)
{ size_t l = r->len, i;
  for (i = 0; i < l; i++) {
    if (r->data[i] != L_ESC) {
      APPEND(buf, len, cap, r->data + i, 1);
    } else {
      i++;
      if (i >= l) paterror(ms, "malformed pattern?");  /* hmm */
      if (!isdigit((unsigned char)r->data[i])) {
	if (r->data[i] != L_ESC)
	  lerrorstr(ms->L, "invalid use of '%' in replacement string");
	APPEND(buf, len, cap, r->data + i, 1);
      } else if (r->data[i] == '0') {
	APPEND(buf, len, cap, s, (size_t)(e - s));
      } else {
	int idx = r->data[i] - '1';
	push_onecapture(ms, idx, s, e);
	{ Val v = L->stack[L->top-1];
	  Str *sv = strV2(tostringV(L, v));
	  L->top--;
	  if (sv) APPEND(buf, len, cap, sv->data, sv->len); }
      }
    }
  } }

static void add_value(MatchState *ms, char **buf, size_t *len, size_t *cap,
		      const char *s, const char *e, int tr, Val repl)
{ Thread *L = ms->L;
  if (tr == 2) {  /* function */
    int n;
    lpushval(L, repl);
    n = getcaptures2(ms, s, e);
    lpushval(L, repl);
    ldocall(L, L->top - n - 1, n, 1);
    { Val v = L->stack[L->top-1];
      if (!isfalse(v)) {
	Str *sv = strV2(tostringV(L, v));
	if (!sv) lerrorstr(ms->L, "invalid replacement value (a %s)");
	APPEND(buf, len, cap, sv->data, sv->len);
      }
      L->top--; }
  } else if (tr == 1) {  /* table */
    int n = getcaptures2(ms, s, e);
    { Val key = L->stack[L->top - n];
      Val *res = table_get(tabV2(repl), key);
      Val v = res ? *res : nilV();
      L->top -= n;
      if (!isfalse(v)) {
	Str *sv = strV2(tostringV(L, v));
	if (!sv) lerrorstr(ms->L, "invalid replacement value (a %s)");
	APPEND(buf, len, cap, sv->data, sv->len); } }
  } else {
    Str *r = (repl.t == TAG_STR) ? strV2(repl) : strV2(tostringV(L, repl));
    add_s(ms, buf, len, cap, s, e, r);
  } }

void lib_str_gsub(Thread *L)
{ Str *s = lcheckstr(L, 1);
  Str *p = lcheckstr(L, 2);
  Val repl = lget(L, 3);
  int max_s = loptint(L, 4, -1);
  int anchor = (p->len > 0 && p->data[0] == '^');
  size_t n = 0;
  MatchState ms;
  char *buf = NULL;
  size_t len = 0, cap = 0;
  const char *src = s->data;
