/* --------------------------------------------------------- string funcs -- */
static void push_onecapture(MatchState *ms, int i, const char *s, const char *e)
{ if (i < 0) {
    if (s == NULL) lerrorstr(ms->L, "invalid capture index");
    else lpushlstr(ms->L, s, (size_t)(e - s));
  } else {
    ptrdiff_t l = ms->capture[i].len;
    if (l == CAP_UNSYNED) {
      if (s == NULL) lerrorstr(ms->L, "unfinished capture");
      lpushlstr(ms->L, ms->capture[i].init, (size_t)(e - ms->capture[i].init));
    } else if (l == CAP_POSITION) {
      lpushint(ms->L, (int)((ms->capture[i].init - ms->src_init) + 1));
    } else {
      lpushlstr(ms->L, ms->capture[i].init, (size_t)l);
    }
  }
  (void)0; }

static int getcaptures2(MatchState *ms, const char *s, const char *e)
{ int nlevels = (ms->level == 0 && s) ? 1 : ms->level;
  int i;
  for (i = 0; i < nlevels; i++) push_onecapture(ms, i, s, e);
  return nlevels; }

static void str_find_aux(Thread *L, int find)
{ Str *s = lcheckstr(L, 1);
  Str *p = lcheckstr(L, 2);
  size_t l1 = s->len, l2 = p->len;
  int init = loptint(L, 3, 1);
  int plain = istrue(lget(L, 4));
  MatchState ms;
  const char *s1, *e = NULL;
  int spos = 0;
  init = posrelat(init, l1);
  if (init < 1) init = 1;
  else if ((size_t)init > l1 + 1) {
    lpushnil(L);
    if (find) lpushnil(L);
    ret(L, find ? 2 : 1);
    return;
  }
  s1 = s->data + init - 1;
  ms.src_init = s->data; ms.src_end = s->data + l1;
  ms.p_end = p->data + l2;
  ms.L = L;
  ms.level = 0;
  ms.matchdepth = MATCH_MAXDEPTH;
  if (plain) {
    const char *q = s1;
    while (q + l2 <= s->data + l1) {
      if (memcmp(q, p->data, l2) == 0) { e = q + l2; break; }
      q++;
    }
    if (e) {
      spos = (int)(q - s->data) + 1;
      lpushint(L, spos);
      lpushint(L, (int)(e - s->data));
      ret(L, 2);
      return;
    }
    lpushnil(L);
    if (find) lpushnil(L);
    ret(L, find ? 2 : 1);
    return;
  }
  {
    const char *pp = p->data;
    do {
      ms.level = 0;
      e = match_(&ms, s1, pp);
      if (e != NULL) break;
      s1++;
