void lib_str_format(Thread *L)
{ Str *f = lcheckstr(L, 1);
  size_t i = 0;
  char *buf = NULL; size_t len = 0, cap = 0;
  int arg = 2;
  int ntop = lgettop(L);
  (void)ntop;
  while (i < f->len) {
    if (f->data[i] != '%') { APPEND(&buf, &len, &cap, f->data + i, 1); i++; continue; }
    i++;
    if (i >= f->len) { lerrorstr(L, "invalid option '%' to 'format'"); }
    if (f->data[i] == '%') { APPEND(&buf, &len, &cap, "%", 1); i++; continue; }
    {
      char form[80];
      size_t fi = 0;
      char conv;
      /* flags */
      while (i < f->len && strchr("-+ #0", f->data[i])) { form[fi++] = f->data[i]; i++; }
      /* width */
      if (i < f->len && f->data[i] == '*') {
	int w = lcheckint_(L, arg++);
	char tmp[32];
	snprintf(tmp, sizeof(tmp), "%d", w);
	memcpy(form + fi, tmp, strlen(tmp)); fi += strlen(tmp);
	i++;
      } else {
	while (i < f->len && isdigit((unsigned char)f->data[i])) { form[fi++] = f->data[i]; i++; }
      }
      /* precision */
      if (i < f->len && f->data[i] == '.') {
	form[fi++] = '.';
	i++;
	if (i < f->len && f->data[i] == '*') {
	  int p = lcheckint_(L, arg++);
	  char tmp[32];
	  snprintf(tmp, sizeof(tmp), "%d", p);
	  memcpy(form + fi, tmp, strlen(tmp)); fi += strlen(tmp);
	  i++;
	} else {
	  while (i < f->len && isdigit((unsigned char)f->data[i])) { form[fi++] = f->data[i]; i++; }
	}
      }
      if (i >= f->len) lerrorstr(L, "invalid conversion to 'format'");
      conv = f->data[i++];
      form[fi++] = conv;
      form[fi] = 0;
      switch (conv) {
      case 'c': case 'd': case 'i': case 'o': case 'u': case 'x': case 'X': {
	int v = lcheckint_(L, arg);
	if (conv == 'c') {
	  char c = (char)v;
	  APPEND(&buf, &len, &cap, &c, 1);
	} else {
	  char tmp[256];
	  form[fi-1] = (conv == 'i') ? 'd' : ((conv == 'u') ? 'u' : conv);
	  form[fi] = 0;
	  if (conv == 'u') { unsigned int uv = (unsigned int)v;
	    snprintf(tmp, sizeof(tmp), form, uv); }
	  else snprintf(tmp, sizeof(tmp), form, v);
	  APPEND(&buf, &len, &cap, tmp, strlen(tmp));
	}
	break; }
      case 'e': case 'E': case 'f': case 'g': case 'G': case 'a': case 'A': {
	double v = lchecknum_(L, arg);
	char tmp[512];
	if (fi - 1 < (int)sizeof(form)) { form[fi-1] = conv; form[fi] = 0; }
	snprintf(tmp, sizeof(tmp), form, v);
	APPEND(&buf, &len, &cap, tmp, strlen(tmp));
	break; }
      case 's': case 'q': {
	Val v = lget(L, arg);
	Str *s = strV2(tostringV(L, v));
	if (!s) lerrorstr(L, "string expected");
	if (conv == 's') { APPEND(&buf, &len, &cap, s->data, s->len); }
	else {
	  size_t j;
	  APPEND(&buf, &len, &cap, "\"", 1);
	  for (j = 0; j < s->len; j++) {
	    unsigned char c = (unsigned char)s->data[j];
	    char tmp[8];
	    if (c == '"' || c == '\\') { tmp[0] = '\\'; tmp[1] = (char)c; APPEND(&buf, &len, &cap, tmp, 2); }
	    else if (c == '\n') { tmp[0] = '\\'; tmp[1] = '\n'; APPEND(&buf, &len, &cap, tmp, 2); }
	    else if (iscntrl(c)) { int n2 = snprintf(tmp, sizeof(tmp), "\\%u", (unsigned)c);
	      APPEND(&buf, &len, &cap, tmp, (size_t)n2); }
	    else APPEND(&buf, &len, &cap, s->data + j, 1);
	  }
	  APPEND(&buf, &len, &cap, "\"", 1);
	}
	break; }
      case 'p': {
	Val v = lget(L, arg);
	char tmp[64];
	snprintf(tmp, sizeof(tmp), "%p", (void*)v.u.g);
	APPEND(&buf, &len, &cap, tmp, strlen(tmp));
	break; }
      default:
	lerrorstr(L, "invalid option to 'format'");
	break;
      }
      arg++;
    }
  }
  lsettop(L, 0);
  lpushlstr(L, buf ? buf : "", len);
  ret(L, 1);
  if (buf) free(buf); }

/* ---------------------------------------------- registration ------------- */
static void reg1(Thread *L, Table *t, const char *name, CFunction_ f, uint32_t id)
{ lpushcfunc(L, f, id, name);
  table_setstr(L, t, luaP_newstr(L, name, strlen(name)), L->stack[L->top-1]);
  L->top--; }

void lib_str_register(Thread *L, Table *t)
{ reg1(L, t, "byte", lib_str_byte, 76);
  reg1(L, t, "char", lib_str_char, 77);
  reg1(L, t, "sub", lib_str_sub, 78);
  reg1(L, t, "rep", lib_str_rep, 79);
