    pos = lcheckint(L, 2);
    if (pos < 0) pos += n + 1;
  } else pos = n;
  if (pos < 1 || pos > n) { lsettop(L, 0); lpushnil(L); ret(L, 1); return; }
  v = table_geti(t, pos);
  { int i;
    for (i = pos; i < n; i++) table_seti(L, t, i, table_geti(t, i + 1));
