void lib_tab_getn(Thread *L) { int n = aux_getn(L, 1); lsettop(L, 0); lpushint(L, n); }
void lib_tab_maxn(Thread *L)
{ Table *t = lchecktable(L, 1);
  double max = 0;
  Val key, val;
  int64_t n = 0;
