  n = table_getn(t);
  { Val k = nilV();
    while (table_next(t, k, &k, &val)) {
      if (k.t == TAG_NUM && (k.u.n > max || (max == 0 && isfalse(table_geti(t, (int64_t)max)))))
	if (k.u.n > max) max = k.u.n;
    } }
  lsettop(L, 0);
  lpushnum(L, max); }

typedef struct SortCtx { Thread *L; Table *t; int hascmp; } SortCtx;

static void sort_comp(Thread *L, Table *t, int hascmp, Val a, Val b, int *out)
{ if (hascmp) {
    lpushval(L, lcmpval(L));
    lpushval(L, a);
    lpushval(L, b);
    ldocall(L, L->top - 3, 2, 1);
    *out = istrue(L->stack[L->top-1]);
    L->top--;
  } else {
    lj_compare(L, a, b, MM_LT, out);
  } }

static void auxsort(Thread *L, Table *t, int hascmp, int lo, int up)
{ while (lo < up) {
    int i = lo, j = up;
    Val p = table_geti(t, (int64_t)((lo + up) / 2));
    for (;;) {
      int r;
      Val vi;
      while (i < up) {
	int cmp;
	vi = table_geti(t, i);
	sort_comp(L, t, hascmp, vi, p, &cmp);
	if (!cmp) break;
	i++;
      }
      while (j > lo) {
	int cmp;
	Val vj = table_geti(t, j);
	sort_comp(L, t, hascmp, p, vj, &cmp);
	if (!cmp) break;
	j--;
      }
      if (j <= i) break;
      { Val a = table_geti(t, i), b = table_geti(t, j);
	table_seti(L, t, i, b);
	table_seti(L, t, j, a); }
      i++; j--;
      if (i > j) break;
    }
    if (i == 0) lerrorstr(L, "invalid order function for sorting");
    { /* check that the pivot element is in place */
      Val v = table_geti(t, i);
      int cmp;
      sort_comp(L, t, hascmp, p, v, &cmp);
      if (cmp) lerrorstr(L, "invalid order function for sorting"); }
    if (i - lo >= up - i) { auxsort(L, t, hascmp, i + 1, up); up = i - 1; }
    else { auxsort(L, t, hascmp, lo, i - 1); lo = i + 1; }
  } }

void lib_tab_sort(Thread *L)
{ Table *t = lchecktable(L, 1);
  int n = aux_getn(L, 1);
  int hascmp = (lgettop(L) >= 2 && istrue(lget(L, 2)));
  lsettop(L, 0);
  if (hascmp) { Val f = lget_orig(L, 2); lsetcmpval(L, f); }
  auxsort(L, t, hascmp, 1, n);
