void lib_tab_move(Thread *L)
{ Val t1v = lget(L, 1);
  Table *t1 = lchecktable(L, 1);
  int f = lcheckint(L, 2);
  int e = lcheckint(L, 3);
  int t = lcheckint(L, 4);
  Val t2v = lget(L, 5);
  Table *t2 = (istrue(t2v)) ? lchecktable(L, 5) : t1;
  int n;
  if (t2v.t == TAG_NIL) { t2v = t1v; t2 = t1; }
  if (e < f) { lsettop(L, 0); lpushval(L, t2v); ret(L, 1); return; }
  n = e - f + 1;
  if (t > e - f + 1 && t1 == t2) {
    /* move backwards */
    int i;
    for (i = n - 1; i >= 0; i--) {
      table_seti(L, t2, t + i, table_geti(t1, f + i));
    }
  } else {
    int i;
    for (i = 0; i < n; i++) {
      Val v = table_geti(t1, f + i);
      table_seti(L, t2, t + i, v);
    }
  }
  lsettop(L, 0);
  lpushval(L, t2v);
  ret(L, 1); }

void lib_tab_unpack(Thread *L)
{ Table *t = lchecktable(L, 1);
  int i = loptint(L, 2, 1);
  int j;
  int n = 0;
  if (lgettop(L) >= 3) j = lcheckint(L, 3);
  else j = (int)table_getn(t);
  lsettop(L, 0);
  for (; i <= j; i++, n++) lpushval(L, table_geti(t, i));
  ret(L, n); }

void lib_tab_foreach(Thread *L)
{ Table *t = lchecktable(L, 1);
  Val f = lget(L, 2);
  Val k = nilV(), v;
  lsettop(L, 0);
  while (table_next(t, k, &k, &v)) {
    int st;
    lpushval(L, f);
    lpushval(L, k);
    lpushval(L, v);
    st = ldocall_ret(L, L->top - 3, 2, 1);
    if (st) { /* the callback returned nil: stop */ }
    { Val r = L->stack[L->top-1];
      if (!isfalse(r)) { ret(L, 2); return; }
      L->top--; }
  }
  ret(L, 0); }

void lib_tab_foreachi(Thread *L)
{ Table *t = lchecktable(L, 1);
  Val f = lget(L, 2);
  int n = aux_getn(L, 1);
  int i;
  lsettop(L, 0);
  for (i = 1; i <= n; i++) {
    Val v = table_geti(t, i);
    lpushval(L, f);
    lpushint(L, i);
    lpushval(L, v);
    ldocall(L, L->top - 3, 2, 1);
    { Val r = L->stack[L->top-1];
      if (!isfalse(r)) { ret(L, 2); return; }
      L->top--; }
  }
  ret(L, 0); }

void lib_tab_register(Thread *L, Table *t)
{ reg1(L, t, "concat", lib_tab_concat, 92);
  reg1(L, t, "insert", lib_tab_insert, 91);
  reg1(L, t, "remove", lib_tab_remove, 0);
  reg1(L, t, "sort", lib_tab_sort, 93);
  reg1(L, t, "move", lib_tab_move, 0);
  reg1(L, t, "unpack", lib_tab_unpack, 0);
  reg1(L, t, "getn", lib_tab_getn, 0);
  reg1(L, t, "maxn", lib_tab_maxn, 90);
  reg1(L, t, "foreach", lib_tab_foreach, 0);
  reg1(L, t, "foreachi", lib_tab_foreachi, 0);
  lsettop(L, 0); }
CEOF
echo ok"}

