{ double a = lchecknum(L, 1), b = lchecknum(L, 2);
  lsettop(L, 0); lpushnum(L, pow(a, b)); }
void lib_math_fmod(Thread *L)
{ double a = lchecknum(L, 1), b = lchecknum(L, 2);
  lsettop(L, 0); lpushnum(L, fmod(a, b)); }
void lib_math_ldexp(Thread *L)
{ double a = lchecknum(L, 1);
  int e = lcheckint(L, 2);
  lsettop(L, 0); lpushnum(L, ldexp(a, e)); }
void lib_math_deg(Thread *L) { double d = lchecknum(L, 1); lsettop(L, 0); lpushnum(L, d * (180.0 / 3.14159265358979323846)); }
void lib_math_rad(Thread *L) { double d = lchecknum(L, 1); lsettop(L, 0); lpushnum(L, d * (3.14159265358979323846 / 180.0)); }
void lib_math_min(Thread *L)
{ int n = lgettop(L);
  double m;
  int i;
  if (n < 1) largerr(L, 1, "number expected, got no value");
  m = lchecknum(L, 1);
  for (i = 2; i <= n; i++) { double d = lchecknum(L, i); if (d < m) m = d; }
  lsettop(L, 0); lpushnum(L, m); }
void lib_math_max(Thread *L)
{ int n = lgettop(L);
  double m;
  int i;
  if (n < 1) largerr(L, 1, "number expected, got no value");
  m = lchecknum(L, 1);
  for (i = 2; i <= n; i++) { double d = lchecknum(L, i); if (d > m) m = d; }
  lsettop(L, 0); lpushnum(L, m); }

/* Tausworthe PRNG (period 2^223) */
static uint32_t pr_u = 0x11090601, pr_v = 0, pr_w = 0;
static void pr_seed(uint64_t seed)
{ uint32_t r = 0x11090601;
  uint32_t u = (uint32_t)seed;
  uint32_t v = (uint32_t)(seed >> 32);
  int i;
  for (i = 0; i < 4; i++) {
    uint32_t m = 1u << (r & 255);
    r >>= 8;
    u = (u ^ m) * 0x5bd1e995u;
    u = (u << 13) | (u >> 19);
    v = (v ^ m) * 0x5bd1e995u;
    v = (v << 13) | (v >> 19);
  }
  pr_u = u; pr_v = v; pr_w = 0x11090601; }

static uint32_t pr_step(void)
{ uint32_t u = pr_u;
  /* Tausworthe 3 */
  u ^= ((u << 13) | (u >> 19));
  u ^= (u >> 7);
  u ^= ((u << 17) | (u >> 15));
  pr_u = u;
  return u; }

void lib_math_random(Thread *L)
{ int n = lgettop(L);
  if (n == 0) {
    /* 52 pseudo-random bits */
    uint64_t r = ((uint64_t)pr_step() << 32) | pr_step();
    double d = (double)(r >> 11) * (1.0 / 9007199254740992.0);
    lsettop(L, 0);
    lpushnum(L, d);
    return;
  }
  if (n == 1) {
    double m = lchecknum(L, 1);
    double d;
    uint64_t r = ((uint64_t)pr_step() << 32) | pr_step();
    d = (double)(r >> 11) * (1.0 / 9007199254740992.0);
    lsettop(L, 0);
    if (m <= 0) lerrorstr(L, "interval is empty");
    lpushnum(L, floor(d * m) + 1);
    return;
  }
  { double m = lchecknum(L, 1), mn = lchecknum(L, 2);
    double d;
    uint64_t r = ((uint64_t)pr_step() << 32) | pr_step();
    d = (double)(r >> 11) * (1.0 / 9007199254740992.0);
    lsettop(L, 0);
    if (mn < m) lerrorstr(L, "interval is empty");
    lpushnum(L, floor(d * (mn - m + 1)) + m);
    return; } }

void lib_math_randomseed(Thread *L)
{ Val v = lget(L, 1);
  if (isfalse(v)) {
    pr_seed((uint64_t)time(NULL) * 2654435769u);
  } else {
    double d = lchecknum(L, 1);
    union { double d; uint64_t u; } x;
    x.d = d;
    pr_seed(x.u);
  }
  lsettop(L, 0); }

void lib_math_register(Thread *L, Table *t)
{ lreg1(L, t, "abs", lib_math_abs, 38);
  lreg1(L, t, "floor", lib_math_floor, 39);
  lreg1(L, t, "ceil", lib_math_ceil, 40);
  lreg1(L, t, "sqrt", lib_math_sqrt, 41);
  lreg1(L, t, "log10", lib_math_log10, 42);
  lreg1(L, t, "exp", lib_math_exp, 43);
  lreg1(L, t, "sin", lib_math_sin, 44);
  lreg1(L, t, "cos", lib_math_cos, 45);
  lreg1(L, t, "tan", lib_math_tan, 46);
  lreg1(L, t, "asin", lib_math_asin, 47);
  lreg1(L, t, "acos", lib_math_acos, 48);
  lreg1(L, t, "atan", lib_math_atan, 49);
  lreg1(L, t, "sinh", lib_math_sinh, 50);
  lreg1(L, t, "cosh", lib_math_cosh, 51);
  lreg1(L, t, "tanh", lib_math_tanh, 52);
  lreg1(L, t, "frexp", lib_math_frexp, 53);
  lreg1(L, t, "modf", lib_math_modf, 54);
  lreg1(L, t, "log", lib_math_log, 55);
  lreg1(L, t, "atan2", lib_math_atan2, 56);
  lreg1(L, t, "pow", lib_math_pow, 57);
  lreg1(L, t, "fmod", lib_math_fmod, 58);
  lreg1(L, t, "ldexp", lib_math_ldexp, 59);
  lreg1(L, t, "min", lib_math_min, 60);
  lreg1(L, t, "max", lib_math_max, 61);
  lreg1(L, t, "random", lib_math_random, 62);
  lreg1(L, t, "randomseed", lib_math_randomseed, 63);
  lreg1(L, t, "deg", lib_math_deg, 0);
  lreg1(L, t, "rad", lib_math_rad, 0);
  lsettop(L, 0);
  table_setstr(L, t, luaP_newstr(L, "pi", 2), numV(3.14159265358979323846));
  table_setstr(L, t, luaP_newstr(L, "huge", 4), numV(HUGE_VAL)); }

/* ------------------------------------------------------------ bit lib ---- */
static int32_t bit_arg(Thread *L, int idx)
{ Val v = lget(L, idx);
  if (v.t == TAG_NUM) return lj_numtoint(v.u.n);
  if (v.t == TAG_STR) { double d; if (str2num(strV2(v)->data, strV2(v)->len, &d)) return lj_numtoint(d); }
  largerr(L, idx, "number expected, got %s", luaP_typename(v));
  return 0; }

void lib_bit_tobit(Thread *L) { int32_t a = bit_arg(L, 1); lsettop(L, 0); lpushnum(L, (double)(int32_t)a); }
void lib_bit_bnot(Thread *L) { int32_t a = bit_arg(L, 1); lsettop(L, 0); lpushnum(L, (double)(int32_t)~a); }
void lib_bit_band(Thread *L)
{ int n = lgettop(L);
  uint32_t r = 0xffffffffu;
  int i;
  if (n < 1) largerr(L, 1, "number expected, got no value");
  for (i = 1; i <= n; i++) r &= (uint32_t)bit_arg(L, i);
  lsettop(L, 0);
  lpushnum(L, (double)(int32_t)r); }
void lib_bit_bor(Thread *L)
{ int n = lgettop(L);
  uint32_t r = 0;
  int i;
  if (n < 1) largerr(L, 1, "number expected, got no value");
  for (i = 1; i <= n; i++) r |= (uint32_t)bit_arg(L, i);
  lsettop(L, 0);
  lpushnum(L, (double)(int32_t)r); }
void lib_bit_bxor(Thread *L)
{ int n = lgettop(L);
  uint32_t r = 0;
  int i;
  if (n < 1) largerr(L, 1, "number expected, got no value");
  for (i = 1; i <= n; i++) r ^= (uint32_t)bit_arg(L, i);
  lsettop(L, 0);
  lpushnum(L, (double)(int32_t)r); }
static int32_t shmask(int32_t n) { return n & 31; }
void lib_bit_lshift(Thread *L)
{ int32_t a = bit_arg(L, 1), n = bit_arg(L, 2);
  lsettop(L, 0);
  lpushnum(L, (double)(int32_t)((uint32_t)a << shmask(n))); }
void lib_bit_rshift(Thread *L)
{ int32_t a = bit_arg(L, 1), n = bit_arg(L, 2);
  lsettop(L, 0);
  lpushnum(L, (double)(int32_t)((uint32_t)a >> shmask(n))); }
void lib_bit_arshift(Thread *L)
{ int32_t a = bit_arg(L, 1), n = bit_arg(L, 2);
  lsettop(L, 0);
  lpushnum(L, (double)(int32_t)(a >> shmask(n))); }
void lib_bit_rol(Thread *L)
{ int32_t a = bit_arg(L, 1), n = bit_arg(L, 2);
  uint32_t u = (uint32_t)a;
  int32_t s = shmask(n);
  lsettop(L, 0);
  lpushnum(L, (double)(int32_t)((u << s) | (u >> (32 - s)))); }
void lib_bit_ror(Thread *L)
{ int32_t a = bit_arg(L, 1), n = bit_arg(L, 2);
  uint32_t u = (uint32_t)a;
  int32_t s = shmask(n);
  lsettop(L, 0);
  lpushnum(L, (double)(int32_t)((u >> s) | (u << (32 - s)))); }
void lib_bit_bswap(Thread *L)
{ int32_t a = bit_arg(L, 1);
  uint32_t u = (uint32_t)a;
  lsettop(L, 0);
  lpushnum(L, (double)(int32_t)(((u & 0xff) << 24) | ((u & 0xff00) << 8) |
			       ((u & 0xff0000) >> 8) | ((u & 0xff000000) >> 24))); }
void lib_bit_tohex(Thread *L)
{ int32_t a = bit_arg(L, 1);
  int n = loptint(L, 2, 8);
  char buf[128];
  int i;
  uint32_t u = (uint32_t)a;
  int neg = 0;
  if (n == 0) { lsettop(L, 0); lpushlstr(L, "", 0); ret(L, 1); return; }
  if (n < 0) { neg = 1; n = -n; }
  if (n > 100) n = 100;
  for (i = 0; i < n; i++) {
    int shift = 4 * ((n - 1 - i) % 8);
    int d;
    if (neg) d = (int)(((uint32_t)~u >> shift) & 0xf);
    else d = (int)((u >> shift) & 0xf);
    buf[i] = (char)(d < 10 ? '0' + d : (neg ? 'a' + d - 10 : 'A' + d - 10));
  }
  buf[n] = 0;
  lsettop(L, 0);
  lpushlstr(L, buf, (size_t)n); }

void lib_bit_register(Thread *L, Table *t)
{ lreg1(L, t, "tobit", lib_bit_tobit, 64);
  lreg1(L, t, "bnot", lib_bit_bnot, 65);
  lreg1(L, t, "bswap", lib_bit_bswap, 66);
  lreg1(L, t, "lshift", lib_bit_lshift, 67);
  lreg1(L, t, "rshift", lib_bit_rshift, 68);
  lreg1(L, t, "arshift", lib_bit_arshift, 69);
  lreg1(L, t, "rol", lib_bit_rol, 70);
  lreg1(L, t, "ror", lib_bit_ror, 71);
  lreg1(L, t, "band", lib_bit_band, 72);
  lreg1(L, t, "bor", lib_bit_bor, 73);
  lreg1(L, t, "bxor", lib_bit_bxor, 74);
  lreg1(L, t, "tohex", lib_bit_tohex, 75);
  lsettop(L, 0); }
