/* table, math and bit libraries */
#include "llib.h"
#include <math.h>
#include <time.h>
#include <stdlib.h>

/* registration helper (shared) */
void lreg1(Thread *L, Table *t, const char *name, CFunction_ f, uint32_t id)
{ lpushcfunc(L, f, id, name);
  table_setstr(L, t, luaP_newstr(L, name, strlen(name)), L->stack[L->top-1]);
  L->top--; }

/* ---------------------------------------------------------- table lib ---- */
static int aux_getn(Thread *L, int idx) { return (int)table_getn(lchecktable(L, idx)); }

void lib_tab_concat(Thread *L)
{ Table *t = lchecktable(L, 1);
  size_t total = 0;
  int i, sep = 0;
  Str *ssep = NULL;
  int i0 = loptint(L, 2, 1);
  int i1;
  char *buf;
  { Val sv = lget(L, 2); if (istrue(sv)) { ssep = lcheckstr(L, 2); sep = 1; } }
  i1 = loptint(L, 3, -1);
  if (i1 == -1) i1 = aux_getn(L, 1);
  else if (i1 < 0) i1 += aux_getn(L, 1) + 1;
  { Val v = lget(L, 4); if (istrue(v)) i1 = lcheckint(L, 4); }
  if (i0 > i1) { lsettop(L, 0); lpushlstr(L, "", 0); ret(L, 1); return; }
  for (i = i0; i <= i1; i++) {
    Val v = table_geti(t, i);
    Str *s;
    if (isfalse(v)) largerr(L, i, "invalid value (nil) at index %d in table for 'concat'", i);
    s = strV2(tostringV(L, v));
    if (!s) largerr(L, i, "invalid value (%s) at index %d in table for 'concat'", luaP_typename(v), i);
    total += s->len + (i > i0 ? (size_t)sep : 0);
  }
  buf = (char*)luaP_malloc(total + 1);
  { size_t p = 0;
    for (i = i0; i <= i1; i++) {
      Val v = table_geti(t, i);
      Str *s = strV2(tostringV(L, v));
      if (i > i0 && sep) { memcpy(buf + p, ssep->data, ssep->len); p += ssep->len; }
      memcpy(buf + p, s->data, s->len); p += s->len;
    } }
  lsettop(L, 0);
  lpushlstr(L, buf, total);
  ret(L, 1);
  free(buf); }

void lib_tab_insert(Thread *L)
{ Table *t = lchecktable(L, 1);
  int n = (int)table_getn(t);
  if (lgettop(L) < 2) largerr(L, 2, "value expected");
  if (lgettop(L) == 2) {
    Val v = larg(L, 2);
    lsettop(L, 0);
    table_seti(L, t, n + 1, v);
  } else {
    int pos = lcheckint(L, 2);
    Val v = larg(L, 3);
    int i;
    lsettop(L, 0);
    for (i = n; i >= pos; i--) {
      Val x = table_geti(t, i);
      table_seti(L, t, i + 1, x);
    }
    table_seti(L, t, pos, v);
  } }

void lib_tab_remove(Thread *L)
{ Table *t = lchecktable(L, 1);
  int n = (int)table_getn(t);
  int pos;
  Val v;
  if (lgettop(L) >= 2) {
    pos = lcheckint(L, 2);
    if (pos < 0) pos += n + 1;
  } else pos = n;
  if (pos < 1 || pos > n) { lsettop(L, 0); lpushnil(L); ret(L, 1); return; }
  v = table_geti(t, pos);
  { int i;
    for (i = pos; i < n; i++) table_seti(L, t, i, table_geti(t, i + 1));
    table_seti(L, t, n, nilV()); }
  lsettop(L, 0);
  lpushval(L, v);
  ret(L, 1); }

void lib_tab_getn(Thread *L) { int n = aux_getn(L, 1); lsettop(L, 0); lpushint(L, n); }

void lib_tab_maxn(Thread *L)
{ Table *t = lchecktable(L, 1);
  double max = 0;
  Val k = nilV(), val;
  while (table_next(t, k, &k, &val)) {
    if (k.t == TAG_NUM && k.u.n > max) max = k.u.n;
  }
  lsettop(L, 0);
  lpushnum(L, max); }

static Val g_cmp;

static void sort_comp(Thread *L, int hascmp, Val a, Val b, int *out)
{ if (hascmp) {
    lpushval(L, g_cmp);
    lpushval(L, a);
    lpushval(L, b);
    ldocall(L, L->top - 3, 2, 1);
    *out = istrue(L->stack[L->top-1]);
    L->top--;
  } else lj_compare(L, a, b, MM_LT, out); }

static void auxsort(Thread *L, int hascmp, int lo, int up, Table *t)
{ while (lo < up) {
    int i = lo, j = up;
    Val p = table_geti(t, (int64_t)((lo + up) / 2));
    for (;;) {
      int cmp;
      while (i < up) {
	sort_comp(L, hascmp, table_geti(t, i), p, &cmp);
	if (!cmp) break;
	i++;
      }
      while (j > lo) {
	sort_comp(L, hascmp, p, table_geti(t, j), &cmp);
	if (!cmp) break;
	j--;
      }
      if (j <= i) break;
      { Val a = table_geti(t, i), b = table_geti(t, j);
	table_seti(L, t, i, b);
	table_seti(L, t, j, a); }
      i++; j--;
      if (i > j) break;
    }
    if (i == 0) lerrorstr(L, "invalid order function for sorting");
    { int cmp;
      sort_comp(L, hascmp, p, table_geti(t, i), &cmp);
      if (cmp) lerrorstr(L, "invalid order function for sorting"); }
    if (i - lo >= up - i) { auxsort(L, hascmp, i + 1, up, t); up = i - 1; }
    else { auxsort(L, hascmp, lo, i - 1, t); lo = i + 1; }
  } }

void lib_tab_sort(Thread *L)
{ Table *t = lchecktable(L, 1);
  int n = aux_getn(L, 1);
  int hascmp = (lgettop(L) >= 2 && istrue(larg(L, 2)));
  if (hascmp) g_cmp = larg(L, 2);
  lsettop(L, 0);
  auxsort(L, hascmp, 1, n, t);
  g_cmp = nilV(); }

void lib_tab_move(Thread *L)
{ Table *t1 = lchecktable(L, 1);
  int f = lcheckint(L, 2);
  int e = lcheckint(L, 3);
  int t = lcheckint(L, 4);
  Val t2v = lget(L, 5);
  Table *t2;
  int n, i;
  if (istrue(t2v)) t2 = lchecktable(L, 5);
  else { t2 = t1; t2v = larg(L, 1); }
  if (e < f) { lsettop(L, 0); lpushval(L, t2v); ret(L, 1); return; }
  n = e - f + 1;
  for (i = 0; i < n; i++) {
    Val v = table_geti(t1, f + i);
    table_seti(L, t2, t + i, v);
  }
  lsettop(L, 0);
  lpushval(L, t2v);
  ret(L, 1); }

void lib_tab_unpack(Thread *L)
{ Table *t = lchecktable(L, 1);
  int i = loptint(L, 2, 1);
  int j, n = 0;
  { Val v = lget(L, 3); j = istrue(v) ? lcheckint(L, 3) : (int)table_getn(t); }
  lsettop(L, 0);
  for (; i <= j; i++, n++) lpushval(L, table_geti(t, i));
  ret(L, n); }

void lib_tab_foreach(Thread *L)
{ Table *t = lchecktable(L, 1);
  Val f = larg(L, 2);
  Val k = nilV(), v;
  lsettop(L, 0);
  while (table_next(t, k, &k, &v)) {
    lpushval(L, f);
    lpushval(L, k);
    lpushval(L, v);
    ldocall(L, L->top - 3, 2, 1);
    { Val r = L->stack[L->top-1];
      if (!isfalse(r)) { ret(L, 2); return; }
      L->top--; }
  }
  ret(L, 0); }

void lib_tab_foreachi(Thread *L)
{ Table *t = lchecktable(L, 1);
  Val f = larg(L, 2);
  int n = aux_getn(L, 1);
  int i;
  lsettop(L, 0);
  for (i = 1; i <= n; i++) {
    lpushval(L, f);
    lpushint(L, i);
    lpushval(L, table_geti(t, i));
    ldocall(L, L->top - 3, 2, 1);
    { Val r = L->stack[L->top-1];
      if (!isfalse(r)) { ret(L, 2); return; }
      L->top--; }
  }
  ret(L, 0); }

void lib_tab_register(Thread *L, Table *t)
{ lreg1(L, t, "concat", lib_tab_concat, 92);
  lreg1(L, t, "insert", lib_tab_insert, 91);
  lreg1(L, t, "remove", lib_tab_remove, 0);
  lreg1(L, t, "sort", lib_tab_sort, 93);
  lreg1(L, t, "move", lib_tab_move, 0);
  lreg1(L, t, "unpack", lib_tab_unpack, 0);
  lreg1(L, t, "getn", lib_tab_getn, 0);
  lreg1(L, t, "maxn", lib_tab_maxn, 90);
  lreg1(L, t, "foreach", lib_tab_foreach, 0);
  lreg1(L, t, "foreachi", lib_tab_foreachi, 0);
  lsettop(L, 0); }

/* ----------------------------------------------------------- math lib ---- */
void lib_math_abs(Thread *L) { double d = lchecknum(L, 1); lsettop(L, 0); lpushnum(L, fabs(d)); }
void lib_math_floor(Thread *L) { double d = lchecknum(L, 1); lsettop(L, 0); lpushnum(L, floor(d)); }
void lib_math_ceil(Thread *L) { double d = lchecknum(L, 1); lsettop(L, 0); lpushnum(L, ceil(d)); }
void lib_math_sqrt(Thread *L) { double d = lchecknum(L, 1); lsettop(L, 0); lpushnum(L, sqrt(d)); }
