void lib_math_exp(Thread *L) { double d = lchecknum(L, 1); lsettop(L, 0); lpushnum(L, exp(d)); }
void lib_math_sin(Thread *L) { double d = lchecknum(L, 1); lsettop(L, 0); lpushnum(L, sin(d)); }
void lib_math_cos(Thread *L) { double d = lchecknum(L, 1); lsettop(L, 0); lpushnum(L, cos(d)); }
void lib_math_tan(Thread *L) { double d = lchecknum(L, 1); lsettop(L, 0); lpushnum(L, tan(d)); }
void lib_math_asin(Thread *L) { double d = lchecknum(L, 1); lsettop(L, 0); lpushnum(L, asin(d)); }
void lib_math_acos(Thread *L) { double d = lchecknum(L, 1); lsettop(L, 0); lpushnum(L, acos(d)); }
void lib_math_atan(Thread *L) { double d = lchecknum(L, 1); lsettop(L, 0); lpushnum(L, atan(d)); }
void lib_math_sinh(Thread *L) { double d = lchecknum(L, 1); lsettop(L, 0); lpushnum(L, sinh(d)); }
