static int aux_getn(Thread *L, int idx) { return (int)table_getn(lchecktable(L, idx)); }

void lib_tab_concat(Thread *L)
{ Table *t = lchecktable(L, 1);
  size_t total = 0;
  int i, sep = 0;
  Str *ssep = NULL;
  int i0 = loptint(L, 2, 1);
  int i1;
  char *buf;
  { Val sv = lget(L, 2); if (istrue(sv)) { ssep = lcheckstr(L, 2); sep = 1; } }
