void lib_tab_insert(Thread *L)
{ Table *t = lchecktable(L, 1);
  int n = (int)table_getn(t);
  if (lgettop(L) < 2) largerr(L, 2, "value expected");
  if (lgettop(L) == 2) {
    Val v = larg(L, 2);
    lsettop(L, 0);
    table_seti(L, t, n + 1, v);
  } else {
    int pos = lcheckint(L, 2);
    Val v = larg(L, 3);
    int i;
    lsettop(L, 0);
    for (i = n; i >= pos; i--) {
      Val x = table_geti(t, i);
      table_seti(L, t, i + 1, x);
    }
    table_seti(L, t, pos, v);
  } }

void lib_tab_remove(Thread *L)
{ Table *t = lchecktable(L, 1);
