static Val g_cmp;

static void sort_comp(Thread *L, int hascmp, Val a, Val b, int *out)
{ if (hascmp) {
    lpushval(L, g_cmp);
    lpushval(L, a);
    lpushval(L, b);
    ldocall(L, L->top - 3, 2, 1);
    *out = istrue(L->stack[L->top-1]);
    L->top--;
  } else lj_compare(L, a, b, MM_LT, out); }

static void auxsort(Thread *L, int hascmp, int lo, int up, Table *t)
{ while (lo < up) {
    int i = lo, j = up;
    Val p = table_geti(t, (int64_t)((lo + up) / 2));
    for (;;) {
      int cmp;
      while (i < up) {
	sort_comp(L, hascmp, table_geti(t, i), p, &cmp);
	if (!cmp) break;
	i++;
      }
      while (j > lo) {
	sort_comp(L, hascmp, p, table_geti(t, j), &cmp);
	if (!cmp) break;
	j--;
      }
      if (j <= i) break;
      { Val a = table_geti(t, i), b = table_geti(t, j);
	table_seti(L, t, i, b);
	table_seti(L, t, j, a); }
      i++; j--;
      if (i > j) break;
    }
    if (i == 0) lerrorstr(L, "invalid order function for sorting");
    { int cmp;
      sort_comp(L, hascmp, p, table_geti(t, i), &cmp);
      if (cmp) lerrorstr(L, "invalid order function for sorting"); }
    if (i - lo >= up - i) { auxsort(L, hascmp, i + 1, up, t); up = i - 1; }
    else { auxsort(L, hascmp, lo, i - 1, t); lo = i + 1; }
  } }

