typedef struct IOFile { FILE *fp; int closed; int typeofopen; } IOFile;
static Val g_input, g_output;

static IOFile *tofile(Thread *L, int idx)
{ Val v = lget(L, idx);
  if (v.t == TAG_UDATA && udV2(v)->kind == UD_FILE) {
    IOFile *f = (IOFile*)udV2(v)->data;
