static Val pushfile(Thread *L, IOFile *f)
{ UData *u = luaP_newudata(L, UD_FILE, (void*)f);
  lpushval(L, udV(u));
  return udV(u); }

static void io_register_file_methods(Thread *L, Table *mt);

static IOFile *newfile(Thread *L, FILE *fp)
{ IOFile *f = (IOFile*)luaP_malloc(sizeof(IOFile));
  f->fp = fp; f->closed = 0; f->typeofopen = 0;
  pushfile(L, f);
  { Val uv = L->stack[L->top-1];
    UData *u = udV2(uv);
