void lib_io_open(Thread *L)
{ const char *fn = lcheckstr(L, 1)->data;
  const char *mode = loptstr(L, 2, "r");
  FILE *fp = fopen(fn, mode);
  IOFile *f;
  lsettop(L, 0);
  if (!fp) {
    lpushnil(L);
    lpushstring(L, strerror(errno));
    lpushint(L, errno);
    ret(L, 3);
    return;
  }
  f = newfile(L, fp);
  { const char *m = mode;
    if (strchr(m, 'w')) f->typeofopen = 1;
    else if (strchr(m, 'a')) f->typeofopen = 2;
    else f->typeofopen = 0; }
  ret(L, 1); }

void lib_io_close(Thread *L)
{ IOFile *f = tofile(L, 1);
  int r = fclose(f->fp);
  f->closed = 1;
  lsettop(L, 0);
  if (r == 0) ret(L, 0);
  else { lpushnil(L); lpushstring(L, strerror(errno)); lpushint(L, errno); ret(L, 3); } }

