void lib_io_seek(Thread *L)
{ IOFile *f = tofile(L, 1);
  const char *whence = loptstr(L, 2, "cur");
  long off = 0;
  int w = SEEK_CUR;
  long r;
  if (istrue(lget(L, 3))) off = (long)lchecknum(L, 3);
  if (strcmp(whence, "set") == 0) w = SEEK_SET;
  else if (strcmp(whence, "cur") == 0) w = SEEK_CUR;
