    if (n < sizeof(buf) - 1) buf[n++] = (char)c;
    else { lpushlstr(L, buf, n); return 2; }
  }
  if (!got) { lpushnil(L); return 1; }
  lpushlstr(L, buf, n);
  return 0; }

static void read_all(Thread *L, FILE *fp)
{ size_t cap = 8192, len = 0;
  char *buf = (char*)luaP_malloc(cap);
  size_t r;
  while ((r = fread(buf + len, 1, cap - len, fp)) > 0) {
    len += r;
    if (len == cap) { cap *= 2; { char *nb = (char*)luaP_malloc(cap); memcpy(nb, buf, len); free(buf); buf = nb; } }
  }
  lpushlstr(L, buf, len);
  free(buf); }

static void read_number(Thread *L, FILE *fp)
{ /* read a number: skip leading whitespace, then scan a number */
  int c;
  char buf[64];
  size_t n = 0;
  double d = 0;
  int ok = 0;
  do { c = getc(fp); } while (c != EOF && isspace(c));
  if (c == EOF) { lpushnil(L); return; }
  ungetc(c, fp);
  while ((c = getc(fp)) != EOF && !isspace(c)) {
    if (n < sizeof(buf) - 1) buf[n++] = (char)c;
    else break;
  }
  if (c != EOF && n < sizeof(buf) - 1) ungetc(c, fp);
  buf[n] = 0;
  if (str2num(buf, n, &d)) ok = 1;
  if (ok) lpushnum(L, d);
  else lpushnil(L); }

void lib_io_read(Thread *L)
{ IOFile *f = tofile(L, 1);
  int n = lgettop(L);
  int i;
  lsettop(L, 0);
  if (n == 1) { /* no format: read a line */
    read_line(L, f->fp, 0);
    ret(L, 1);
    return;
  }
  for (i = 2; i <= n; i++) {
    Val v = lget(L, i);
    if (v.t == TAG_NUM) {
      int k = (int)v.u.n;
      char *buf = (char*)luaP_malloc(k + 1);
      size_t r = fread(buf, 1, (size_t)k, f->fp);
      if (r == 0) { lpushnil(L); }
      else lpushlstr(L, buf, r);
      free(buf);
    } else {
      Str *s = lcheckstr(L, i);
      const char *p = s->data;
      if (p[0] == '*') p++;
      switch (p[0]) {
      case 'l': read_line(L, f->fp, 0); break;
      case 'L': read_line(L, f->fp, 1); break;
      case 'a': read_all(L, f->fp); break;
      case 'n': read_number(L, f->fp); break;
      default: largerr(L, i, "invalid format");
      }
    }
  }
  ret(L, n - 1); }

void lib_io_write(Thread *L)
{ IOFile *f = tofile(L, 1);
  int n = lgettop(L);
  int i;
  for (i = 2; i <= n; i++) {
    Val v = lget(L, i);
    Str *s = strV2(tostringV(L, v));
    if (s) fwrite(s->data, 1, s->len, f->fp);
  }
  lsettop(L, 0);
  ret(L, 1); }

void lib_io_lines(Thread *L)
{ Val v = lget(L, 1);
  IOFile *f;
  lsettop(L, 0);
  if (v.t == TAG_UDATA && udV2(v)->kind == UD_FILE) {
    f = tofile(L, 1);
  } else {
    Str *s = lcheckstr(L, 1);
    FILE *fp = fopen(s->data, "r");
    if (!fp) largerr(L, 1, "%s: %s", s->data, strerror(errno));
    f = newfile(L, fp);
    f->typeofopen = 3;  /* to close on EOF */
  }
  lpushcfunc(L, lib_io_lines_iter, lnextid(), "lines_iter");
  { UData *u = luaP_newudata(L, UD_FILE, (void*)f);
    lpushval(L, udV(u)); }
  ret(L, 2); }

void lib_io_lines_iter(Thread *L)
{ Val v = lget(L, 1);
  IOFile *f = (IOFile*)udV2(v)->data;
  lsettop(L, 0);
  if (f->closed) { lpushnil(L); ret(L, 1); return; }
  { int r = read_line(L, f->fp, 0);
    if (r == 1) {
      if (f->typeofopen == 3) { fclose(f->fp); f->closed = 1; }
      lpushnil(L);
      ret(L, 1);
    } else ret(L, 1); } }

void lib_io_input(Thread *L)
{ Val v = lget(L, 1);
  if (isfalse(v)) { lsettop(L, 0); lpushval(L, g_input); ret(L, 1); return; }
  if (v.t == TAG_UDATA && udV2(v)->kind == UD_FILE) { g_input = v; lsettop(L, 0); lpushval(L, g_input); ret(L, 1); return; }
  { Str *s = lcheckstr(L, 1);
    FILE *fp = fopen(s->data, "r");
    lsettop(L, 0);
    if (!fp) largerr(L, 1, "cannot open file '%s' (%s)", s->data, strerror(errno));
    g_input = pushfile(L, newfile(L, fp));
    ret(L, 1); } }

void lib_io_output(Thread *L)
{ Val v = lget(L, 1);
  if (isfalse(v)) { lsettop(L, 0); lpushval(L, g_output); ret(L, 1); return; }
  if (v.t == TAG_UDATA && udV2(v)->kind == UD_FILE) { g_output = v; lsettop(L, 0); lpushval(L, g_output); ret(L, 1); return; }
  { Str *s = lcheckstr(L, 1);
    FILE *fp = fopen(s->data, "w");
    lsettop(L, 0);
    if (!fp) largerr(L, 1, "cannot open file '%s' (%s)", s->data, strerror(errno));
    g_output = pushfile(L, newfile(L, fp));
    ret(L, 1); } }

void lib_io_tmpfile(Thread *L)
{ FILE *fp = tmpfile();
  lsettop(L, 0);
  if (!fp) { lpushnil(L); ret(L, 1); return; }
  pushfile(L, newfile(L, fp));
  ret(L, 1); }

void lib_io_popen(Thread *L)
{ const char *cmd = lcheckstr(L, 1)->data;
  const char *mode = loptstr(L, 2, "r");
  FILE *fp = popen(cmd, mode);
  lsettop(L, 0);
  if (!fp) { lpushnil(L); lpushstring(L, strerror(errno)); lpushint(L, errno); ret(L, 3); return; }
  pushfile(L, newfile(L, fp));
  ret(L, 1); }

void lib_io_type(Thread *L)
{ Val v = lget(L, 1);
  lsettop(L, 0);
  if (v.t == TAG_UDATA && udV2(v)->kind == UD_FILE) {
    IOFile *f = (IOFile*)udV2(v)->data;
    if (f && !f->closed) lpushstring(L, "file");
    else lpushstring(L, "closed file");
  } else lpushnil(L);
  ret(L, 1); }

void lib_io_fclose(Thread *L) { lib_io_close(L); }
void lib_io_gc(Thread *L)
{ Val v = lget(L, 1);
  IOFile *f = (IOFile*)udV2(v)->data;
  if (f && !f->closed) { fclose(f->fp); f->closed = 1; }
  lsettop(L, 0); }

void lib_io_register(Thread *L, Table *t, Table *mt, Val stdin_ud, Val stdout_ud, Val stderr_ud)
{ extern void lreg1(Thread *L, Table *t, const char *name, CFunction_ f, uint32_t id);
  lreg1(L, t, "open", lib_io_open, 0);
  lreg1(L, t, "close", lib_io_close, 0);
  lreg1(L, t, "flush", lib_io_flush, 0);
  lreg1(L, t, "seek", lib_io_seek, 0);
  lreg1(L, t, "read", lib_io_read, 0);
  lreg1(L, t, "write", lib_io_write, 0);
  lreg1(L, t, "lines", lib_io_lines, 0);
  lreg1(L, t, "input", lib_io_input, 0);
  lreg1(L, t, "output", lib_io_output, 0);
  lreg1(L, t, "tmpfile", lib_io_tmpfile, 0);
  lreg1(L, t, "popen", lib_io_popen, 0);
  lreg1(L, t, "type", lib_io_type, 0);
  lsettop(L, 0);
  io_register_file_methods(L, mt);
  table_setstr(L, t, luaP_newstr(L, "stdin", 5), stdin_ud);
  table_setstr(L, t, luaP_newstr(L, "stdout", 6), stdout_ud);
  table_setstr(L, t, luaP_newstr(L, "stderr", 6), stderr_ud);
  g_input = stdout_ud; g_input = stdin_ud;
  g_output = stdout_ud; }

static void io_register_file_methods(Thread *L, Table *mt)
{ lreg1(L, mt, "close", lib_io_close, 0);
  lreg1(L, mt, "flush", lib_io_flush, 0);
  lreg1(L, mt, "lines", lib_io_lines, 0);
  lreg1(L, mt, "read", lib_io_read, 0);
  lreg1(L, mt, "seek", lib_io_seek, 0);
  lreg1(L, mt, "setvbuf", lib_io_setvbuf, 0);
  lreg1(L, mt, "write", lib_io_write, 0);
  lreg1(L, mt, "__gc", lib_io_gc, 0);
  lsettop(L, 0); }

void lib_io_setvbuf(Thread *L)
{ IOFile *f = tofile(L, 1);
  const char *mode = loptstr(L, 2, "full");
  lsettop(L, 0);
  if (strcmp(mode, "no") == 0) setvbuf(f->fp, NULL, _IONBF, 0);
  else if (strcmp(mode, "full") == 0) setvbuf(f->fp, NULL, _IOFBF, 4096);
  else if (strcmp(mode, "line") == 0) setvbuf(f->fp, NULL, _IOLBF, 4096);
  ret(L, 0); }
CEOF
echo ok; wc -l llib3.c"}

