/* -------------------------------------------------------------- os lib --- */
void lib_os_time(Thread *L)
{ Val v = lget(L, 1);
  lsettop(L, 0);
  if (istrue(v)) {
    Table *t = lchecktable(L, 1);
    struct tm tm;
    time_t r;
    memset(&tm, 0, sizeof(tm));
    tm.tm_year = (int)loptnumv(L, t, "year", 0) - 1900;
    tm.tm_mon = (int)loptnumv(L, t, "month", 1) - 1;
    tm.tm_mday = (int)loptnumv(L, t, "day", 1);
    tm.tm_hour = (int)loptnumv(L, t, "hour", 12);
    tm.tm_min = (int)loptnumv(L, t, "min", 0);
    tm.tm_sec = (int)loptnumv(L, t, "sec", 0);
    tm.tm_isdst = (int)loptnumv(L, t, "isdst", 0);
    r = mktime(&tm);
    lpushnum(L, (double)r);
    ret(L, 1);
    return;
  }
  lpushnum(L, (double)time(NULL));
  ret(L, 1); }

void lib_os_date(Thread *L)
{ const char *fmt = loptstr(L, 1, "%c");
  double t = loptnum(L, 2, (double)time(NULL));
  char buf[512];
  struct tm tmv;
  lsettop(L, 0);
  if (fmt[0] == '!') { fmt++;
    { time_t tt = (time_t)t;
      gmtime_r(&tt, &tmv); } }
  else { time_t tt = (time_t)t; localtime_r(&tt, &tmv); }
  if (fmt[0] == '*' && fmt[1] == 't') {
    Table *r = luaP_newtable(L);
    lpushval(L, tabV(r));
    table_setstr(L, r, luaP_newstr(L, "year", 4), numV(tmv.tm_year + 1900));
    table_setstr(L, r, luaP_newstr(L, "month", 5), numV(tmv.tm_mon + 1));
    table_setstr(L, r, luaP_newstr(L, "day", 3), numV(tmv.tm_mday));
    table_setstr(L, r, luaP_newstr(L, "hour", 4), numV(tmv.tm_hour));
    table_setstr(L, r, luaP_newstr(L, "min", 3), numV(tmv.tm_min));
    table_setstr(L, r, luaP_newstr(L, "sec", 3), numV(tmv.tm_sec));
    table_setstr(L, r, luaP_newstr(L, "wday", 4), numV(tmv.tm_wday + 1));
    table_setstr(L, r, luaP_newstr(L, "yday", 4), numV(tmv.tm_yday));
    table_setstr(L, r, luaP_newstr(L, "isdst", 5), boolV(tmv.tm_isdst));
    ret(L, 1);
    return;
  }
  strftime(buf, sizeof(buf), fmt, &tmv);
  lpushstring(L, buf);
  ret(L, 1); }

void lib_os_clock(Thread *L) { lsettop(L, 0); lpushnum(L, (double)clock() / (double)CLOCKS_PER_SEC); }
void lib_os_difftime(Thread *L)
{ double a = lchecknum(L, 1);
  double b = loptnum(L, 2, 0);
  lsettop(L, 0);
  lpushnum(L, difftime((time_t)a, (time_t)b)); }
void lib_os_getenv(Thread *L)
{ const char *s = lcheckstr(L, 1)->data;
  const char *r = getenv(s);
  lsettop(L, 0);
  if (r) lpushstring(L, r); else lpushnil(L);
  ret(L, 1); }
void lib_os_execute(Thread *L)
{ const char *cmd = lcheckstr(L, 1)->data;
  int r = system(cmd);
  lsettop(L, 0);
  if (cmd[0] == 0) { lpushnum(L, r ? -1 : 0); ret(L, 1); return; }
  lpushnum(L, (double)r);
  ret(L, 1); }
void lib_os_exit(Thread *L)
{ Val v = lget(L, 1);
  Val close = lget(L, 2);
  int code = 0;
  if (istrue(v)) {
    if (v.t == TAG_TRUE) code = EXIT_SUCCESS;
    else code = (int)lchecknum(L, 1);
  }
  (void)close;
  fflush(stdout);
  exit(code); }
void lib_os_remove(Thread *L)
{ const char *fn = lcheckstr(L, 1)->data;
  int r = remove(fn);
  lsettop(L, 0);
  if (r == 0) { lpushtrue(L); ret(L, 1); return; }
  lpushnil(L); lpushstring(L, strerror(errno)); lpushint(L, errno); ret(L, 3); }
void lib_os_rename(Thread *L)
{ const char *a = lcheckstr(L, 1)->data;
  const char *b = lcheckstr(L, 2)->data;
  int r = rename(a, b);
  lsettop(L, 0);
  if (r == 0) { lpushtrue(L); ret(L, 1); return; }
  lpushnil(L); lpushstring(L, strerror(errno)); lpushint(L, errno); ret(L, 3); }
void lib_os_setlocale(Thread *L)
{ const char *cat = loptstr(L, 2, "all");
  const char *loc = loptstr(L, 1, NULL);
  int c = LC_ALL;
  if (strcmp(cat, "collate") == 0) c = LC_COLLATE;
  else if (strcmp(cat, "ctype") == 0) c = LC_CTYPE;
  else if (strcmp(cat, "monetary") == 0) c = LC_MONETARY;
  else if (strcmp(cat, "numeric") == 0) c = LC_NUMERIC;
  else if (strcmp(cat, "time") == 0) c = LC_TIME;
  else if (strcmp(cat, "all") != 0) largerr(L, 2, "invalid category");
  { const char *r = setlocale(c, loc);
    lsettop(L, 0);
    if (r) lpushstring(L, r); else lpushnil(L);
    ret(L, 1); } }
void lib_os_tmpname(Thread *L)
{ char buf[256];
  lsettop(L, 0);
  snprintf(buf, sizeof(buf), "/tmp/lua_%d.tmp", (int)getpid());
  lpushstring(L, buf);
  ret(L, 1); }

void lib_os_register(Thread *L, Table *t)
{ lreg1(L, t, "clock", lib_os_clock, 0);
  lreg1(L, t, "date", lib_os_date, 0);
  lreg1(L, t, "difftime", lib_os_difftime, 0);
  lreg1(L, t, "execute", lib_os_execute, 0);
  lreg1(L, t, "exit", lib_os_exit, 0);
  lreg1(L, t, "getenv", lib_os_getenv, 0);
  lreg1(L, t, "remove", lib_os_remove, 0);
  lreg1(L, t, "rename", lib_os_rename, 0);
  lreg1(L, t, "setlocale", lib_os_setlocale, 0);
  lreg1(L, t, "time", lib_os_time, 0);
  lreg1(L, t, "tmpname", lib_os_tmpname, 0);
  lsettop(L, 0); }

/* -------------------------------------------------------- coroutine lib -- */
void lib_coro_create(Thread *L)
{ Val f = lget(L, 1);
  Thread *co;
  if (f.t != TAG_FUN || funV2(f)->isC) largerr(L, 1, "Lua function expected");
  co = luaP_newthread(L);
  co->co = f;
  co->env = funV2(f)->env;
  lsettop(L, 0);
  { UData *u = luaP_newudata(L, UD_CORO, (void*)co);
    co->co = udV(u);
    lpushval(L, udV(u)); }
  ret(L, 1); }

void lib_coro_status(Thread *L)
{ Val v = lget(L, 1);
  Thread *co;
  lsettop(L, 0);
  if (v.t != TAG_UDATA || udV2(v)->kind != UD_CORO) largerr(L, 1, "coroutine expected");
  co = (Thread*)udV2(v)->data;
  if (co->status == 0) lpushstring(L, "running");
  else if (co->status == 1) lpushstring(L, "suspended");
  else lpushstring(L, "dead");
  ret(L, 1); }

void lib_coro_yield(Thread *L)
{ luaP_yield(L, lgettop(L)); }

void lib_coro_resume(Thread *L)
{ Val v = lget(L, 1);
  Thread *co;
  int n;
  if (v.t != TAG_UDATA || udV2(v)->kind != UD_CORO) largerr(L, 1, "coroutine expected");
  co = (Thread*)udV2(v)->data;
  n = lgettop(L) - 1;
  luaP_resume(L, co, n);
  { /* the results are at [base, ...) — move them */
    int base = CURBASE;
    int cnt = L->top - base;
    (void)cnt;
  }
  ret(L, L->top - CURBASE); }

void lib_coro_wrap(Thread *L)
{ Val f = lget(L, 1);
  Thread *co;
  if (f.t != TAG_FUN || funV2(f)->isC) largerr(L, 1, "Lua function expected, got %s", luaP_typename(f));
  co = luaP_newthread(L);
  co->co = f;
  co->env = funV2(f)->env;
  lsettop(L, 0);
  { UData *u = luaP_newudata(L, UD_CORO, (void*)co);
    co->co = udV(u);
    lpushval(L, udV(u)); }
  lpushcfunc(L, lib_coro_wrap_iter, lnextid(), "wrap_iter");
  lpushval(L, L->stack[L->top-1]);
  ret(L, 2); }

void lib_coro_wrap_iter(Thread *L)
{ Val v = lget(L, 1);
  Thread *co = (Thread*)udV2(v)->data;
  int n = lgettop(L) - 1;
  lsettop(L, 0);
  luaP_resume(L, co, n);
  { int cnt = L->top - CURBASE;
    int i;
    Val *res = (Val*)luaP_malloc(sizeof(Val) * (cnt > 0 ? cnt : 1));
    for (i = 0; i < cnt; i++) res[i] = L->stack[CURBASE + i];
    lsettop(L, 0);
    if (!istrue(res[0])) { /* error: propagate */
      lerror(L, res[1]);
    }
    for (i = 1; i < cnt; i++) lpushval(L, res[i]);
    ret(L, cnt - 1);
    free(res); } }

void lib_coro_running(Thread *L)
{ Thread *cur = curthread;
  lsettop(L, 0);
  if (cur && cur->co.t == TAG_UDATA) {
    UData *u = udV2(cur->co);
    if (u->kind == UD_CORO) { lpushval(L, cur->co); ret(L, 1); return; }
  }
  lpushnil(L);
  ret(L, 1); }

void lib_coro_isyieldable(Thread *L)
{ int can = 0;
  int i;
  if (curthread) {
    for (i = curthread->nframes - 1; i >= 0; i--) {
      Frame *fr = &curthread->frames[i];
      if (fr->kind == FR_C && !fr->cont) { can = 0; break; }
    }
    if (i < 0) can = 1;
  }
  lsettop(L, 0);
  lpushbool(L, can);
  ret(L, 1); }

void lib_coro_register(Thread *L, Table *t)
{ lreg1(L, t, "status", lib_coro_status, 30);
  lreg1(L, t, "running", lib_coro_running, 31);
  lreg1(L, t, "isyieldable", lib_coro_isyieldable, 32);
  lreg1(L, t, "create", lib_coro_create, 33);
  lreg1(L, t, "yield", lib_coro_yield, 34);
  lreg1(L, t, "resume", lib_coro_resume, 35);
  lreg1(L, t, "wrap", lib_coro_wrap, 37);
  lsettop(L, 0); }
CEOF
echo ok; wc -l llib3.c"}

