int lj_jit_status(Thread *L, int on)
{ extern void lpushstatus(Thread *L, int on);
  lpushstatus(L, on);
  ret(L, lgettop(L));
  return 0; }

void lpushstatus(Thread *L, int on)
{ /* jit.status() returns: bool, cpu features..., opt flags... */
  lpushbool(L, on);
  lpushstring(L, "SSE3");
  lpushstring(L, "SSE4.1");
  lpushstring(L, "BMI2");
  lpushstring(L, "fold");
  lpushstring(L, "cse");
  lpushstring(L, "dce");
  lpushstring(L, "fwd");
  lpushstring(L, "dse");
  lpushstring(L, "narrow");
  lpushstring(L, "loop");
  lpushstring(L, "abc");
  lpushstring(L, "sink");
  lpushstring(L, "fuse"); }

int lj_opt_flag_valid(const char *s)
{ static const char *flags[] = { "fold", "cse", "dce", "fwd", "dse", "narrow", "loop", "abc", "sink", "fuse", "fma", "srec", "fuse", NULL };
  int i;
  for (i = 0; flags[i]; i++) if (strcmp(flags[i], s) == 0) return 1;
  { /* numeric level */
    int all_digits = (*s != 0);
    const char *p = s;
    while (*p) { if (!isdigit((unsigned char)*p)) { all_digits = 0; break; } p++; }
    if (all_digits) return 1;
  }
  return 0; }
CEOF
