int main(int argc, char **argv)
{ Thread *L;
  int i;
  int interactive = 0;
  int has_i = 0, has_v = 0;
  int has_e = 0;
  int stopopts = 0;
  int scriptidx = -1;
  extern void luaL_openlibs(Thread *L);
  extern int lj_jit_on_flag;
