	{ extern int lj_dojitcmd(Thread *L, const char *cmd);
	  if (lj_dojitcmd(L, cmd)) return 1; }
	continue;
      }
      if (a[1] == 'O') {
	extern int lj_dojitopt(Thread *L, const char *opt);
	if (lj_dojitopt(L, a + 2)) return 1;
	continue;
      }
      if (strcmp(a, "-i") == 0) { has_i = 1; preargs[npre++] = argv[i]; continue; }
      if (strcmp(a, "-v") == 0) { has_v = 1; preargs[npre++] = argv[i]; continue; }
      if (strcmp(a, "-E") == 0) { preargs[npre++] = argv[i]; continue; }
      if (a[1] == '-' && a[2] == 0) { stopopts = 1; continue; }
      if (a[1] == 0) {
	/* '-' : read stdin and stop handling options */
