    }
    if (dochunk(L, buf, len, luaP_newstr(L, "stdin", 5), 0)) return 1;
  } else if (scriptidx >= 0) {
    char errbuf[512];
    extern Func *lj_loadfile(Thread *L, const char *fn, Str *chunkname, int mode, char *errbuf, size_t errlen);
    Func *f = lj_loadfile(L, argv[scriptidx], luaP_newstr(L, argv[scriptidx], strlen(argv[scriptidx])), 0, errbuf, sizeof(errbuf));
    if (!f) { report(L, strV(luaP_newstr(L, errbuf, strlen(errbuf))), 0); return 1; }
    { ErrCtx ctx;
      int st;
      int target = L->nframes;
      lpushval(L, funV(f));
      { int funcidx = L->top - 1;
	st = lj_protect(L, &ctx, 1);
	if (st == 0) {
	  luaP_docall(L, funcidx, 0, 0, FRK_MAIN, NULL);
