/* Stubs for the extra extension modules (ffi, string.buffer, table.new/clear,
 * jit.util, jit.profile) and the -j / -O command handling. */
#include "llib.h"

/* ---- ffi ---- */
void lib_ffi_register(Thread *L, Table *preload)
{ Table *ffi = luaP_newtable(L);
  table_setstr(L, preload, luaP_newstr(L, "ffi", 3), tabV(ffi));
  table_setstr(L, ffi, luaP_newstr(L, "abi", 3), strV(luaP_newstr(L, "64", 2)));
  table_setstr(L, ffi, luaP_newstr(L, "arch", 4), strV(luaP_newstr(L, "x64", 3)));
  table_setstr(L, ffi, luaP_newstr(L, "os", 2), strV(luaP_newstr(L, "Linux", 5)));
  lsettop(L, 0); }

/* ---- string.buffer ---- */
void lib_buf_register(Thread *L, Table *preload)
{ Table *b = luaP_newtable(L);
  table_setstr(L, preload, luaP_newstr(L, "string.buffer", 13), tabV(b));
  lsettop(L, 0); }

/* ---- table.new / table.clear ---- */
void lib_tabextra_register(Thread *L, Table *preload)
{ lpushcfunc(L, lib_tab_new, 94, "table.new");
  table_setstr(L, preload, luaP_newstr(L, "table.new", 9), L->stack[L->top-1]); L->top--;
  lpushcfunc(L, lib_tab_clear, 95, "table.clear");
  table_setstr(L, preload, luaP_newstr(L, "table.clear", 11), L->stack[L->top-1]); L->top--;
  lsettop(L, 0); }

void lib_tab_new(Thread *L)
{ int narr = loptint(L, 1, 0);
  int nhash = loptint(L, 2, 0);
  Table *t = luaP_newtable(L);
  table_resize(L, t, (uint32_t)narr, (uint32_t)nhash);
  lsettop(L, 0);
  lpushval(L, tabV(t));
  ret(L, 1); }

void lib_tab_clear(Thread *L)
{ Table *t = lchecktable(L, 1);
  table_clear(t);
  lsettop(L, 0); ret(L, 0); }

/* ---- jit.util / jit.profile ---- */
void lib_jitu_register(Thread *L, Table *jit)
{ Table *u = luaP_newtable(L);
  table_setstr(L, preload_g, luaP_newstr(L, "jit.util", 8), tabV(u));
  { Table *p = luaP_newtable(L);
    table_setstr(L, preload_g, luaP_newstr(L, "jit.profile", 11), tabV(p));
    lpushcfunc(L, lib_prof_start, lnextid(), "profile_start");
    table_setstr(L, p, luaP_newstr(L, "start", 5), L->stack[L->top-1]); L->top--;
    lsettop(L, 0); }
  lsettop(L, 0); }

void lib_prof_start(Thread *L)
{ /* jit.profile.start(mode, cb[, thread]) */
  Val cb = lget(L, 2);
  lsettop(L, 0);
  if (cb.t != TAG_FUN) largerr(L, 2, "function expected, got no value");
  ret(L, 0); }

/* ---- -j handling ---- */
int lj_dojitcmd(Thread *L, const char *cmd)
{ const char *eq = strchr(cmd, '=');
  size_t len = eq ? (size_t)(eq - cmd) : strlen(cmd);
  const char *arg = eq ? eq + 1 : NULL;
  char name[64];
  Val jit;
  extern Table *jit_table_g;
  if (len >= sizeof(name)) len = sizeof(name) - 1;
  memcpy(name, cmd, len);
  name[len] = 0;
  jit = luaP_getglobal(L, "jit");
  if (jit.t == TAG_TAB) {
    Val f = table_getstr(tabV2(jit), luaP_newstr(L, name, strlen(name)));
    if (f.t == TAG_FUN) {
      lpushval(L, f);
      if (arg) lpushstring(L, arg);
      ldocall(L, L->top - 1 - (arg ? 1 : 0), arg ? 1 : 0, 0);
      lsettop(L, CURBASE);
