      { Val *pv = lj_pkg_preload ? table_getstr(lj_pkg_preload, luaP_newstr(L, modname, strlen(modname))) : NULL;
	if (pv && istrue(*pv)) {
	  Val m;
	  lpushval(L, *pv);
	  lpushstring(L, modname);
	  ldocall(L, L->top - 2, 1, 1);
	  m = L->stack[L->top-1];
	  L->top--;
	  if (m.t == TAG_TAB) {
	    Val st = table_getstr(tabV2(m), luaP_newstr(L, "start", 5));
	    if (st.t == TAG_FUN) {
	      lpushval(L, st);
	      if (arg) lpushstring(L, arg);
	      ldocall(L, L->top - 1 - (arg ? 1 : 0), arg ? 1 : 0, 0);
	      lsettop(L, CURBASE);
	      return 0;
	    }
	  }
	} else {
	  if (pv && pv->t == TAG_TAB) {
	    Val st = table_getstr(tabV2(*pv), luaP_newstr(L, "start", 5));
	    if (st.t == TAG_FUN) {
	      lpushval(L, st);
	      if (arg) lpushstring(L, arg);
	      ldocall(L, L->top - 1 - (arg ? 1 : 0), arg ? 1 : 0, 0);
	      lsettop(L, CURBASE);
	      return 0;
	    }
	  }
	}
      }
    }
  }
  lerrorstr_nopos("unknown luaJIT command or jit.* modules not installed");
  return 1; }

/* ---- -O handling ---- */
static const char *optflags[] = { "fold", "cse", "dce", "fwd", "dse", "narrow", "loop", "abc", "sink", "fuse", "fma", NULL };

int lj_dojitopt(Thread *L, const char *opt)
{ const char *p = opt;
  while (*p) {
    const char *e = strchr(p, ',');
    size_t len = e ? (size_t)(e - p) : strlen(p);
    char tok[64];
    if (len >= sizeof(tok)) len = sizeof(tok) - 1;
    memcpy(tok, p, len); tok[len] = 0;
    p = e ? e + 1 : p + strlen(p);
    if (*tok == 0) continue;
    if (isdigit((unsigned char)tok[0])) {
      /* a level: -O0..-O5 */
      continue;
    }
    if (tok[0] == '+' || tok[0] == '-') {
      const char *nm = tok + 1;
      int i, found = 0;
      for (i = 0; optflags[i]; i++) if (strcmp(optflags[i], nm) == 0) { found = 1; break; }
      if (!found) { char buf[128]; snprintf(buf, sizeof(buf), "unknown or malformed optimization flag '%s'", nm); lmessage(buf); return 1; }
      continue;
    }
    {
      char *eq = strchr(tok, '=');
      if (eq) {
	char nm[64];
	size_t nl = (size_t)(eq - tok);
	if (nl >= sizeof(nm)) nl = sizeof(nm) - 1;
	memcpy(nm, tok, nl); nm[nl] = 0;
	{ int i, found = 0;
	  for (i = 0; optflags[i]; i++) if (strcmp(optflags[i], nm) == 0) { found = 1; break; }
	  { int all_digits = (nm[0] != 0);
	    const char *q = nm;
	    while (*q) { if (!isdigit((unsigned char)*q)) { all_digits = 0; break; } q++; }
	    if (all_digits) found = 1; }
	  if (!found) { char buf[128]; snprintf(buf, sizeof(buf), "unknown or malformed optimization flag '%s'", tok); lmessage(buf); return 1; }
	}
	continue;
      }
      { int i, found = 0;
	for (i = 0; optflags[i]; i++) if (strcmp(optflags[i], tok) == 0) { found = 1; break; }
	if (!found) { char buf[128]; snprintf(buf, sizeof(buf), "unknown or malformed optimization flag '%s'", tok); lmessage(buf); return 1; } }
    }
  }
  return 0; }
